BEGIN;

INSERT INTO public.subjects (slug, name, description, color, sort_order)
VALUES ('g-kentei-g', 'G検定（JDLA ジェネラリスト検定） Set G 頻出補完',
        'JDLA G検定 対策 第7弾。機械学習の概要・ディープラーニングの概要/要素技術/応用例の4分野で、既存セットで未出だが問われがちな概念（強化学習の基本用語、次元の呪い、受容野、1x1畳み込み、TF-IDF、CTC、ViT、U-Netなど）を補完する。学習用オリジナル。',
        '#0B5CAB', 56)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT s.id, v.name, v.color, v.sort_order
FROM public.subjects s
CROSS JOIN (VALUES
  ('3. 機械学習の概要', '#3fb950', 0),
  ('4. ディープラーニングの概要', '#a371f7', 1),
  ('5. ディープラーニングの要素技術', '#d2a8ff', 2),
  ('6. ディープラーニングの応用例', '#f0883e', 3)
) AS v(name, color, sort_order)
WHERE s.slug = 'g-kentei-g'
ON CONFLICT (subject_id, name) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('g-kentei-g-q1', '3. 機械学習の概要',
   '強化学習では、行動を選ぶ主体と、行動の結果を返す側が向き合って学習が進む。行動した結果として「状態」と「報酬」を返す側の名称として最も適切なものはどれか。',
   NULL::text,
   '["環境", "エージェント", "方策", "価値関数"]',
   0, '[0]', 'single',
   '{"asked": "強化学習の登場人物のうち、行動の結果として状態と報酬を返す側の名前を選ぶ問題。", "point": "行動するのがエージェント、その行動を受け取って状態と報酬を返すのが環境。", "kid": "強化学習には2人の登場人物しかいない。行動を選ぶ側の「エージェント」と、その行動を受け止めて「次はこうなった」「これだけ点数をあげる」と返す側の「環境」。エージェントが動く→環境が反応する、この行ったり来たりを何度も繰り返して、エージェントは少しずつ賢くなる。", "eg": "たとえるなら、ゲームをプレイする人がエージェント、ゲーム機の中の世界（画面の状態やスコア表示）が環境。プレイヤーがボタンを押す（行動）と、ゲーム機が新しい画面（状態）とスコア（報酬）を返してくる。プレイヤー自身はゲームのルールを直接いじれず、ボタンを押すことしかできない。", "terms": [["エージェント", "行動を選んで実行する側。強化学習で賢くなっていく主役"], ["環境", "エージェントの行動を受け取り、次の状態と報酬を返す側"], ["状態", "今どんな状況にあるかを表す情報"], ["報酬", "その行動がどれだけ良かったかを表す数値"]], "think": "強化学習は「エージェントが行動する」→「環境が状態と報酬を返す」の繰り返しでできている。この向きを取り違えると混乱するので、まず「行動を出すのはエージェントだけ」「状態と報酬を返すのは環境だけ」と役割を固定して覚えるとよい。方策や価値関数は、エージェントの中にある「どう行動を選ぶか」の仕組みの名前であり、環境側の言葉ではない。", "vs": "方策・価値関数はどちらもエージェント内部で行動を決めるための道具の名前で、「状態と報酬を返す側」ではない。ここと混同すると誤答になる。", "why_asked": "強化学習の一番の基礎である用語の役割分担を、名前だけでなく矢印の向き（誰が何を渡すか）まで理解しているかを試している。", "usecase": "ロボット制御やゲームAIの設計で、まず「何がエージェントで何が環境か」を切り分けることが強化学習の設計の出発点になる。", "opt": ["正解。行動の結果として状態と報酬を返す側は環境。", "エージェントは行動を選ぶ側であり、状態と報酬を返す側ではない。", "方策はエージェントが行動を選ぶときのルールの名前で、環境ではない。", "価値関数はある状態や行動がどれだけ良いかを見積もる仕組みの名前で、環境ではない。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 130\" font-family=\"sans-serif\">\n<rect x=\"20\" y=\"30\" width=\"90\" height=\"40\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<text x=\"65\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">エージェント</text>\n<rect x=\"230\" y=\"30\" width=\"90\" height=\"40\" rx=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/>\n<text x=\"275\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">環境</text>\n<line x1=\"110\" y1=\"42\" x2=\"230\" y2=\"42\" stroke=\"#60a5fa\" stroke-width=\"1.5\" marker-end=\"url(#arG1)\"/>\n<text x=\"170\" y=\"36\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">行動</text>\n<line x1=\"230\" y1=\"60\" x2=\"110\" y2=\"60\" stroke=\"#c9a04a\" stroke-width=\"1.5\" marker-end=\"url(#arG2)\"/>\n<text x=\"170\" y=\"76\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">状態・報酬</text>\n<defs>\n<marker id=\"arG1\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#60a5fa\"/></marker>\n<marker id=\"arG2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#c9a04a\"/></marker>\n</defs>\n<text x=\"170\" y=\"108\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">エージェントが行動し、環境が状態と報酬を返す。この繰り返し</text>\n</svg>\n"}'),
  ('g-kentei-g-q2', '3. 機械学習の概要',
   '強化学習における「方策（policy）」と「価値関数」の違いとして最も適切なものはどれか。',
   NULL::text,
   '["方策は各状態でどの行動を選ぶかを決めるルールであり、価値関数はある状態や行動がどれだけ良いかを見積もる数値である", "方策はある状態や行動がどれだけ良いかを見積もる数値であり、価値関数はどの行動を選ぶかを決めるルールであり、両者の説明が入れ替わっている", "方策と価値関数はどちらも環境から返ってくる報酬そのものを指す同じ言葉であり、呼び方が違うだけである", "方策は学習の最初にだけ使われ、価値関数は学習の最後にだけ使われるという、使うタイミングだけの違いである"]',
   0, '[0]', 'single',
   '{"asked": "強化学習の「方策」と「価値関数」という2つの用語の役割の違いを選ぶ問題。", "point": "「行動を選ぶルール」なら方策、「良さを数値で見積もる」なら価値関数。", "kid": "方策は、今の状態を見て「次はこの行動をしよう」と決めるための、いわば行動マニュアル。価値関数は、ある状態や行動が「将来的にどれくらい得か」を点数で見積もる、いわば成績表。方策は行動を選ぶための道具、価値関数はその選択の善し悪しを測るための物差し、と役割が分かれている。", "eg": "たとえるなら、方策はカーナビの「次は右に曲がってください」という案内。価値関数は「このルートで行くとあと何分で着くか」という到着予測。案内（方策）と予測（価値関数）は別物で、予測を見ながら案内を作ることもできる。", "terms": [["方策（policy）", "各状態でどの行動を選ぶかを決めるルール"], ["価値関数", "ある状態や行動が将来的にどれだけ得かを数値で見積もる関数"], ["Q学習", "状態と行動の組の価値（Q値）を試行錯誤で更新していく代表的な強化学習手法"]], "think": "なぜこの2つを分けて考えるのかがカギ。もし「良さの見積もり」だけがあって「行動を選ぶルール」が無いと、エージエントは数値を知っていても実際に何をすればいいか決められない。逆に「行動を選ぶルール」だけで「良さの見積もり」が無いと、そのルールが良いのか悪いのか改善のしようがない。だから強化学習は、価値関数で良さを測りながら、その情報を使って方策を良くしていく、という2段構えで組み立てられている。", "vs": "「どちらも強化学習の中の数値っぽい概念だから似ている」と混同しやすいが、方策は行動という「選択」を出力し、価値関数は良さという「数値」を出力する。出力の種類が違う。", "why_asked": "強化学習の用語は似た響きが多く、役割を取り違えたまま暗記すると場面問題で崩れる。方策と価値関数は特に頻出の対比。", "usecase": "囲碁AIなどでは、価値関数で盤面の良さを評価しながら、その評価をもとに方策（次の一手）を改善していく設計が使われる。", "opt": ["正解。方策は行動を選ぶルール、価値関数は良さを見積もる数値で役割が異なる。", "方策と価値関数の説明が入れ替わっている。", "報酬は環境が返す数値そのものであり、方策や価値関数とは別の概念。", "方策も価値関数も学習全体を通じて使われ続ける道具であり、使うタイミングが分かれているわけではない。"]}'),
  ('g-kentei-g-q3', '3. 機械学習の概要',
   '強化学習の代表的な手法の一つで、状態と行動の組み合わせごとの価値（Q値）を、試行錯誤しながら少しずつ更新していく手法はどれか。',
   NULL::text,
   '["Q学習", "主成分分析", "k近傍法", "アンサンブル学習"]',
   0, '[0]', 'single',
   '{"asked": "状態と行動の組の価値（Q値）を試行錯誤で更新していく強化学習の代表手法の名前を選ぶ問題。", "point": "「状態と行動の組ごとにQ値という点数表を持ち、それを更新する」ならQ学習。", "kid": "Q学習は、「この状態でこの行動を取ったら、将来どれくらい得か」という点数（Q値）を、状態と行動の組み合わせごとに表にして持っておく手法。最初はでたらめな点数から始めて、実際に行動して報酬をもらうたびに、その点数を少しずつ正しい値に近づけて書き換えていく。この表が十分育つと、各状態で一番点数の高い行動を選べば、うまく立ち回れるようになる。", "eg": "たとえるなら、迷路のあらゆる分かれ道に「ここで右に行くと何点」というメモを貼っていく作業。最初は当てずっぽうの点数を貼っておき、実際に歩いて出口に近づけたら点数を書き直す。何度も歩くうちに、メモの点数がだんだん正確になり、点数の高い方を選ぶだけでゴールにたどり着けるようになる。", "terms": [["Q値", "ある状態である行動を取ったときの、将来的な良さを表す点数"], ["Q学習", "Q値を試行錯誤しながら更新していく代表的な強化学習手法"], ["方策", "各状態でどの行動を選ぶかを決めるルール。Q学習ではQ値が最大の行動を選ぶ形で方策が作られる"]], "think": "Q学習が何をしているかは「状態×行動」という組ごとに点数表を持ち、実際にやってみた結果（もらえた報酬と次の状態の点数）を使ってその点数を少しずつ書き直す、という一点に尽きる。この点数表が育てば育つほど、各状態で最も点数の高い行動を選ぶだけで良い行動が取れるようになる。だから「Q値を更新していく」という言葉が手法名にそのまま入っている。", "vs": "主成分分析・k近傍法・アンサンブル学習はいずれも教師あり学習や教師なし学習の手法で、報酬や試行錯誤という強化学習の要素を持たない。用語の並びに惑わされず「試行錯誤」「報酬」という言葉があるかで見分ける。", "why_asked": "強化学習の代表手法として名前と中身（Q値を更新する）をセットで覚えているかを試す定番の出題。", "usecase": "迷路探索やゲームの簡単なルール学習など、状態と行動の数が扱いきれる範囲であればQ学習の点数表がそのまま使える。", "opt": ["正解。状態と行動の組ごとのQ値を試行錯誤で更新していく手法はQ学習。", "主成分分析は次元削減の手法であり、Q値の更新とは無関係。", "k近傍法は教師あり学習の分類手法であり、試行錯誤による価値の更新とは無関係。", "アンサンブル学習は複数のモデルを組み合わせる手法の総称であり、Q値の更新とは無関係。"]}'),
  ('g-kentei-g-q4', '3. 機械学習の概要',
   '強化学習で、確率εのときだけランダムな行動を試し、それ以外はこれまでで一番よかった行動を選ぶという単純な工夫がある。この工夫の名称として最も適切なものはどれか。',
   NULL::text,
   '["ε-greedy法（たまにランダムに試す）", "k分割交差検証（データを分けて順番に評価する）", "グリッドサーチ（設定値の総当たり探索）", "バギング（多数決のアンサンブル学習）"]',
   0, '[0]', 'single',
   '{"asked": "確率εでランダムな行動を試し、それ以外は今までで一番よい行動を選ぶという強化学習の工夫の名前を選ぶ問題。", "point": "「小さな確率でわざと外れを試す」ならε-greedy法。", "kid": "強化学習のエージェントは、「今まで一番おいしいと分かっている行動」ばかり選び続けると、実はもっとおいしい行動があるのに気づけないままになってしまう。かといって毎回いろいろ試してばかりだと、せっかく見つけた良い行動を使わずに損してしまう。ε-greedy法は、ほとんどの回は今まで一番良いと分かっている行動を選び（活用）、たまに（確率ε）だけ思い切って別の行動を試す（探索）という、両方をバランスよく混ぜるやり方。", "eg": "たとえるなら、いつもの美味しいお店に行く（活用）か、たまには新しいお店を試してみる（探索）かの選び方。毎回いつもの店ばかりだと、もっと美味しい店を見逃したままになる。逆に毎回新しい店ばかりだと、せっかく見つけたお気に入りの店を楽しめない。だから「10回に1回くらいは新しい店に挑戦する」というルールを決めておく、というのがε-greedy法の考え方。", "terms": [["探索（exploration）", "まだ試していない行動を試して、新しい情報を得ようとすること"], ["活用（exploitation）", "これまでで一番良いと分かっている行動を選ぶこと"], ["ε-greedy法", "確率εで探索、それ以外は活用を行う、探索と活用を両立させる代表的な工夫"]], "think": "なぜ両方が要るのかがカギ。活用だけだと、たまたま最初に見つけた「まあまあの行動」に固定されてしまい、実はもっと良い行動があっても一生気づけない。探索だけだと、せっかく良い行動を見つけてもすぐ別のものを試してしまい、良い行動を活かしきれない。ε-greedy法は、ほとんどの回で確実に良い方（活用）を選びつつ、小さな確率εだけ思い切って別の行動（探索）を混ぜることで、この両方の弱点を同時に防いでいる。だから探索と活用のトレードオフの定番の解決策になっている。", "vs": "k分割交差検証・グリッドサーチ・バギングはいずれも評価やハイパーパラメータ探索、アンサンブルの手法であり、強化学習の「行動選択の最中の探索と活用」を扱う仕組みではない点で異なる。", "why_asked": "強化学習特有の「探索と活用のトレードオフ」という考え方と、その代表的な対処法の名前をセットで覚えているかを試す。", "usecase": "広告のクリック率最適化（どの広告を出すか毎回選ぶ問題）など、行動を繰り返し選び続ける場面でε-greedy法のような探索と活用のバランスが使われる。", "opt": ["正解。確率εで探索、それ以外は活用を行う工夫はε-greedy法。", "k分割交差検証はモデルの評価方法であり、行動選択時の探索と活用の話ではない。", "グリッドサーチはハイパーパラメータの候補を総当たりで試す方法であり、行動選択の工夫ではない。", "バギングは複数のモデルを組み合わせるアンサンブル学習の手法であり、探索と活用の工夫ではない。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 140\" font-family=\"sans-serif\">\n<text x=\"8\" y=\"14\" font-size=\"9\" fill=\"#e8eaf0\">活用（exploitation）＝いつもの店</text>\n<rect x=\"10\" y=\"24\" width=\"60\" height=\"60\" rx=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/>\n<text x=\"40\" y=\"58\" text-anchor=\"middle\" font-size=\"20\" fill=\"#6ab08d\">★</text>\n<text x=\"40\" y=\"98\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">確実に80点</text>\n\n<text x=\"175\" y=\"14\" font-size=\"8\" fill=\"#e8eaf0\">探索（exploration）＝新しい店</text>\n<rect x=\"185\" y=\"24\" width=\"60\" height=\"60\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>\n<text x=\"215\" y=\"58\" text-anchor=\"middle\" font-size=\"20\" fill=\"#c9a04a\">?</text>\n<text x=\"215\" y=\"98\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">30点かも100点かも</text>\n\n<text x=\"127\" y=\"58\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8892a4\">or</text>\n\n<rect x=\"10\" y=\"112\" width=\"235\" height=\"14\" rx=\"2\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<rect x=\"10\" y=\"112\" width=\"211\" height=\"14\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n<rect x=\"221\" y=\"112\" width=\"24\" height=\"14\" fill=\"#c47070\" opacity=\"0.7\"/>\n<text x=\"115\" y=\"122\" text-anchor=\"middle\" font-size=\"8\" fill=\"#e8eaf0\">確率1-ε：活用</text>\n<text x=\"233\" y=\"136\" text-anchor=\"middle\" font-size=\"8\" fill=\"#c47070\">確率ε：探索</text>\n</svg>\n"}'),
  ('g-kentei-g-q5', '3. 機械学習の概要',
   '同じ件数のデータのまま、扱う特徴量（項目）の数だけを増やしていくと、データ点どうしの間隔がまばらになり、距離や密度に基づく学習がうまく働きにくくなる。この現象の名称として最も適切なものはどれか。',
   NULL::text,
   '["次元の呪い", "過学習", "勾配消失", "データリーケージ"]',
   0, '[0]', 'single',
   '{"asked": "特徴量（項目）の数を増やすほどデータがまばらになり、学習が働きにくくなる現象の名前を選ぶ問題。", "point": "「項目を増やすほど同じ点数ではスカスカになる」なら次元の呪い。", "kid": "次元とは、データを表すのに使う項目の数のこと（身長だけなら1次元、身長と体重なら2次元…）。項目を1つ増やすたびに、データを置ける「空間」がどんどん広がっていく。ところが、データの件数は増えないままなので、同じ数の点を広くなった空間に置くと、点と点の間がスカスカに離れていってしまう。これが「次元の呪い」。", "eg": "たとえるなら、4人の友達を1本の廊下（1次元）に立たせるとぎっしり並ぶが、同じ4人を体育館（2次元）に立たせると間隔がまばらになり、さらに巨大な野球場（もっと高い次元）に立たせるとほとんど誰も近くにいない状態になる。人数（データ件数）は変わらないのに、空間（次元）が広がるほど「近くに仲間がいる」という状況が作りにくくなる。", "terms": [["次元", "データを表すのに使う項目（特徴量）の数"], ["次元の呪い", "次元が増えるほど、同じデータ件数では点どうしがまばらになり、距離や密度に頼る手法が効きにくくなる現象"], ["k近傍法", "近くのデータ点を見て判断する手法。次元の呪いの影響を特に受けやすい代表例"]], "think": "なぜ次元が増えるとまばらになるのかがカギ。項目を1つ増やすごとに、データを置ける空間の広さはかけ算的に膨らんでいく。一方でデータの件数はそのままなので、同じ件数の点を、どんどん広がる空間に置くことになる。空間の広がる速さに対してデータの増える速さが追いつかないので、点どうしの間隔は必然的に開いていく。距離や近さを手がかりにする手法（k近傍法など）は「近くに似た点がある」ことを前提にしているため、この現象が起きると急に精度が落ちる。", "vs": "過学習は訓練データに合わせすぎて未知データで精度が落ちる現象、勾配消失はニューラルネットの学習の合図が層を伝わるうちに小さくなる現象、データリーケージは本来使えない情報が紛れ込む問題で、いずれも「項目数を増やすとデータがまばらになる」という次元の呪いとは別の現象。", "why_asked": "特徴量を増やせば増やすほど精度が上がると誤解しやすいが、実際には項目を増やしすぎるとかえって学習が難しくなるという注意点を理解しているかを試す。", "usecase": "画像や遺伝子データのように項目数が非常に多いデータを扱う前に、主成分分析などで次元削減を行い、次元の呪いの影響を弱める、といった判断につながる。", "opt": ["正解。項目数（次元）が増えるほど同じデータ件数では点がまばらになる現象は次元の呪い。", "過学習は訓練データに合わせすぎて未知データでの精度が落ちる現象であり、項目数の増加そのものの話ではない。", "勾配消失はニューラルネットの学習信号が層を経るうちに小さくなる現象であり、次元とは無関係。", "データリーケージは本来使えないはずの情報が学習に紛れ込む問題であり、次元の増加とは無関係。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 140\" font-family=\"sans-serif\">\n<text x=\"60\" y=\"14\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">1次元：線</text>\n<line x1=\"15\" y1=\"40\" x2=\"105\" y2=\"40\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/>\n<circle cx=\"25\" cy=\"40\" r=\"3\" fill=\"#3b82f6\"/>\n<circle cx=\"45\" cy=\"40\" r=\"3\" fill=\"#3b82f6\"/>\n<circle cx=\"65\" cy=\"40\" r=\"3\" fill=\"#3b82f6\"/>\n<circle cx=\"85\" cy=\"40\" r=\"3\" fill=\"#3b82f6\"/>\n<text x=\"60\" y=\"58\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">4点でぎっしり</text>\n\n<text x=\"215\" y=\"14\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">2次元：面</text>\n<rect x=\"170\" y=\"24\" width=\"90\" height=\"34\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/>\n<circle cx=\"185\" cy=\"35\" r=\"3\" fill=\"#3b82f6\"/>\n<circle cx=\"250\" cy=\"50\" r=\"3\" fill=\"#3b82f6\"/>\n<circle cx=\"200\" cy=\"52\" r=\"3\" fill=\"#3b82f6\"/>\n<circle cx=\"240\" cy=\"30\" r=\"3\" fill=\"#3b82f6\"/>\n<text x=\"215\" y=\"70\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">同じ4点でスカスカ</text>\n\n<rect x=\"20\" y=\"88\" width=\"300\" height=\"16\" rx=\"2\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<rect x=\"20\" y=\"88\" width=\"270\" height=\"16\" fill=\"#c47070\" opacity=\"0.5\"/>\n<text x=\"170\" y=\"100\" text-anchor=\"middle\" font-size=\"8\" fill=\"#e8eaf0\">次元が増えるほど、同じ点数では空間がスカスカに</text>\n<text x=\"170\" y=\"124\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">これが「次元の呪い」</text>\n</svg>\n"}'),
  ('g-kentei-g-q6', '3. 機械学習の概要',
   '1枚の画像に「犬」「猫」「鳥」のうちどれか1つだけを割り当てるタスクと、1本のニュース記事に「政治」「経済」「スポーツ」のうち当てはまるものをいくつでも割り当てるタスクがある。この2つのタスクの呼び分けとして最も適切なものはどれか。',
   NULL::text,
   '["1つだけ選ぶ前者は多クラス分類、複数選べる後者は多ラベル分類と呼ばれ、1データにいくつ正解を割り当てられるかが違う", "1つだけ選ぶ前者は多ラベル分類、複数選べる後者は多クラス分類と呼ばれ、正解の個数に対する2つの呼び方が逆になっている", "どちらも同じ「多クラス分類」という1つの呼び方で扱われ、選べる個数による呼び分けは存在しない", "前者は教師あり学習、後者は教師なし学習という、学習方式そのものの違いであり、正解の個数とは関係がない"]',
   0, '[0]', 'single',
   '{"asked": "「1つだけ選ぶ分類」と「複数選べる分類」というタスクの呼び分け方を選ぶ問題。", "point": "「1データに正解1つ」なら多クラス分類、「1データに正解いくつでも」なら多ラベル分類。", "kid": "多クラス分類は、選択肢がいくつあっても、1つのデータには正解を1つだけ割り当てるタスク（犬か猫か鳥か、どれか1つに決める）。多ラベル分類は、1つのデータに当てはまる正解を複数同時に割り当ててよいタスク（このニュースは政治でもあり経済でもある、のように）。「選択肢が2つより多いかどうか」ではなく、「1つのデータに正解をいくつ付けてよいか」が違いのポイント。", "eg": "たとえるなら、多クラス分類は「今日の主食はご飯・パン・麺のうちどれか1つを選ぶ」ような、必ず1つに絞る場面。多ラベル分類は「このお弁当に入っているおかずを、肉・魚・野菜の中から当てはまるもの全部選ぶ」ような、複数選んでよい場面。前者は択一、後者は該当するもの全部という違い。", "terms": [["多クラス分類", "3つ以上の選択肢から1つだけを選ぶ分類タスク"], ["多ラベル分類", "1つのデータに複数の正解ラベルを同時に割り当ててよい分類タスク"], ["二値分類", "選択肢が2つだけの分類タスク（多クラス分類の中でも選択肢が2つの特別な場合）"]], "think": "見分け方は「1つのデータに正解が何個付くか」という一点。選択肢の数がいくつあっても、最終的にどれか1つに決めるなら多クラス分類。選択肢の中から当てはまるものをいくつでも選べるなら多ラベル分類。「選択肢が3つ以上あるかどうか」で判断すると、多ラベル分類も選択肢は複数あるため混同しやすいので注意する。", "vs": "多クラス分類と多ラベル分類は名前が似ているため取り違えやすい。多クラス分類は「クラス（選択肢）が多い」という選択肢側の話、多ラベル分類は「ラベル（正解の個数）が多くてよい」という正解の付け方側の話、と言葉の由来から区別すると覚えやすい。", "why_asked": "分類タスクを設計するとき、正解が必ず1つなのか複数あり得るのかを見誤ると、モデルの出力の作り方（確率の合計を1にするか、しないか）ごと間違えてしまうため、この区別は実務上も重要視される。", "usecase": "画像に写っている動物の種類を1つ特定するなら多クラス分類、1枚の写真に写っている複数の物体タグを全部付けるなら多ラベル分類、といった設計判断で使われる。", "opt": ["正解。1つだけ選ぶのは多クラス分類、複数選べるのは多ラベル分類で、正解の個数の違いを表す呼び分け。", "多クラス分類と多ラベル分類の説明が入れ替わっている。", "選べる個数によって呼び方は明確に分かれており、同じ1つの呼び方でまとめられるものではない。", "どちらも正解ラベルを使って学習する教師あり学習であり、教師あり・教師なしの違いではない。"]}'),
  ('g-kentei-g-q7', '3. 機械学習の概要',
   '回帰モデルの評価指標であるMAEとRMSEは、どちらも予測値と正解値のズレの大きさを表すが、外れ値（大きく外した1件）への反応の仕方が異なる。この違いとして最も適切なものはどれか。',
   NULL::text,
   '["RMSEはズレを2乗してから平均するため、大きく外した1件の影響を強く受けて跳ね上がりやすいが、MAEはズレをそのまま平均するため影響が緩やか", "MAEはズレを2乗してから平均するため外れ値に敏感で、RMSEはズレをそのまま平均するため外れ値に鈍感であり、両者の説明がちょうど反対に入れ替わっている", "MAEとRMSEはどちらもズレを2乗してから平均する同じ計算方法であり、外れ値への反応の仕方に違いは生まれない", "MAEとRMSEはどちらも予測が正解より大きいか小さいかという向きだけを見る指標であり、外れ値の大きさそのものは反映されない"]',
   0, '[0]', 'single',
   '{"asked": "回帰の評価指標MAEとRMSEの、外れ値への反応の違いを選ぶ問題。", "point": "「2乗してから平均」＝RMSEは外れ値に敏感、「そのまま平均」＝MAEは外れ値に鈍感。", "kid": "MAE（Mean Absolute Error、平均絶対誤差）は、予測と正解のズレの大きさ（プラスマイナスを外した絶対値）をそのまま平均したもの。RMSE（Root Mean Squared Error、平方根平均二乗誤差）は、ズレを一度2乗してから平均し、最後に平方根（2乗の逆の計算）を取ったもの。2乗するかどうかがカギで、2乗すると大きいズレはさらに大きく膨らむので、たった1件でも大きく外した予測があると、RMSEはその1件に強く引っ張られて値が跳ね上がる。MAEはそのまま平均するだけなので、そこまで極端には反応しない。", "eg": "たとえるなら、5人のテストの間違い直しの点数を集計するとき、MAEは「間違えた点数をそのまま足して平均する」やり方。RMSEは「間違えた点数を一度2乗してから足して平均し、最後に平方根で戻す」やり方。1人だけ大失敗して大きくズレていた場合、2乗するRMSEはその1人の失敗が全体の平均を大きく押し上げてしまう。そのまま足すMAEは、その1人の分だけ律儀に足されるだけで、跳ね上がり方はRMSEほど極端にならない。", "terms": [["MAE（Mean Absolute Error、平均絶対誤差）", "直訳は「平均の・絶対の・誤差」。ズレの絶対値をそのまま平均した指標"], ["RMSE（Root Mean Squared Error、平方根平均二乗誤差）", "直訳は「根・平均・2乗された・誤差」。ズレを2乗して平均し、最後に平方根を取った指標"], ["外れ値", "他のデータから大きく離れた値。1件だけ極端に大きい・小さいデータ"]], "think": "なぜ2乗するかどうかで反応が変わるのかがカギ。ズレが2（小さい失敗）なら2乗しても4で、そこまで大きくは増えない。しかしズレが20（大きな失敗）だと2乗すると400になり、一気に膨れ上がる。RMSEはこの2乗した値を平均してから平方根で戻すので、大きなズレ1件の影響が計算の途中で膨らんだまま最終結果に色濃く残る。MAEは2乗せずそのまま平均するだけなので、大きなズレも「その分だけ」しか効かない。だからRMSEは外れ値に敏感、MAEは外れ値に鈍感、という性質の違いが生まれる。", "vs": "「どちらも誤差の平均だから同じような値になる」と思い込みやすいが、外れ値が1件でもあるとRMSEの方がMAEより大きく跳ね上がる。両方を並べて見て差が大きいときは、外れ値の存在を疑うという読み方ができる。", "why_asked": "評価指標の定義を暗記しているだけでは、外れ値がある場面でどちらを重視すべきかという実務的な判断ができない。この因果（2乗するから敏感になる）まで理解しているかを試す。", "usecase": "外れ値を厳しく罰したい（大失敗を絶対避けたい）場面ではRMSEを重視し、外れ値の影響を受けすぎたくない（多少の大失敗より全体の安定を見たい）場面ではMAEを重視する、といった指標の選び方に直結する。", "opt": ["正解。RMSEは2乗してから平均するため外れ値に敏感、MAEはそのまま平均するため外れ値に鈍感。", "MAEとRMSEの説明が入れ替わっている。2乗して平均するのはRMSEの方。", "MAEはズレを2乗せずそのまま平均する指標であり、RMSEと同じ計算方法ではない。", "MAEもRMSEもズレの大きさ（絶対値や2乗）を見る指標であり、向き（プラスかマイナスか）だけを見るものではない。"], "calc": "予測と正解のズレが [2, 2, 2, 20] の4件だったとして、MAEとRMSEを比べてみる。①日本語で言うと：MAEはズレをそのまま平均、RMSEはズレを2乗して平均し、最後に平方根（2乗の逆の計算。例えば4の平方根は2）を取る。②小さい数字でステップを追う：MAEはまず (2+2+2+20)÷4 を計算する。合計は26、4件で割ると26÷4=6.5。これがMAE。RMSEはまず各ズレを2乗する：2の2乗=4、2の2乗=4、2の2乗=4、20の2乗=400。これを平均する：(4+4+4+400)÷4=412÷4=103。最後に103の平方根を取ると、だいたい10.1になる。これがRMSE。③記号で書くと、n件のズレを e とすると、MAE = (|e1|+|e2|+…+|en|)÷n、RMSE = √{(e1²+e2²+…+en²)÷n}。同じデータなのにMAEが6.5、RMSEが10.1と大きく開いたのは、20という1件の大きなズレが2乗されて400まで膨らみ、RMSEを強く押し上げたため。"}'),
  ('g-kentei-g-q8', '3. 機械学習の概要',
   '決定木がどの項目・どの値で枝分かれさせるかを選ぶとき、情報利得やジニ不純度といった指標が使われる。これらの指標が測っているものとして最も適切なものはどれか。',
   NULL::text,
   '["分割した後の各グループに、異なるクラスのデータがどれだけ混ざらずに、同じクラスだけに揃っているか（純粋さ）", "分割した後の各グループに含まれるデータの件数が、左右のグループでどれだけぴったり同じ数に均等に揃っているかどうか", "分割に使う項目（特徴量）の値が、どれだけ大きい数値であるか", "木の深さ（根から葉までの枝分かれの回数）が、あらかじめ決めた上限に達しているかどうか"]',
   0, '[0]', 'single',
   '{"asked": "決定木の分割基準（情報利得・ジニ不純度）が実際に何を測っているかを選ぶ問題。", "point": "「分けた後、同じクラスだけに揃っているか」を測るなら情報利得・ジニ不純度。", "kid": "決定木は、データをある条件（例えば「年齢は30歳以上か」）で2つのグループに分けていく手法。同じ条件でも、分け方次第では「合格の人も不合格の人も半々に混ざったグループ」になることもあれば、「ほぼ合格の人だけが集まったグループ」になることもある。情報利得やジニ不純度は、分けた後の各グループが「どれだけ1種類のクラスだけに揃っているか（純粋か）」を数値にした指標で、この数値が良くなる分け方を決定木は選んでいく。", "eg": "たとえるなら、クラスの生徒を「好きな科目」で2つの部屋に分けるとき、片方の部屋に理系好きだけが集まり、もう片方に文系好きだけが集まったら「きれいに分かれた（純粋）」。両方の部屋に理系好きと文系好きが半々ずつ混ざっていたら「あまり分かれていない（混ざっている・不純）」。情報利得やジニ不純度は、この「きれいに分かれた度合い」を測るものさし。", "terms": [["不純度", "1つのグループの中に、異なるクラスがどれだけ混ざっているかを表す度合い。低いほど1種類に揃っている"], ["ジニ不純度", "不純度を測る代表的な計算方法の1つ"], ["情報利得", "分割の前後で不純度がどれだけ減ったか（＝どれだけきれいになったか）を表す指標"]], "think": "なぜ「純粋さ」を測る必要があるのかがカギ。決定木は最終的に、1つのグループに対して「このグループは合格」「このグループは不合格」のように1つの答えを出したい。もし分けた後のグループに合格・不合格が半々に混ざっていたら、そのグループに対して自信を持って1つの答えを出せない。逆に、分けた後のグループがほぼ1種類のクラスだけになっていれば、そのグループの答えとして自信を持って1つを出せる。だから決定木は、分けるたびに「どれだけ純粋になったか」を測る情報利得やジニ不純度を使い、それが最も良くなる分け方を選んでいく。", "vs": "件数の均等さ・項目の値の大きさ・木の深さの上限は、いずれも分割の「純粋さ」とは別の話。特に「左右の件数を揃える」ことと「クラスを揃える」ことは違う概念で、情報利得やジニ不純度が測っているのは後者。", "why_asked": "決定木の分割基準の名前（情報利得・ジニ不純度）だけを覚えていても、それが実際に何を測っているかを説明できないと、木がなぜそのように分岐するのかを理解できない。", "usecase": "決定木やランダムフォレストのモデルがどの項目を重要視して分岐したかを確認するとき、その分岐が情報利得やジニ不純度の改善に基づいて選ばれていることを理解していると、モデルの判断根拠を読み解きやすくなる。", "opt": ["正解。情報利得・ジニ不純度は、分割後の各グループがどれだけ同じクラスだけに揃っているか（純粋さ）を測る。", "件数を左右で揃えることと、クラスを揃えることは別の話。情報利得やジニ不純度が測るのは後者。", "項目の値の大きさそのものではなく、その値で分けた結果どれだけクラスが揃うかを測っている。", "木の深さの上限は分割の回数を制限する別のパラメータであり、情報利得やジニ不純度が測るものではない。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 140\" font-family=\"sans-serif\">\n<text x=\"60\" y=\"14\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">分け方A：混ざったまま</text>\n<rect x=\"15\" y=\"24\" width=\"90\" height=\"34\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<circle cx=\"30\" cy=\"41\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"45\" cy=\"35\" r=\"3\" fill=\"#c47070\"/>\n<circle cx=\"60\" cy=\"45\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"75\" cy=\"35\" r=\"3\" fill=\"#c47070\"/>\n<circle cx=\"90\" cy=\"45\" r=\"3\" fill=\"#3b82f6\"/>\n<rect x=\"15\" y=\"64\" width=\"90\" height=\"34\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<circle cx=\"30\" cy=\"81\" r=\"3\" fill=\"#c47070\"/><circle cx=\"45\" cy=\"75\" r=\"3\" fill=\"#3b82f6\"/>\n<circle cx=\"60\" cy=\"85\" r=\"3\" fill=\"#c47070\"/><circle cx=\"75\" cy=\"75\" r=\"3\" fill=\"#3b82f6\"/>\n<text x=\"60\" y=\"112\" text-anchor=\"middle\" font-size=\"7\" fill=\"#8892a4\">色が混ざる→不純度が高い</text>\n\n<text x=\"245\" y=\"14\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">分け方B：きれいに分かれた</text>\n<rect x=\"200\" y=\"24\" width=\"90\" height=\"34\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/>\n<circle cx=\"215\" cy=\"41\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"230\" cy=\"35\" r=\"3\" fill=\"#3b82f6\"/>\n<circle cx=\"245\" cy=\"45\" r=\"3\" fill=\"#3b82f6\"/><circle cx=\"260\" cy=\"35\" r=\"3\" fill=\"#3b82f6\"/>\n<circle cx=\"275\" cy=\"45\" r=\"3\" fill=\"#3b82f6\"/>\n<rect x=\"200\" y=\"64\" width=\"90\" height=\"34\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/>\n<circle cx=\"215\" cy=\"81\" r=\"3\" fill=\"#c47070\"/><circle cx=\"230\" cy=\"75\" r=\"3\" fill=\"#c47070\"/>\n<circle cx=\"245\" cy=\"85\" r=\"3\" fill=\"#c47070\"/><circle cx=\"260\" cy=\"75\" r=\"3\" fill=\"#c47070\"/>\n<text x=\"245\" y=\"112\" text-anchor=\"middle\" font-size=\"7\" fill=\"#8892a4\">1色だけ→不純度が低い＝良い分割</text>\n</svg>\n"}'),
  ('g-kentei-g-q9', '3. 機械学習の概要',
   '勾配ブースティング（前の学習器の間違いを次の学習器が補正しながら順番に木を追加していく手法）を高速かつ高精度に実装したライブラリとして、実務でよく使われるものはどれか。',
   NULL::text,
   '["XGBoost", "TensorFlow", "OpenCV", "scikit-learn の k-means実装"]',
   0, '[0]', 'single',
   '{"asked": "勾配ブースティングを高速・高精度に実装した、実務でよく使われるライブラリの名前を選ぶ問題。", "point": "「勾配ブースティングを速く正確に動かす専用ツール」ならXGBoostやLightGBM。", "kid": "勾配ブースティングは、簡単な決定木を1本作り、その木がまだ間違えている部分を次の木で補い、さらにその次の木で補い…と、木を順番に追加していって全体の精度を上げていく手法。XGBoostやLightGBMは、この仕組みをコンピュータの中でとても速く、かつ高い精度で動かせるように作られた、実務で定番のライブラリ。コンペや実際の業務のテーブルデータ分析で頻繁に使われる。", "eg": "たとえるなら、テストの採点で「1人目の先生が採点し、間違えやすい問題だけ2人目の先生がもう一度見直し、それでも残るミスを3人目がまた見直す」というリレー形式の採点システムを、とても効率よく動かす専用ソフトのようなもの。木を1本ずつ追加して弱点を補っていく仕組み自体が勾配ブースティングで、XGBoostやLightGBMはそれを高速に計算してくれる道具。", "terms": [["勾配ブースティング", "前の学習器の間違いを次の学習器が補正しながら、木を順番に追加していく手法"], ["XGBoost（Extreme Gradient Boosting）", "直訳は「極限の・勾配・後押し」。勾配ブースティングを高速・高精度に実装した定番ライブラリ"], ["LightGBM", "XGBoostと並ぶ、勾配ブースティングの高速な実装ライブラリ"]], "think": "テーブルデータ（表形式のデータ）を扱う実務のコンテストや分析では、勾配ブースティングの精度の高さが繰り返し実証されてきた。ただし勾配ブースティングという「考え方」そのものと、それを実際に動かす「道具（ライブラリ）」は別物で、XGBoostやLightGBMはその道具にあたる。TensorFlowはニューラルネットワーク全般を組み立てるための道具、OpenCVは画像処理のための道具であり、勾配ブースティングの専用ツールではない。", "vs": "TensorFlowはディープラーニング全般の枠組みであり、勾配ブースティングの専用ライブラリではない。OpenCVは画像処理のためのライブラリで学習手法そのものではない。k-meansはクラスタリング手法であり勾配ブースティングとは別物。", "why_asked": "G検定では手法の名前だけでなく、実務でどのツールが結びついているかという実装レベルの知識も問われる。勾配ブースティング＝XGBoost/LightGBMという対応は頻出。", "usecase": "売上予測や与信審査のようなテーブルデータの予測タスクで、精度と速度のバランスが良いXGBoostやLightGBMが実務の定番として選ばれる。", "opt": ["正解。勾配ブースティングを高速・高精度に実装した実務定番ライブラリはXGBoost（LightGBMも同様）。", "TensorFlowはニューラルネットワークを組み立てるための枠組みであり、勾配ブースティング専用のライブラリではない。", "OpenCVは画像処理のためのライブラリであり、勾配ブースティングの実装ではない。", "k-meansはクラスタリング（教師なし学習）の手法であり、勾配ブースティングとは別の手法。"]}'),
  ('g-kentei-g-q10', '3. 機械学習の概要',
   'ハイパーパラメータの探索方法である「グリッドサーチ」「ランダムサーチ」「ベイズ最適化」の説明として最も適切なものはどれか。',
   NULL::text,
   '["グリッドサーチは総当たりで試し、ランダムサーチはランダムに選んで試し、ベイズ最適化はこれまでの結果を踏まえて次の値を賢く選ぶ", "グリッドサーチ・ランダムサーチ・ベイズ最適化はいずれも同じ総当たりの計算をしており、探索の順番が違うだけで結果は常に同じになる", "グリッドサーチは結果を踏まえて次の値を賢く選び、ベイズ最適化は候補を総当たりで試すという、両者の説明が入れ替わっている", "この3つはすべてクラスタリングの手法の名称であり、ハイパーパラメータの探索とは無関係である"]',
   0, '[0]', 'single',
   '{"asked": "3つのハイパーパラメータ探索方法（グリッドサーチ・ランダムサーチ・ベイズ最適化）の違いを選ぶ問題。", "point": "「総当たり」はグリッド、「ランダムに選ぶ」はランダムサーチ、「結果を踏まえて賢く選ぶ」はベイズ最適化。", "kid": "ハイパーパラメータとは、モデルを作る前に人間があらかじめ決めておく設定値（木の深さ、学習率など）のこと。この設定値の良い組み合わせを探す方法が3つある。グリッドサーチは候補をすべて格子状に並べて、しらみつぶしに全部試す方法。ランダムサーチは候補の中からくじ引きのようにランダムに選んで試す方法。ベイズ最適化は、これまで試した結果を踏まえて「次はこのあたりが良さそうだ」と予想しながら、賢く次の候補を選んでいく方法。", "eg": "たとえるなら、宝物が埋まっている畑を探すとき、グリッドサーチは畑をマス目に区切って端から順番に全マスを掘る方法。ランダムサーチはマス目を無視してくじ引きで掘る場所を決める方法。ベイズ最適化は、これまで掘った場所の手応え（近くに宝がありそうか）を踏まえて、次に掘る場所を予想しながら決めていく、一番効率のよい掘り方。", "terms": [["グリッドサーチ", "候補の組み合わせを格子状に並べ、総当たりで試す探索方法"], ["ランダムサーチ", "候補の中からランダムに選んで試す探索方法"], ["ベイズ最適化", "これまでの試行結果を踏まえて、次に試す値を確率的に賢く選ぶ探索方法"]], "think": "3つの違いは「次にどこを試すかをどう決めるか」という一点に集約できる。グリッドサーチは決めた候補を機械的に全部試すので、候補が多いと時間がかかりすぎる。ランダムサーチはくじ引きで選ぶので全部は試さないが、良い場所を逃す可能性もある一方、意外と広い範囲を効率よくカバーできることが知られている。ベイズ最適化は、それまでの結果から「良さそうな場所」を予測しながら次を選ぶので、少ない試行回数で良い組み合わせに近づきやすい。試行回数をかけられるか、時間を節約したいかで使い分ける。", "vs": "グリッドサーチとランダムサーチは「候補の選び方が機械的か、くじ引きか」の違いで、どちらも過去の結果を次の選択に活かさない。ベイズ最適化だけが過去の結果を使って賢く次を選ぶ点で性質が異なる。", "why_asked": "3つの探索方法の名前を暗記していても、それぞれの「候補の選び方」の違いを説明できるかが問われる。特にベイズ最適化の「過去の結果を活かす」という特徴が頻出のポイント。", "usecase": "候補の数が少なく計算資源に余裕があるならグリッドサーチ、候補が多く手早く探りたいならランダムサーチ、試行に時間やコストがかかり効率よく最良点に近づきたいならベイズ最適化が選ばれる。", "opt": ["正解。グリッドサーチは総当たり、ランダムサーチはランダムに選択、ベイズ最適化は結果を踏まえて賢く選ぶ。", "3つの方法は候補の選び方が異なり、同じ結果になるとは限らない。", "グリッドサーチとベイズ最適化の説明が入れ替わっている。", "3つとも教師あり学習のハイパーパラメータを探索する方法であり、クラスタリングの手法ではない。"]}'),
  ('g-kentei-g-q11', '3. 機械学習の概要',
   '文章の一部の単語を隠し、その隠した単語を周囲の文脈から予測させるというタスクのように、人が正解ラベルを付けなくても、データ自身の一部を隠したり加工したりして「問題と正解のペア」を自動的に作り出す学習方式はどれか。',
   NULL::text,
   '["自己教師あり学習", "強化学習", "ハードマージンSVM", "階層的クラスタリング"]',
   0, '[0]', 'single',
   '{"asked": "データ自身を加工して問題と正解のペアを自動的に作り出す学習方式の名前を選ぶ問題。", "point": "「人がラベルを付けず、データ自身の一部を隠して問題と正解を自動生成する」なら自己教師あり学習。", "kid": "教師あり学習には、人間が用意した正解ラベルが必要だった。しかし正解ラベルを人手で付けるのは時間もお金もかかる。自己教師あり学習は、人が正解を付けなくても、データそのものの一部をわざと隠したり入れ替えたりして、「隠した部分を当てる」という問題を自動的に作り出す方法。隠す前の元のデータがそのまま正解になるので、ラベル付けの手間なしに教師あり学習と同じような訓練ができる。", "eg": "たとえるなら、1冊の本の文章の一部の単語を付箋で隠して、「この付箋の下に何が書いてあるか当ててみて」というクイズを大量に作る作業。付箋を貼るのも、答え合わせをするのも、元の本さえあれば全部自動でできる。誰かに正解を教えてもらう必要がない。", "terms": [["自己教師あり学習", "データ自身を加工して問題と正解のペアを自動生成し、人手のラベル付けなしに学習する方式"], ["穴埋め予測（マスク言語モデル）", "文章の一部の単語を隠し、周囲の文脈から当てさせる自己教師あり学習の代表的なタスク"], ["半教師あり学習", "少量のラベル付きデータと大量のラベルなしデータを組み合わせる学習方式。自己教師あり学習とは別物"]], "think": "なぜ「自己」教師あり、という名前なのかがカギ。教師あり学習では人間が外から正解ラベルを与える。自己教師あり学習では、データ自身の一部を隠すという操作によって、データ自身が自分の正解（隠す前の姿）を兼ねている。つまり教師役を人間ではなくデータ自身が務めているという意味で「自己教師あり」と呼ばれる。この仕組みのおかげで、ラベル付けにお金や時間をかけずに、大量の未加工データだけで教師あり学習と同じ形の訓練ができる。", "vs": "半教師あり学習は「少量のラベル付き＋大量のラベルなし」を組み合わせる方式で、人手のラベルが一部は必要な点が自己教師あり学習と異なる。自己教師あり学習は人手のラベルを一切使わずに問題と正解を自動生成する点が特徴。", "why_asked": "近年の大規模言語モデルの事前学習の多くが自己教師あり学習に基づいており、なぜ大量のラベルなしデータだけで学習が進められるのかという理屈を理解しているかを試す。", "usecase": "大規模言語モデルの事前学習（文章の穴埋めや次の単語予測）や、画像の一部を隠して復元させる事前学習など、ラベル付けが難しい大量データの活用に使われる。", "opt": ["正解。データ自身の一部を隠して問題と正解のペアを自動生成する学習方式は自己教師あり学習。", "強化学習は行動と報酬を手がかりに学ぶ方式であり、データを隠して正解を自動生成する仕組みとは異なる。", "ハードマージンSVMは分類の境界線を引く教師あり学習の手法であり、正解ラベルの自動生成とは無関係。", "階層的クラスタリングは正解ラベルを使わずにデータをグループ分けする教師なし学習であり、問題と正解のペアを作る仕組みではない。"]}'),
  ('g-kentei-g-q12', '3. 機械学習の概要',
   'データを訓練・検証・テストの3つに分ける進め方において、「検証データ」と「テストデータ」の役割の違いとして最も適切なものはどれか。',
   NULL::text,
   '["検証データはハイパーパラメータの調整のために何度も繰り返し使ってよいが、テストデータは最終的な性能を測るために学習も調整も終えた後に1回だけ使う", "検証データは最終的な性能を測るために1回だけ使い、テストデータはハイパーパラメータの調整のために繰り返し使うという、2つの役割がちょうど逆に入れ替わっている", "検証データとテストデータはまったく同じ役割を持ち、呼び方が違うだけでどちらを何度使っても結果に違いは生じない", "検証データとテストデータはどちらもモデルの重みそのものを直接学習させるために使われるデータである"]',
   0, '[0]', 'single',
   '{"asked": "訓練・検証・テストの3分割のうち、「検証データ」と「テストデータ」の役割の違いを選ぶ問題。", "point": "「何度も見ながら調整してよい」なら検証データ、「最後に1回だけ」ならテストデータ。", "kid": "訓練データはモデル自身に「これが正解だよ」と教えて重みを学習させるためのデータ。検証データは、モデルの設定値（ハイパーパラメータ、例えば木の深さや学習率）を「これくらいがよさそうだ」と何度も試しながら調整するためのデータ。テストデータは、調整がすべて終わった後、最後の最後に「本当の実力はどれくらいか」を1回だけ測るためのデータ。検証データは調整の道具として繰り返し覗いてよいが、テストデータは本番の答案のように、最後まで見ずに取っておく。", "eg": "たとえるなら、訓練データは教科書、検証データは模試（何度も受けて、間違えた部分の勉強法を調整してよい）、テストデータは本番の入学試験（1回きりで、それまでは絶対に問題を見てはいけない）。模試の結果を見ながら勉強法を何度も調整するのは普通だが、本番の試験問題を先に見て対策してしまったら、本当の実力は測れなくなる。", "terms": [["訓練データ", "モデルの重みそのものを学習させるために使うデータ"], ["検証データ", "ハイパーパラメータの調整のために繰り返し使ってよいデータ"], ["テストデータ", "調整が全て終わった後、最終的な性能を測るために最後に1回だけ使うデータ"]], "think": "なぜテストデータを何度も使ってはいけないのかがカギ。もしテストデータを見ながらハイパーパラメータを何度も調整してしまうと、そのテストデータに都合よく合わせ込む調整を無意識にしてしまい、テストデータの結果が「まだ見ぬ本番データでの実力」ではなく「そのテストデータだけで良い点を取るための調整結果」になってしまう。これでは本当の汎化性能（未知のデータへの強さ）を測れない。だから調整用の検証データと、最終評価用のテストデータを分けて、テストデータは調整が全部終わるまで一切見ない、というルールが必要になる。", "vs": "検証データとテストデータはどちらも「学習には使わない」点で訓練データとは違うが、検証データは調整のために繰り返し覗いてよく、テストデータは最後の1回しか使わないという使う回数と目的が異なる。ここを混同すると「テストデータで何度もチューニングしてしまう」という実務上のミスにつながる。", "why_asked": "検証データとテストデータをどちらも「学習に使わないデータ」とひとまとめにして覚えてしまうと、テストデータを使ってハイパーパラメータ調整をしてしまうという典型的な失敗につながるため、役割の違いが繰り返し問われる。", "usecase": "モデル開発の実務では、検証データでの成績を見ながら学習率や木の深さなどを何度も調整し、最後にテストデータで1回だけ評価してから世に出す、という手順が守られる。", "opt": ["正解。検証データは調整のために繰り返し使い、テストデータは最終評価のために最後に1回だけ使う。", "検証データとテストデータの役割が入れ替わっている。", "検証データは繰り返し調整に使えるが、テストデータは最後に1回だけという使う回数の違いがあり、同じ役割ではない。", "検証データもテストデータも、モデルの重みを直接学習させる（訓練する）ためのデータではない。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 120\" font-family=\"sans-serif\">\n<rect x=\"15\" y=\"30\" width=\"180\" height=\"30\" fill=\"#3b82f6\" opacity=\"0.55\" stroke=\"#2a2f3f\"/>\n<text x=\"105\" y=\"49\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">訓練データ</text>\n<rect x=\"195\" y=\"30\" width=\"70\" height=\"30\" fill=\"#c9a04a\" opacity=\"0.6\" stroke=\"#2a2f3f\"/>\n<text x=\"230\" y=\"49\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">検証</text>\n<rect x=\"265\" y=\"30\" width=\"60\" height=\"30\" fill=\"#c47070\" opacity=\"0.6\" stroke=\"#2a2f3f\"/>\n<text x=\"295\" y=\"49\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">テスト</text>\n<text x=\"105\" y=\"74\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">モデルを学習させる</text>\n<text x=\"230\" y=\"74\" text-anchor=\"middle\" font-size=\"7\" fill=\"#8892a4\">調整に使う</text>\n<text x=\"295\" y=\"74\" text-anchor=\"middle\" font-size=\"7\" fill=\"#8892a4\">最後に1回評価</text>\n<line x1=\"230\" y1=\"90\" x2=\"230\" y2=\"98\" stroke=\"#c9a04a\" stroke-width=\"1\"/>\n<text x=\"230\" y=\"108\" text-anchor=\"middle\" font-size=\"8\" fill=\"#c9a04a\">見ながら何度も調整してよい</text>\n</svg>\n"}'),
  ('g-kentei-g-q13', '4. ディープラーニングの概要',
   'ニューラルネットワークの重みを全部0で初期化してから学習を始めると、うまく学習が進まない。最も適切な理由はどれか。',
   NULL::text,
   '["同じ層のノードが最初から全く同じ計算をしてしまい、勾配で更新しても互いに区別されないままになるから", "重みが0だと勾配の値が毎回大きくなりすぎてしまい、更新のたびに誤差がどんどん膨らんで発散してしまうから", "重みを0にすると学習率の値まで自動的に0へ固定されてしまい、更新の歩幅がなくなってしまうから", "重みが0だと出力層の活性化関数の計算そのものが数学的に成立しなくなってしまうから"]',
   0, '[0]', 'single',
   '{"asked": "重みを全部0で初期化すると学習が進まない理由を問う設問。", "point": "同じ層の重みが全部同じ値からスタートすると、更新してもノード同士がずっと同じ値のまま＝対称性が崩れない。", "kid": "ニューラルネットワークの各ノードは、入ってくる値に掛ける『効き具合のつまみ』＝重みを持っている。このつまみの値がノードごとに違うからこそ、ノードごとに違う特徴に反応できるようになる。最初から全ノードのつまみを0で揃えてしまうと、どのノードも同じ計算しかできない状態でスタートすることになる。", "eg": "クラス全員に同じ問題と同じ最初の答案を配り、同じ添削コメントを返すようなもの。全員が同じ添削を受けて同じように直すので、いつまでも全員の答案が同じままになり、誰も個性のある得意分野を持てない。", "terms": [["重みの初期化", "学習を始める前に重みへ与える最初の値の決め方"], ["対称性の破れ", "同じ層のノードがそれぞれ違う値からスタートし、違う役割を持てるようにすること"], ["勾配", "出力の誤差をもとに『重みをどちら向きにどれだけ直すか』を表す合図"]], "think": "なぜ全部0だと学習できないのかがカギ。同じ層の各ノードは、入力への重みが違うからこそ違う特徴に反応するようになる。重みを全部0にすると、どのノードも最初から全く同じ計算をしていることになる。逆伝播で返ってくる『直してね』の合図である勾配も、同じ層のすべてのノードに対してまったく同じ値になる。同じ合図で同じだけ更新されるので、更新した後もノード同士はやっぱり同じ値のまま。これが何度更新を繰り返しても崩れない。結果、その層は実質1個のノードしか無いのと同じ状態になり、表現力が全く増えない。だから重みは最初からランダムに初期化して、ノードごとに違う値にしておく必要がある。", "vs": "勾配消失（層を重ねるうちに合図そのものが薄まって届かなくなる現象）や、学習率が大きすぎて起きる発散とは別の話。全部0初期化の問題は、値が小さいか大きいかではなく、ノード同士が『区別されない』ことが原因。", "why_asked": "「重みは0で初期化すればいいのでは」という直感的な誤解を突く定番の切り口。ランダム初期化がなぜ必要かの理解を問う。", "usecase": "実務でも重みをうっかり全部同じ値（0や定数）で初期化するバグは起きうる。学習が全く進まないときの初歩的なチェックポイントの一つになる。", "opt": ["正解。重みが全部同じ値だと、同じ層のノードは常に同じ計算・同じ勾配・同じ更新を受け、いつまでも区別されない。", "全部0で揃えた場合に起きるのはむしろ更新が止まったように見える停滞で、発散とは逆方向の問題。勾配が大きくなりすぎるわけではない。", "学習率自体は初期化とは別に設定する値で、重みを0にしても学習率の値が自動で0になるわけではない。", "活性化関数の計算自体はできる。問題は同じ層のノードが区別されなくなることにあり、計算が成立しなくなるわけではない。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 140\" font-family=\"sans-serif\">\n  <text x=\"10\" y=\"16\" font-size=\"11\" fill=\"#8892a4\">重みを全部0で初期化すると</text>\n  <circle cx=\"35\" cy=\"70\" r=\"14\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/>\n  <text x=\"35\" y=\"74\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">入力</text>\n  <line x1=\"49\" y1=\"65\" x2=\"130\" y2=\"30\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/>\n  <line x1=\"49\" y1=\"70\" x2=\"130\" y2=\"70\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/>\n  <line x1=\"49\" y1=\"75\" x2=\"130\" y2=\"110\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/>\n  <text x=\"88\" y=\"42\" font-size=\"9\" fill=\"#8892a4\">w=0</text>\n  <text x=\"88\" y=\"65\" font-size=\"9\" fill=\"#8892a4\">w=0</text>\n  <text x=\"88\" y=\"100\" font-size=\"9\" fill=\"#8892a4\">w=0</text>\n  <circle cx=\"145\" cy=\"30\" r=\"14\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/>\n  <circle cx=\"145\" cy=\"70\" r=\"14\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/>\n  <circle cx=\"145\" cy=\"110\" r=\"14\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/>\n  <text x=\"145\" y=\"34\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">同じ</text>\n  <text x=\"145\" y=\"74\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">同じ</text>\n  <text x=\"145\" y=\"114\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">同じ</text>\n  <line x1=\"167\" y1=\"70\" x2=\"205\" y2=\"70\" stroke=\"#8892a4\" stroke-width=\"1.2\"/>\n  <polygon points=\"205,70 198,66 198,74\" fill=\"#8892a4\"/>\n  <text x=\"185\" y=\"60\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">更新</text>\n  <circle cx=\"237\" cy=\"30\" r=\"14\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/>\n  <circle cx=\"237\" cy=\"70\" r=\"14\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/>\n  <circle cx=\"237\" cy=\"110\" r=\"14\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/>\n  <text x=\"237\" y=\"34\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">同じ</text>\n  <text x=\"237\" y=\"74\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">同じ</text>\n  <text x=\"237\" y=\"114\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">同じ</text>\n  <text x=\"260\" y=\"70\" font-size=\"18\" fill=\"#c47070\" text-anchor=\"middle\">…</text>\n  <text x=\"170\" y=\"135\" font-size=\"10\" fill=\"#c47070\" text-anchor=\"middle\">同じ層のノードがずっと区別されないまま</text>\n</svg>"}'),
  ('g-kentei-g-q14', '4. ディープラーニングの概要',
   '活性化関数の種類に合わせて重みの初期値の『ばらつきの大きさ』を調整する初期化手法がある。シグモイド関数・tanh関数向けの手法と、ReLU関数向けの手法の組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["シグモイド・tanh向け＝Xavier初期化、ReLU向け＝He初期化", "シグモイド・tanh向け＝He初期化、ReLU向け＝Xavier初期化", "シグモイド・tanh向け＝Xavier初期化、ReLU向け＝Xavier初期化（どちらも同じもの）", "シグモイド・tanh向け＝バッチ正規化、ReLU向け＝Xavier初期化"]',
   0, '[0]', 'single',
   '{"asked": "活性化関数ごとに使い分ける重み初期化手法の名前の組み合わせを問う設問。", "point": "『シグモイド・tanh＝Xavier初期化』『ReLU＝He初期化』という対応のペアで覚える。", "kid": "重みの最初の値をどれくらいバラつかせるか（初期値の広がり方）は、その後に通す活性化関数によって最適な大きさが変わる。シグモイドやtanhは入力が大きくなるとグラフの傾きがほぼ平らになり信号が薄まりやすいので、信号が大きくなりすぎず小さくなりすぎない広がりを計算するのがXavier初期化。ReLUはマイナス側を全部0にしてしまうぶん、通り抜けた後の信号がおよそ半分に減る傾向があるので、それを補うようにXavierより少し広めにばらつかせるのがHe初期化。", "eg": "同じ蛇口でも、水を通す先が細いストロー（シグモイド）か太いホース（ReLU）かで、ちょうどいい水量が違うようなもの。", "terms": [["Xavier初期化", "シグモイド・tanh向けに、層の入出力のノード数から重みの広がりを決める初期化手法"], ["He初期化", "ReLU向けに、Xavier初期化より少し広めに調整した初期化手法"], ["勾配消失", "層を重ねるうちに『直してね』の合図が薄まって届かなくなる現象"]], "think": "なぜ活性化関数ごとに初期化を使い分けるのかがカギ。初期値の広がりが狭すぎると、層を重ねるたびに信号がどんどん小さくなって勾配消失に近づき、広すぎると逆に信号が層を重ねるたびに大きくなりすぎて発散に近づく。シグモイド・tanhとReLUでは信号の減り方の傾向が違うため、ちょうどよい広がりを求める計算式も別になる。だから名前も別に用意されている。", "vs": "重みをランダムに初期化すること自体（対称性を崩す工夫）とは別の論点。Xavier初期化とHe初期化は、ランダムにする上で『どれくらいの広がりが最適か』を活性化関数ごとに数式で決める工夫。", "why_asked": "似た名前の初期化手法を、対応する活性化関数を入れ替えて出す引っかけが定番。", "usecase": "深いネットワークを組むとき、フレームワークのデフォルト初期化がどちらの発想に基づくか意識すると、学習が不安定なときの手がかりになる。", "opt": ["正解。シグモイド・tanh向けの広がりを計算するのがXavier初期化、ReLU向けに少し広めに調整するのがHe初期化。", "対応が逆。シグモイド・tanh向けがXavier初期化、ReLU向けがHe初期化という組み合わせが正しい。", "同じものではない。ReLU向けにはXavier初期化より広めに調整したHe初期化が使われる。", "バッチ正規化は初期化手法ではなく、学習中に各層の入力の分布をそろえる別の仕組み。"]}'),
  ('g-kentei-g-q15', '4. ディープラーニングの概要',
   '勾配がほぼ0に近いのに、そこが本当の最小値ではない場所がある。ある方向には下り坂、別の方向には上り坂になっている、このような地点を何と呼ぶか。',
   NULL::text,
   '["鞍点", "局所最適解", "大域最適解", "勾配消失"]',
   0, '[0]', 'single',
   '{"asked": "方向によって坂の向きが違う、勾配がほぼ0の地点（鞍点。「あんてん」と読む）の名前を問う設問。", "point": "見る方向によって下りにも上りにもなる地点なら鞍点。まわり全方向が上りに見える地点なら局所最適解。", "kid": "馬に乗せる『鞍（くら）』のような形をした地形を思い浮かべる。前後方向で見ると谷底のように下っているのに、左右方向で見るとまだ山の途中で上っている。このような場所では、傾き（勾配）を計算するとほぼ0になるので、勾配降下法は『もう十分低い場所だ』と勘違いして動きがほとんど止まってしまう。", "eg": "峠（とうげ）のような地形。北から登ってきた道からは下ってきたように見えても、東西の尾根に沿って見ると、実はまだ稜線の途中だったりする。", "terms": [["鞍点", "ある方向では谷、別の方向では山になっている地点。全体としては最小値ではない"], ["局所最適解", "まわり全方向で見ると一番低く見えるが、全体で見ると本当の最小値ではない点"], ["プラトー", "勾配がほぼ0のまま長く続く、傾きの緩やかな平らな領域"]], "think": "なぜ深いニューラルネットワークで鞍点が問題になりやすいのかがカギ。重み全部の組み合わせという多くの方向（次元）がある空間では、全方向が同時に上り坂になる本当の谷底（局所最適解）である確率は下がっていき、一部の方向だけ下り坂が残る鞍点である確率のほうが相対的に高くなる。鞍点では動ける方向の勾配がほぼ0なので、そのまま勾配降下法だけで進もうとすると動きがほとんど止まり、学習が停滞して見える。前回までの更新の『勢い』を引き継ぐモメンタムのような工夫が、この停滞を抜けやすくする。", "vs": "局所最適解はまわり全方向が上り坂になっている点、鞍点はある方向は下り・別の方向は上りになっている点。どちらも勾配がほぼ0という共通点があるため混同しやすい。", "why_asked": "学習が停滞して見えるとき、単純に局所最適解にはまったと決めつける短絡的な理解を突く。", "usecase": "損失が下がらず停滞したとき、局所最適解だけでなく鞍点・プラトーの可能性も疑う視点として、モメンタムなど勢いを持つ最適化手法を選ぶ根拠になる。", "opt": ["正解。ある方向は下り坂、別の方向は上り坂という、方向によって性質が変わる勾配ほぼ0の地点。", "局所最適解はまわり全方向が上り坂に見える点で、方向によって坂の向きが変わる鞍点とは別物。", "大域最適解は全体の中で本当に一番低い点であり、勾配がほぼ0になる停滞地点の名前ではない。", "勾配消失は層を重ねるうちに合図そのものが薄まって届かなくなる現象で、地形上の特定の地点の名前ではない。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 140\" font-family=\"sans-serif\">\n  <text x=\"10\" y=\"14\" font-size=\"9.5\" fill=\"#8892a4\">鞍点（方向で坂の向きが違う）</text>\n  <path d=\"M 20 60 C 45 30, 55 90, 80 60 S 110 30, 130 60\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.8\"/>\n  <circle cx=\"80\" cy=\"60\" r=\"3.5\" fill=\"#c9a04a\"/>\n  <text x=\"80\" y=\"78\" font-size=\"9\" fill=\"#c9a04a\" text-anchor=\"middle\">勾配≈0</text>\n  <text x=\"20\" y=\"100\" font-size=\"8.5\" fill=\"#8892a4\">ある向きは下り、別の向きは上り</text>\n\n  <text x=\"185\" y=\"14\" font-size=\"9.5\" fill=\"#8892a4\">局所最適解（どちらも上り坂）</text>\n  <path d=\"M 190 40 Q 235 100, 280 40\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/>\n  <circle cx=\"235\" cy=\"88\" r=\"3.5\" fill=\"#6ab08d\"/>\n  <text x=\"235\" y=\"105\" font-size=\"9\" fill=\"#6ab08d\" text-anchor=\"middle\">勾配≈0</text>\n  <text x=\"200\" y=\"120\" font-size=\"8.5\" fill=\"#8892a4\">まわり全方向が上り坂</text>\n</svg>"}'),
  ('g-kentei-g-q16', '4. ディープラーニングの概要',
   '学習の最初は大きな学習率で大まかに動き、学習が進むにつれて学習率を徐々に小さくしていく工夫を何と呼ぶか。',
   NULL::text,
   '["学習率スケジューリング（学習率減衰）", "早期終了（検証データの成績悪化を見て学習を打ち切る工夫）", "バッチ正規化（各層に入る値の分布をそろえる工夫）", "勾配クリッピング（勾配の大きさに上限を設ける工夫）"]',
   0, '[0]', 'single',
   '{"asked": "学習が進むにつれて学習率を小さくしていく工夫の名前を問う設問。", "point": "学習率を『最初は大きく、後半は小さく』変えていく工夫なら学習率スケジューリング。", "kid": "学習率とは、一回の更新でどれだけ重みを動かすかを決める『歩幅』のようなつまみ。学習の最初は正解から遠いところにいるので、大股でどんどん進みたい。しかし谷底に近づいてからも大股のままだと、谷底を通り過ぎては戻りを繰り返してしまう。だんだん歩幅を小さくしていけば、最初は速く近づき、後半は谷底付近で細かく調整できる。", "eg": "遠くの目的地に向かうとき、遠いうちは大股で急ぎ、近づいてきたら小刻みな歩幅に切り替えて、目的地をまたぎ越さないようにするようなもの。", "terms": [["学習率", "一回の更新で重みをどれだけ動かすかを決める歩幅のような値"], ["学習率スケジューリング", "学習の進み具合に応じて学習率を徐々に変えていく工夫。多くは減衰（小さくする）方向"], ["ステップ減衰", "学習率スケジューリングの代表的なやり方の一つ。一定のエポックごとに学習率を段階的に小さくする"]], "think": "なぜ学習率を固定したままだと困るのかがカギ。学習率を大きいまま固定すると、谷底付近でも大股で動いてしまうので、谷底を通り過ぎては戻りを繰り返し、ジグザグに揺れて収束しにくい。学習率を小さいまま固定すると、最初の大まかな移動にも小股しか使えないので、学習が終わるまでに時間がかかりすぎる。学習率を少しずつ減衰させれば、最初は大股で速く近づき、後半は小股で微調整でき、速さと精度を両立できる。だから学習率スケジューリングが使われる。", "vs": "早期終了（検証データの成績が悪化し始めたら学習そのものを打ち切るタイミングの工夫）や、勾配クリッピング（勾配の大きさに上限を設ける工夫）とは対象が違う。学習率スケジューリングはあくまで歩幅（学習率）の調整。", "why_asked": "似たような『学習を安定させる工夫』が並ぶ選択肢の中から、対象が『学習率そのもの』であるものを見分けさせる定番の切り口。", "usecase": "学習の後半で損失がジグザグに振動して下がりきらないとき、学習率スケジューリングを入れることで収束を安定させられる。", "opt": ["正解。学習が進むにつれて学習率という歩幅を徐々に小さくしていく工夫。", "早期終了は学習そのものを打ち切るタイミングの工夫で、学習率の値そのものは変えない。", "バッチ正規化は各層に入ってくる値の分布をそろえる工夫で、学習率の歩幅を変える工夫とは別物。", "勾配クリッピングは勾配の大きさに上限を設けて発散を防ぐ工夫で、学習率を徐々に小さくする工夫とは別物。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 140\" font-family=\"sans-serif\">\n  <text x=\"10\" y=\"16\" font-size=\"11\" fill=\"#8892a4\">学習率スケジューリング（学習が進むほど歩幅を小さく）</text>\n  <line x1=\"35\" y1=\"115\" x2=\"320\" y2=\"115\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/>\n  <line x1=\"35\" y1=\"30\" x2=\"35\" y2=\"115\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/>\n  <text x=\"12\" y=\"42\" font-size=\"9\" fill=\"#8892a4\">学習率</text>\n  <text x=\"285\" y=\"128\" font-size=\"9\" fill=\"#8892a4\">エポック</text>\n  <path d=\"M 45 50 L 105 50 L 105 68 L 165 68 L 165 84 L 225 84 L 225 97 L 295 97\"\n        fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n  <text x=\"45\" y=\"45\" font-size=\"8.5\" fill=\"#e8eaf0\">大股</text>\n  <text x=\"255\" y=\"109\" font-size=\"8.5\" fill=\"#e8eaf0\">小股</text>\n</svg>"}'),
  ('g-kentei-g-q17', '4. ディープラーニングの概要',
   '訓練データが1000件あり、バッチサイズを100件に設定して学習する。1エポックの間に重みが更新される回数（イテレーション数）はいくつか。',
   NULL::text,
   '["10回", "100回", "1000回", "1回"]',
   0, '[0]', 'single',
   '{"asked": "訓練データ1000件・バッチサイズ100件のとき、1エポックあたりの重み更新回数（イテレーション数）を求める設問。", "point": "イテレーション数＝データ件数÷バッチサイズ。1000÷100＝10回。", "kid": "エポックとは、訓練データ全体を1回ひととおり使い切ることを指す単位。バッチサイズとは、1回の重み更新に使うデータの件数。1エポックの中で重みを何回更新するか（イテレーション数）は、データ全部の件数をバッチサイズで割った数になる。", "eg": "1000ページある本を、1日100ページずつ読んでいくとする。本を1周読み終える（1エポック）までに、10回に分けて読む（10イテレーション）ことになる、というのと同じ関係。", "terms": [["バッチサイズ", "1回の重み更新に使うデータの件数"], ["イテレーション", "重みを1回更新する処理の単位・その回数"], ["エポック", "訓練データ全体を1回ひととおり使い切ること"]], "calc": "①日本語で言う: 1エポックは訓練データ全部を1回使い切ること。バッチサイズは1回の更新に使うデータの件数。だから1エポックの中で何回更新するか（イテレーション数）は、データ全部の件数をバッチサイズで割った数になる。②小さい数字で全ステップ: データ全部は1000件。バッチサイズは100件。1回の更新で100件を使うので、1000件を使い切るには 1000 ÷ 100 = 10回 の更新が必要。だから1エポックのイテレーション数は10回。③記号版: イテレーション数 = データ件数 ÷ バッチサイズ = 1000 ÷ 100 = 10（÷は割り算の記号。ここでは『データ件数をバッチサイズで割る』という意味で使っている）", "think": "なぜこの3つの語をセットで押さえる必要があるのかがカギ。バッチサイズを大きくすると、1回の更新に使うデータが増えるので、同じ量のデータを使い切るまでの更新回数（イテレーション数）は逆に減る。エポック数を増やすと、データ全体を使い切る回数そのものが増えるので、総イテレーション数（イテレーション数×エポック数）も増える。3つは別々の設定値でありながら、掛け算・割り算の関係でつながっている。", "vs": "バッチサイズを大きくするとイテレーション数が『増える』と思い込みがちだが、実際は逆で、同じデータ量ならバッチサイズが大きいほど更新回数は少なくなる。エポック・バッチサイズ・イテレーションは指しているものが違う語なので混同しない。", "why_asked": "3つの用語を関係式として理解できているかを、小さい数字で実際に計算させて確かめる定番の切り口。", "usecase": "学習ログに表示される『epoch』『step（iteration）』の数字の意味を正しく読むために必要な計算。バッチサイズを変えたときログの更新回数がどう変わるか予測できる。", "opt": ["正解。1000件のデータをバッチサイズ100件で使い切るには、1000÷100＝10回の更新が必要。", "100はバッチサイズの数値そのもの。イテレーション数と取り違えている。", "1000はデータ件数そのもの。1件ずつ更新する場合の回数と取り違えている。", "バッチサイズが1000件（全データ）のバッチ学習であれば1回だが、この設問のバッチサイズは100件。"]}'),
  ('g-kentei-g-q18', '4. ディープラーニングの概要',
   '重みの更新の仕方には、訓練データ全部を使ってから1回更新する方式、少数ずつに分けて何度も更新する方式、1件ずつ使ってその都度更新する方式がある。これらの組み合わせとして正しいものはどれか。',
   NULL::text,
   '["バッチ学習＝全データで1回更新、ミニバッチ学習＝少数ずつ分けて更新、オンライン学習＝1件ずつ更新", "バッチ学習＝1件ずつ更新、ミニバッチ学習＝少数ずつ分けて更新、オンライン学習＝全データで1回更新", "バッチ学習＝少数ずつ分けて更新、ミニバッチ学習＝全データで1回更新、オンライン学習＝1件ずつ更新", "バッチ学習・ミニバッチ学習・オンライン学習はすべて同じ更新方式の呼び名違いにすぎない"]',
   0, '[0]', 'single',
   '{"asked": "バッチ学習・ミニバッチ学習・オンライン学習の3方式と、それぞれの更新の仕方の対応を問う設問。", "point": "1回の更新に使うデータの件数が『全部／少数ずつ／1件』のどれかで、バッチ／ミニバッチ／オンラインが決まる。", "kid": "重みを更新するとき、1回の更新に何件のデータを使うかで呼び名が変わる。訓練データを全部まとめて使ってから1回だけ更新するのがバッチ学習。少数（例えば数十〜数百件）ずつに分けて、そのたびに更新を繰り返すのがミニバッチ学習。1件のデータが来るたびにその都度更新するのがオンライン学習（逐次学習）。", "eg": "会社の経費精算に例えると、1ヶ月分の経費を全員まとめて月末に一度に処理するのがバッチ、数人分ずつまとめてこまめに処理するのがミニバッチ、1件経費が出るたびその都度処理するのがオンライン。", "terms": [["バッチ学習", "訓練データ全部を使ってから重みを1回更新するやり方"], ["ミニバッチ学習", "訓練データを少数ずつのかたまり（ミニバッチ）に分け、そのたびに重みを更新するやり方"], ["オンライン学習", "データが1件来るたびにその都度重みを更新するやり方。逐次学習とも呼ぶ"]], "think": "なぜ実務ではミニバッチ学習が主流なのかがカギ。バッチ学習は毎回全データの平均的な勾配を使うので更新の方向は安定するが、1回の更新に時間がかかり、更新回数そのものも少ない。オンライン学習は1件ごとに更新するので更新は速く頻繁だが、その1件のノイズに引っ張られて更新の方向がぶれやすい。ミニバッチ学習はその中間で、ある程度まとまった件数の平均を取りつつ頻繁に更新できるため、安定性と速さのバランスが良く、実務の多くで使われる。", "vs": "バッチサイズを1にしたミニバッチ学習はオンライン学習と、バッチサイズをデータ全件にしたミニバッチ学習はバッチ学習と実質同じになる。3つは別々の手法というより、バッチサイズの大きさで連続的につながっている関係。", "why_asked": "名前と更新の仕方の対応を入れ替えて出す定番の引っかけ。特にバッチとオンラインを逆にする誤答が多い。", "usecase": "学習が不安定でジグザグに揺れているときはバッチサイズを大きくしてミニバッチに近づけ、逆に更新をもっと頻繁にしたいときはバッチサイズを小さくする、という調整の判断材料になる。", "opt": ["正解。全データで1回更新するのがバッチ学習、少数ずつ分けて何度も更新するのがミニバッチ学習、1件ずつ更新するのがオンライン学習。", "バッチ学習とオンライン学習の対応が入れ替わっている。バッチ学習は全データで1回更新、オンライン学習は1件ずつ更新が正しい。", "バッチ学習とミニバッチ学習の対応が入れ替わっている。バッチ学習は全データで1回更新、ミニバッチ学習は少数ずつ分けて更新が正しい。", "3方式は1回の更新に使うデータ件数（全部／少数／1件）が違う、明確に区別される呼び名。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n  <text x=\"10\" y=\"14\" font-size=\"10\" fill=\"#8892a4\">バッチ学習</text>\n  <circle cx=\"30\" cy=\"35\" r=\"5\" fill=\"#3b82f6\"/><circle cx=\"45\" cy=\"35\" r=\"5\" fill=\"#3b82f6\"/>\n  <circle cx=\"60\" cy=\"35\" r=\"5\" fill=\"#3b82f6\"/><circle cx=\"75\" cy=\"35\" r=\"5\" fill=\"#3b82f6\"/>\n  <circle cx=\"90\" cy=\"35\" r=\"5\" fill=\"#3b82f6\"/>\n  <line x1=\"100\" y1=\"35\" x2=\"130\" y2=\"35\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n  <text x=\"140\" y=\"39\" font-size=\"9\" fill=\"#e8eaf0\">1回更新</text>\n\n  <text x=\"10\" y=\"70\" font-size=\"10\" fill=\"#8892a4\">ミニバッチ学習</text>\n  <circle cx=\"30\" cy=\"90\" r=\"5\" fill=\"#60a5fa\"/><circle cx=\"45\" cy=\"90\" r=\"5\" fill=\"#60a5fa\"/>\n  <line x1=\"55\" y1=\"90\" x2=\"80\" y2=\"90\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n  <text x=\"82\" y=\"94\" font-size=\"8.5\" fill=\"#e8eaf0\">更新</text>\n  <circle cx=\"105\" cy=\"90\" r=\"5\" fill=\"#60a5fa\"/><circle cx=\"120\" cy=\"90\" r=\"5\" fill=\"#60a5fa\"/>\n  <line x1=\"130\" y1=\"90\" x2=\"155\" y2=\"90\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n  <text x=\"157\" y=\"94\" font-size=\"8.5\" fill=\"#e8eaf0\">更新</text>\n  <circle cx=\"180\" cy=\"90\" r=\"5\" fill=\"#60a5fa\"/><circle cx=\"195\" cy=\"90\" r=\"5\" fill=\"#60a5fa\"/>\n  <line x1=\"205\" y1=\"90\" x2=\"230\" y2=\"90\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n  <text x=\"232\" y=\"94\" font-size=\"8.5\" fill=\"#e8eaf0\">更新</text>\n  <text x=\"270\" y=\"94\" font-size=\"18\" fill=\"#8892a4\">…</text>\n\n  <text x=\"10\" y=\"125\" font-size=\"10\" fill=\"#8892a4\">オンライン学習</text>\n  <circle cx=\"30\" cy=\"140\" r=\"5\" fill=\"#6ab08d\"/>\n  <line x1=\"38\" y1=\"140\" x2=\"58\" y2=\"140\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n  <text x=\"60\" y=\"144\" font-size=\"8.5\" fill=\"#e8eaf0\">更新</text>\n  <circle cx=\"90\" cy=\"140\" r=\"5\" fill=\"#6ab08d\"/>\n  <line x1=\"98\" y1=\"140\" x2=\"118\" y2=\"140\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n  <text x=\"120\" y=\"144\" font-size=\"8.5\" fill=\"#e8eaf0\">更新</text>\n  <circle cx=\"150\" cy=\"140\" r=\"5\" fill=\"#6ab08d\"/>\n  <line x1=\"158\" y1=\"140\" x2=\"178\" y2=\"140\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n  <text x=\"180\" y=\"144\" font-size=\"8.5\" fill=\"#e8eaf0\">更新</text>\n  <text x=\"220\" y=\"144\" font-size=\"18\" fill=\"#8892a4\">…</text>\n</svg>"}'),
  ('g-kentei-g-q19', '4. ディープラーニングの概要',
   '「重み減衰（weight decay）」と呼ばれる過学習対策の手法は、実質的に何と同じものか。',
   NULL::text,
   '["L2正則化（重みの2乗に比例した罰を誤差に足す仕組み）", "L1正則化（重みの絶対値に比例した罰を誤差に足す仕組み）", "ドロップアウト（学習のたびに一部のノードを無効化する仕組み）", "早期終了（検証データの成績が悪化し始めたら学習を打ち切る仕組み）"]',
   0, '[0]', 'single',
   '{"asked": "重み減衰（weight decay）という手法が実質的に同じものである別の手法名を問う設問。", "point": "重み減衰という名前で出てきたら、中身はL2正則化と同じだと読み替える。", "kid": "重み減衰は、名前の通り『毎回の更新で重みの値を少しずつ減らしていく』仕組み。一方L2正則化は、誤差に『重みの2乗』を罰として足すことで、大きい重みを抑える仕組み。この2つは呼び方も説明のされ方も違うが、実際に重みへ与える効果を数式で見比べると、まったく同じ働きになる。", "eg": "ダイエットのやり方を、毎回体重の一部を自動的に減らす仕組みだと説明する人と、『食べ過ぎるほど罰金を科す仕組み』だと説明する人がいるようなもの。説明の切り口は違っても、結果として体重が抑えられる仕組みそのものは同じ。", "terms": [["重み減衰", "毎回の更新で重みの値を一定割合だけ減らしてから、通常の更新を行う仕組み"], ["L2正則化", "誤差に重みの2乗を罰として足すことで、重みが大きくなりすぎるのを抑える仕組み"], ["過学習", "訓練データに合わせすぎて、新しいデータへの当てはまりが悪くなる現象"]], "think": "なぜ重み減衰とL2正則化が同じと言えるのかがカギ。L2正則化は誤差に重みの2乗を罰として足す仕組みで、この罰を勾配として計算すると『重みの値そのものに比例した分だけ引く』という更新の形になる。これは『毎回重みを一定割合だけ減らしてから通常の更新をする』という重み減衰の定義とちょうど一致する。だから呼び方が違うだけで、実際に重みへ働く効果は同じになる。", "vs": "重みの絶対値に比例した罰を足すL1正則化とは別物。L1正則化は重みを0まで押し切ってスパース化する効果を持つが、重み減衰（L2正則化）は重みを全体的に小さくするだけで、ちょうど0にはなりにくい。", "why_asked": "同じ仕組みが分野や文献によって別の名前で呼ばれる典型例。名前に惑わされず中身で見分けられるかを問う。", "usecase": "深層学習のフレームワークの `weight_decay` というパラメータは、多くの場合L2正則化の強さを指している。設定値の意味を正しく理解するのに直結する。", "opt": ["正解。重み減衰は毎回重みを一定割合だけ減らす仕組みで、これはL2正則化の罰を勾配の形で見たときの効果と一致する。", "L1正則化は重みの絶対値に比例した罰で、重みを0まで押し切る効果を持つ点が重み減衰とは異なる。", "ドロップアウトはノードを無効化する仕組みで、重みの値そのものを減らす重み減衰とは仕組みが異なる。", "早期終了は学習を打ち切るタイミングの工夫で、重みの値を直接減らす重み減衰とは仕組みが異なる。"]}'),
  ('g-kentei-g-q20', '4. ディープラーニングの概要',
   'ReLU関数では入力がマイナスのとき出力も勾配も常に0になり、そのノードの重みが更新されなくなる「dying ReLU」が起きることがある。この対策として、マイナス側にわずかな傾きを持たせた活性化関数はどれか。',
   NULL::text,
   '["Leaky ReLU", "シグモイド関数（0〜1の範囲に押し込める活性化関数）", "ソフトマックス関数（合計が1になる確率分布に変える活性化関数）", "恒等関数（入力をそのまま出力する活性化関数）"]',
   0, '[0]', 'single',
   '{"asked": "dying ReLU（ReLUの死）への対策として、マイナス側にわずかな傾きを持たせた活性化関数の名前を問う設問。", "point": "マイナス側を完全に0にせず、わずかに傾かせたReLUの改良版ならLeaky ReLU。", "kid": "ReLU関数はプラスの入力はそのまま通し、マイナスの入力は完全に0にする関数。マイナス側の傾きがちょうど0なので、あるノードの入力がずっとマイナスに固定されてしまうと、そのノードの重みは二度と更新されなくなる（dying ReLU）。Leaky ReLUは、マイナス側を完全な0にする代わりに、ごくわずかな傾きを持たせた関数。", "eg": "蛇口を完全に閉めてしまうのではなく、ほんの少しだけ水を流したままにしておくイメージ。完全に閉めると水（勾配）が二度と流れなくなるが、少しでも開けておけば流れ続ける。", "terms": [["Leaky ReLU", "直訳は「漏れのあるReLU」。マイナス側にわずかな傾きを持たせたReLUの改良版"], ["dying ReLU", "直訳は「ReLUの死」。入力がマイナスに固定されたノードの重みが二度と更新されなくなる現象"], ["ReLU（Rectified Linear Unit）", "rectify＝整流する。マイナスを0に切りそろえる。Rectified Linear Unitの略。入力がマイナスなら0、プラスならそのまま通す活性化関数"]], "think": "なぜわずかな傾きを持たせるだけでdying ReLUを防げるのかがカギ。ReLUはマイナス側の傾きがちょうど0なので、あるノードの入力がマイナスに固定されると、逆伝播で返ってくる勾配も常に0になり、そのノードの重みは二度と動かなくなってしまう。Leaky ReLUはマイナス側にごくわずかでも傾きを残しているので、勾配が完全な0にはならず、そのノードにもわずかながら『直してね』の合図が届き続ける。だから固定されたまま更新されなくなるノードが生まれにくい。", "vs": "ReLUはマイナス側の傾きが完全に0だが、Leaky ReLUはマイナス側にもわずかな傾きを残す点が違う。dying ReLUという現象自体はReLUで起きるものであり、Leaky ReLUはその対策として別に用意された関数。", "why_asked": "dying ReLUという現象の名前だけでなく、その対策として作られた関数まで理解しているかを問う定番の切り口。", "usecase": "学習中に特定の層のノードの出力がずっと0のまま動かないとき、活性化関数をReLUからLeaky ReLUに変えることが対策の選択肢になる。", "opt": ["正解。マイナス側にわずかな傾きを持たせることで、勾配が完全な0にならないようにしたReLUの改良版。", "シグモイド関数は別の活性化関数で、dying ReLU対策として作られたものではない。", "ソフトマックス関数は主に出力層で使われる関数で、dying ReLU対策とは目的が異なる。", "恒等関数は変換を加えない関数で、マイナス側に傾きを持たせて調整する仕組みとは異なる。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 140\" font-family=\"sans-serif\">\n  <line x1=\"30\" y1=\"100\" x2=\"310\" y2=\"100\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/>\n  <line x1=\"170\" y1=\"20\" x2=\"170\" y2=\"120\" stroke=\"#2a2f3f\" stroke-width=\"1.2\"/>\n  <text x=\"300\" y=\"112\" font-size=\"9\" fill=\"#8892a4\">入力</text>\n  <text x=\"178\" y=\"28\" font-size=\"9\" fill=\"#8892a4\">出力</text>\n\n  <path d=\"M 30 100 L 170 100 L 290 25\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"2\"/>\n  <text x=\"30\" y=\"88\" font-size=\"9\" fill=\"#c47070\">ReLU（マイナス側は完全に0＝平ら）</text>\n\n  <path d=\"M 30 118 L 170 100 L 290 25\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n  <text x=\"15\" y=\"133\" font-size=\"9\" fill=\"#3b82f6\">Leaky ReLU（マイナス側もわずかに傾く）</text>\n</svg>"}'),
  ('g-kentei-g-q21', '4. ディープラーニングの概要',
   '隠れ層が1つ（ノード数は十分に多い）だけの順伝播ニューラルネットワークでも、理論上はどんな連続関数でも好きな精度で近似できる、という定理を何と呼ぶか。',
   NULL::text,
   '["万能近似定理", "中心極限定理", "ノーフリーランチ定理", "大数の法則"]',
   0, '[0]', 'single',
   '{"asked": "隠れ層1つでも理論上どんな関数も近似できる、という定理の名前を問う設問。", "point": "『隠れ層1つでも幅が十分あれば何でも近似できる』という理論上の保証を指すなら万能近似定理。", "kid": "ニューラルネットワークの隠れ層とは、入力層と出力層の間にある計算の層のこと。万能近似定理は、その隠れ層がたった1つしかなくても、ノード（横方向の幅）を十分たくさん用意すれば、理論上はどんな複雑な連続した関数でも、望むだけ正確に近似できる、ということを保証する定理。", "eg": "折り紙で、十分な数の折り目（ノード）さえあれば理論上どんな形にも折れる、というたとえ。ただし実際にきれいに早く折るには、一気にではなく段階を踏んで折っていく（層を重ねる）ほうが効率的なことが多い。", "terms": [["万能近似定理", "隠れ層1つ・十分な幅があれば、理論上どんな連続関数でも近似できるという定理"], ["隠れ層", "入力層と出力層の間にある、特徴を計算する層"], ["幅と深さ", "幅はノードの数（横方向の広さ）、深さは層の数（縦方向の重なり）を指す"]], "think": "なぜ理論上できることと、実際に深い層が使われることが両立するのかがカギ。万能近似定理が保証しているのは『幅を十分広げれば1層でも近似できる』という存在の話であって、『効率よく学習できる』『現実的な計算量で済む』ことまでは保証しない。1層だけで複雑な関数を表そうとすると、必要なノード数が爆発的に増えてしまうことが多い。層を重ねて深くすると、浅い層で捉えた単純なパターンを次の層で組み合わせて、複雑なパターンをより少ないノード数で効率よく表現できる。だから理論上は1層でも足りるのに、実用ではあえて層を深くしたディープラーニングが使われる。", "vs": "ノーフリーランチ定理（あらゆる問題に万能な唯一のアルゴリズムは存在しないという別の定理）と、『万能』という言葉が共通するため混同しやすい。万能近似定理はネットワークの表現力についての定理で、ノーフリーランチ定理はアルゴリズムの優劣についての定理であり対象がまったく違う。", "why_asked": "「1層で理論上できるなら、なぜ層を深くするのか」という疑問に答えられるかを問う定番の切り口。", "usecase": "モデル設計で層を深くする根拠を説明するときに、理論上の表現力（万能近似定理）と実際の学習効率（深さが効く理由）を分けて考える視点になる。", "opt": ["正解。隠れ層1つ・十分な幅があれば、理論上どんな連続関数でも近似できるという定理。", "中心極限定理は、データをたくさん集めるほど平均が正規分布に近づくという、統計の別の定理。", "ノーフリーランチ定理は、あらゆる問題に万能な唯一のアルゴリズムは存在しないという、アルゴリズムの優劣についての別の定理。", "大数の法則は、試行回数を増やすほど結果の平均が真の期待値に近づくという、統計の別の法則。"]}'),
  ('g-kentei-g-q22', '4. ディープラーニングの概要',
   'ディープラーニングの黎明期、層を深くすると勾配消失などで学習がうまく進まなかったため、オートエンコーダを1層ずつ積み重ねて学習させ、その結果を初期値として使う手法が使われていた。この手法を何と呼ぶか。',
   NULL::text,
   '["事前学習（積層オートエンコーダによる層ごとの事前学習）", "転移学習（他のタスクで学習済みのモデルを流用する手法）", "ファインチューニング（学習済みモデルの一部を再学習する手法）", "アンサンブル学習（複数モデルの予測を組み合わせる手法）"]',
   0, '[0]', 'single',
   '{"asked": "層を深くすると学習が進みにくかった時代に使われていた、オートエンコーダを積み重ねる手法の名前を問う設問。", "point": "オートエンコーダを1層ずつ積み重ねて重みの初期値を先に作っておく、当時の歴史的な手法なら事前学習（積層オートエンコーダ）。", "kid": "オートエンコーダとは、入力をいったん小さく圧縮してから、また元に近い形へ復元することを学習させる仕組み。ディープラーニングの黎明期は、良い重みの初期値がないまま深いネットワーク全体をいきなり学習させると、勾配消失などでうまく学習できなかった。そこで、まず1層目をオートエンコーダとして教師なしで学習させて『入力をうまく復元できる重み』を見つけ、それを初期値として次の層も同じように学習させる、という作業を層の数だけ繰り返してから、最後にネットワーク全体を仕上げに学習させる、という段階的なやり方が使われていた。", "eg": "高いビルを一気に建てるのではなく、1階分の土台をしっかり固めてから、その上に2階を積み、また固めてから3階を積む、という工事の進め方に近い。", "terms": [["積層オートエンコーダ", "オートエンコーダを1層ずつ積み重ねて学習させる仕組み"], ["事前学習", "本番の学習の前に、良い重みの初期値を先に作っておく段階的な学習"], ["ファインチューニング", "事前学習などで用意した重みを土台に、目的のタスク向けに全体または一部を再学習する仕上げの工程"]], "think": "なぜ層ごとの事前学習が必要だったのかがカギ。当時よく使われていたシグモイド関数のような活性化関数と、工夫されていない重みの初期値の組み合わせでは、層を深くするほど勾配消失が起きやすく、ランダムな初期値からいきなり深いネットワーク全体を学習させるのは難しかった。そこで各層をオートエンコーダとして1層ずつ教師なしで学習させ、入力をうまく復元できる重みを先に見つけておき、それを初期値として使ってから最後に全体を仕上げに学習させる、という段階的なやり方がとられた。今はReLUやHe初期化、バッチ正規化などの工夫によって深い層でも直接学習できるようになったため、この手法は歴史的な手法として扱われる。", "vs": "転移学習やファインチューニングは、別のタスクやデータで学習済みのモデルを別の目的に流用する手法で、同じネットワークの層を1層ずつ積み重ねて初期値を作る事前学習（積層オートエンコーダ）とは目的も対象も異なる。", "why_asked": "「今は使われなくなった理由」まで含めて理解しているかを問う、歴史的経緯の定番の切り口。", "usecase": "現在は直接使う機会が少ないが、なぜ不要になったか（ReLU・He初期化・バッチ正規化などの登場）を説明できると、深層学習の発展の流れを理解する助けになる。", "opt": ["正解。オートエンコーダを1層ずつ積み重ねて、その結果を重みの初期値として使う、黎明期の段階的な事前学習の手法。", "転移学習は、他のタスクで学習済みのモデルを別の目的に流用する手法で、同じネットワーク内で層を積み重ねる事前学習とは別物。", "ファインチューニングは、事前学習などで用意した重みを土台に仕上げの再学習を行う工程で、積み重ねて初期値を作る作業そのものとは別物。", "アンサンブル学習は、複数のモデルの予測結果を組み合わせる手法で、重みの初期値を段階的に作る手法とは目的が異なる。"]}'),
  ('g-kentei-g-q23', '4. ディープラーニングの概要',
   '回帰問題では出力層に恒等関数（そのまま出力する関数）と平均二乗誤差（MSE）の組み合わせ、多クラス分類では出力層にソフトマックス関数と交差エントロピー誤差の組み合わせが定番とされる。この理由として最も適切なものはどれか。',
   NULL::text,
   '["出力の形（数値そのものか確率分布か）と、誤差の測り方（数値のずれか確率のずれか）の性質が一致しているから", "この2組の関数の組み合わせは、他のどんな組み合わせよりも計算量が少なく、常に最速で学習できる特別な組み合わせだから", "この2組の関数を使わない限り、誤差逆伝播法によって勾配を計算すること自体が数学的に成立しなくなってしまうから", "分類問題と回帰問題では、それぞれの問題に対応したプログラミング言語の関数の種類が根本的に異なっているから"]',
   0, '[0]', 'single',
   '{"asked": "出力層の活性化関数と損失関数を、回帰と分類でセットで選ぶ理由を問う設問。", "point": "出力が『数値そのもの』か『確率分布』かに、誤差の測り方をそろえるなら定番の組み合わせが選べる。", "kid": "回帰問題は、答えが連続した数値そのもの（例えば価格や気温）。分類問題は、答えが『どのクラスである確率が高いか』という確率の形。出力の形が違えば、誤差の測り方も合わせて変える必要がある。回帰では出力層に何も変換を加えない恒等関数を使い、誤差は数値同士のずれを測るMSEで測る。多クラス分類では出力層で各クラスの値を合計が1になる確率分布に変えるソフトマックス関数を使い、誤差は確率分布同士のずれを測る交差エントロピー誤差で測る。", "eg": "定規で長さを測るとき（回帰・MSE＝距離のずれ）と、天気予報の『降水確率』のずれを測るとき（分類・交差エントロピー＝確率のずれ）とでは、そもそも測っているものの種類が違うので、測り方の道具も変える、というたとえ。", "terms": [["恒等関数", "入力をそのまま出力に通す、変換をしない関数"], ["ソフトマックス関数", "各クラスの値を、合計が1になる確率分布へ変換する関数"], ["交差エントロピー誤差", "予測した確率分布と正解のクラスがどれだけズレているかを測る誤差"]], "think": "なぜこの組み合わせが定番なのかがカギ。回帰は答えが連続する数値そのものなので、出力層も数値をそのまま出す恒等関数が向いており、誤差は『予測値と正解の数値がどれだけ離れているか』を測るMSEが自然に対応する。多クラス分類は『どのクラスである確率が高いか』を答えたいので、出力層は各クラスの値を合計1の確率分布に変えるソフトマックス関数が向いており、誤差は『予測した確率分布と正解のクラスがどれだけズレているか』を測る交差エントロピー誤差が自然に対応する。出力の性質と誤差の測り方がちぐはぐだと、勾配の意味がねじれて学習がうまく働かない。だから出力層の活性化関数と損失関数はセットで選ぶ。", "vs": "回帰の出力層＝恒等関数、回帰の誤差＝MSE、分類の出力層＝ソフトマックスといった個別の事実を単に覚えるだけでなく、なぜその2つがペアで使われるのかという理由まで理解しているかを問う角度。", "why_asked": "個別の名前は知っていても、組み合わせの理由まで説明できるかを試す、より一段深い切り口。", "usecase": "モデルを設計するとき、出力層の活性化関数を変えたら損失関数も対応するものに変える必要がある、という判断につながる。", "opt": ["正解。出力の形と誤差の測り方の性質をそろえることで、勾配の意味がねじれず学習がうまく働く。", "計算量の少なさが理由ではない。出力の形と誤差の測り方の性質が一致していることが理由で、他の組み合わせより常に速いわけではない。", "この組み合わせでなければ誤差逆伝播法自体が成立しないわけではない。組み合わせが崩れると学習の質が落ちやすくなるという話。", "プログラミング言語の関数の種類とは無関係。数学的な出力の形と誤差の測り方の対応が理由。"]}'),
  ('g-kentei-g-q24', '4. ディープラーニングの概要',
   'あらゆる問題に対して常に最良の性能を発揮する、万能な唯一の機械学習アルゴリズムは存在しない、ということを主張する定理を何と呼ぶか。',
   NULL::text,
   '["ノーフリーランチ定理", "万能近似定理（隠れ層1つでも十分な幅があれば近似できるという定理）", "中心極限定理（データを集めるほど平均が正規分布に近づくという定理）", "次元の呪い（特徴量を増やすほどデータがまばらになる現象）"]',
   0, '[0]', 'single',
   '{"asked": "あらゆる問題に万能な唯一のアルゴリズムは存在しない、という定理の名前を問う設問。", "point": "『万能な唯一の最強アルゴリズムは存在しない』という主張ならノーフリーランチ定理。", "kid": "ノーフリーランチ定理とは、どんな種類の問題に対しても常に一番良い性能を出す、唯一の万能なアルゴリズムは存在しない、ということを主張する定理。問題の種類によって、向いているアルゴリズムは違う、ということを理論として保証している。", "eg": "万能な工具は無い、というたとえ。ドライバーは木ネジを締めるのには強いが、釘を打つのには向かない。料理道具でも、包丁は多くの食材に使える万能さがあるように見えて、骨を断つ作業には別の道具のほうが向いている。", "terms": [["ノーフリーランチ定理", "直訳は「タダ飯はない定理」。あらゆる問題に万能な唯一のアルゴリズムは存在しないという定理"], ["万能近似定理", "隠れ層1つでも十分な幅があれば理論上どんな関数でも近似できるという、別の定理"], ["交差検証", "手元のデータを分けて繰り返し評価することで、その問題にどのアルゴリズムが向いているかを比較する方法"]], "think": "なぜこの定理が成り立つのかがカギ。あるアルゴリズムが特定の種類の問題（例えば直線的に分かれるデータ）にうまく合う仕組みを持っているとすれば、その仕組みは別の種類の問題（例えば複雑に入り組んだデータ）ではむしろ足を引っぱることがある。あらゆる問題の平均で見ると、特定の仮定に強いアルゴリズムは、その仮定が外れる問題では弱くなるという跳ね返りがあるため、全ての問題で平均的に一番良いアルゴリズムは存在しない。だからデータの性質に応じて複数のアルゴリズムを比較検討する必要がある。", "vs": "万能近似定理（1つのネットワークが理論上どんな関数も表せるという定理）と、『万能』という言葉が共通するため混同しやすい。ノーフリーランチ定理はアルゴリズム同士の優劣についての定理で、対象がまったく違う。", "why_asked": "「これが最強のアルゴリズムだ」という単純化した思考を戒める、理論的な裏付けとして出題される定番の切り口。", "usecase": "実務でアルゴリズムを選ぶとき、常に一つの手法に決め打ちせず、複数のアルゴリズムを比較検証する根拠になる。", "opt": ["正解。あらゆる問題に対して常に最良の性能を出す、万能な唯一のアルゴリズムは存在しないという定理。", "万能近似定理は、ネットワークの表現力についての別の定理で、アルゴリズムの優劣についての定理ではない。", "中心極限定理は、統計における平均の性質についての別の定理で、アルゴリズムの優劣についての定理ではない。", "次元の呪いは学習が難しくなる現象そのものを指す言葉で、アルゴリズムの優劣についての定理ではない。"]}'),
  ('g-kentei-g-q25', '5. ディープラーニングの要素技術',
   '入力のサイズが6、フィルタのサイズが3、パディングが0、ストライドが1で畳み込みを行うと、出力される特徴マップの一辺のサイズはいくつか。',
   NULL::text,
   '["4", "3", "6", "9"]',
   0, '[0]', 'single',
   '{"asked": "畳み込みの出力サイズが、入力・フィルタ・パディング・ストライドからどう決まるかを問う設問。", "point": "出力サイズは (入力−フィルタ+2×パディング)÷ストライド+1 で決まる。", "kid": "画像の上でフィルタ(小さい四角い型)を端から端まで何回置けるかを数えると、それが出力の大きさになる。", "eg": "6マスの棚に、幅3の箱を1マスずつずらしながら置いていくと、置ける場所は左端・2番目・3番目・4番目の4通り。この「置ける回数」が出力サイズ。", "terms": [["フィルタ(カーネル)", "畳み込みで画像の上を滑らせながら当てる、小さな四角い数値の並び。値そのものは学習で決まる"], ["パディング", "入力の外側に余白(多くは0)を足して、出力が小さくなりすぎるのを防ぐ操作"], ["ストライド", "フィルタを一度にずらす幅。1なら1マスずつ、2なら2マスずつ動かす"]], "think": "なぜ4になるのかがカギ。入力を1,2,3,4,5,6の6マスとすると、幅3のフィルタが収まる開始位置は1,2,3,4の4通りしかない(5から始めると5,6,7の3マスが必要になり、入力は6マス目までしか無いので置けない)。だから置ける回数=出力サイズは4になる。パディングを足せば端にも余白ができて置ける回数が増え、ストライドを2にすれば1つ飛ばしでしか置けなくなるので置ける回数は減る。", "calc": "①日本語で言う: フィルタを画像の端から端まで、はみ出さずに置ける回数を数える。\n②小さい数字で全ステップ:\n  入力のマス   1  2  3  4  5  6\n  フィルタ幅3を置ける開始位置は 1,2,3,4 の4か所\n  (5から置こうとすると5,6,7の3マスが要るが、入力は6マス目までしか無いので置けない)\n  → 置ける回数 = 4 = 出力サイズ\n③記号版: 出力サイズ = (入力サイズ − フィルタサイズ + 2×パディング) ÷ ストライド + 1 = (6−3+2×0)÷1+1 = 4", "vs": "パディングを1にすると入力の両端に余白が1マスずつ増えるので、(6−3+2×1)÷1+1=6となり、出力サイズは4から6に増える（縮まなくなる）。ストライドを2にすると1つ飛ばしでしか置けなくなり、この例では開始位置1と3の2か所だけになって出力は2に縮む。", "why_asked": "CNNの構造を選ぶとき、層を重ねるたびに特徴マップがどれだけ縮むかを見積もれないと、ネットワークの設計や実装のサイズ指定を誤る。数値を当てはめて計算できるかを見る定番の切り口。", "usecase": "モデル設計で「この層を通すと画像は何ピクセルになるか」「最終的に全結合層につなぐときのサイズは」を事前に計算するのに使う。", "opt": ["正解。(6−3+2×0)÷1+1=4。フィルタ幅3を1マスずつずらしながら置ける回数が4通りだから。", "フィルタのサイズをそのまま出力サイズと勘違いした値。フィルタ幅3は「1回に見る範囲」であって出力の大きさではない。", "入力サイズをそのまま出力サイズにしてしまった値。パディング0・ストライド1でも、フィルタで縮む分を考慮していない。", "入力とフィルタを掛け算してしまった値。畳み込みの出力サイズは掛け算ではなく、置ける回数を数える計算で決まる。"]}'),
  ('g-kentei-g-q26', '5. ディープラーニングの要素技術',
   '畳み込み層を何層も重ねていくと、出力側の1つのマス(ノード)が実際に反映している元の画像の範囲(受容野)はどう変化するか。',
   NULL::text,
   '["層を重ねるほど受容野は広がり、深い層の1マスほど元画像の広い範囲を反映する", "層を重ねても受容野はフィルタサイズのままで、深さによって変化しない", "層を重ねるほど受容野は狭くなり、深い層の1マスはより元画像の1画素に近づく", "受容野の広さはフィルタのサイズではなく、学習率の大きさだけで決まる"]',
   0, '[0]', 'single',
   '{"asked": "CNNで層を深くすることが、1マスが「見ている」元画像の範囲(受容野)にどう影響するかを問う設問。", "point": "層を重ねるほど受容野は広がる。深い層の1マスほど、元画像の広い範囲の情報を間接的に集めている。", "kid": "受容野とは「その1マスを作るために、元の画像のどこからどこまでを参考にしたか」という範囲のこと。層を重ねるたびに、この範囲はどんどん広がっていく。", "eg": "伝言ゲームで、1人目は前の3人の話しか聞いていなくても、2人目はその1人目の話(すでに3人ぶんの情報が入っている)を聞くので、実質もっと多くの人の話を間接的に受け継いでいる。層を重ねるほど、1マスが背負っている「元の情報の広さ」が雪だるま式に増える。", "terms": [["受容野(Receptive Field)", "出力側の1つのマスが、間接的にでも参考にしている元の入力画像の範囲"], ["フィルタ(カーネル)", "1回の畳み込みで直接見る小さな範囲(例えば3×3)"]], "think": "なぜ層を重ねると受容野が広がるのかがカギ。1層目の1マスは直接フィルタの範囲(例えば3マス分)しか見ていない。2層目の1マスは、1層目の出力3マスを見るが、その3マス自体がそれぞれ1層目でさらに広い元画像の範囲を反映している。だから2層目の1マスは、1層目の3マスぶんが持っていた元画像の情報をまとめて間接的に受け継ぐことになり、直接見るマス数が変わらなくても実質の参照範囲は層を経るごとに広がっていく。これが「浅い層は輪郭のような細かい特徴、深い層は物体全体のような大きな特徴を捉える」と言われる理由でもある。", "vs": "フィルタサイズは「1回の畳み込みで直接見る範囲」で層を重ねても一定だが、受容野は「間接的に反映している範囲」で層を重ねるほど広がる。この2つを混同しない。", "why_asked": "「深いネットワークほど大きな物体や全体的な構造を捉えやすい」という設計上の理由を理解しているかを問う。フィルタサイズと受容野を同じものと誤解する受験者が多い。", "usecase": "物体検出やセグメンテーションで、大きな物体を認識するには受容野を広げる必要があると判断するときの根拠になる(1×1畳み込みやDilated畳み込み、層数の設計判断につながる)。", "opt": ["正解。層を重ねるたびに、1マスが間接的に反映している元画像の範囲が雪だるま式に広がっていくため。", "フィルタサイズは層を重ねても変わらないが、受容野(間接的に反映する範囲)は層を重ねるほど広がる点を見落としている。", "実際は逆で、層を重ねるほど受容野は広がる。1画素に近づくのではなく、より広い範囲を反映するようになる。", "受容野はフィルタサイズ・層数・ストライドなどネットワークの構造で決まるものであり、学習率(学習の進み方の調整値)とは無関係。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\">\n<text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\" font-family=\"sans-serif\">層が深いほど、1マスが見る元画像の範囲が広がる</text>\n<text x=\"30\" y=\"42\" font-size=\"10\" fill=\"#8892a4\" font-family=\"sans-serif\">入力</text>\n<g>\n<rect x=\"60\" y=\"30\" width=\"24\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<rect x=\"84\" y=\"30\" width=\"24\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<rect x=\"108\" y=\"30\" width=\"24\" height=\"20\" fill=\"#3b82f6\" fill-opacity=\"0.35\" stroke=\"#3b82f6\"/>\n<rect x=\"132\" y=\"30\" width=\"24\" height=\"20\" fill=\"#3b82f6\" fill-opacity=\"0.35\" stroke=\"#3b82f6\"/>\n<rect x=\"156\" y=\"30\" width=\"24\" height=\"20\" fill=\"#3b82f6\" fill-opacity=\"0.35\" stroke=\"#3b82f6\"/>\n<rect x=\"180\" y=\"30\" width=\"24\" height=\"20\" fill=\"#3b82f6\" fill-opacity=\"0.35\" stroke=\"#3b82f6\"/>\n<rect x=\"204\" y=\"30\" width=\"24\" height=\"20\" fill=\"#3b82f6\" fill-opacity=\"0.35\" stroke=\"#3b82f6\"/>\n<rect x=\"228\" y=\"30\" width=\"24\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<rect x=\"252\" y=\"30\" width=\"24\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/>\n</g>\n<text x=\"30\" y=\"76\" font-size=\"10\" fill=\"#8892a4\" font-family=\"sans-serif\">1層目</text>\n<rect x=\"108\" y=\"64\" width=\"24\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<rect x=\"132\" y=\"64\" width=\"24\" height=\"20\" fill=\"#c9a04a\" fill-opacity=\"0.4\" stroke=\"#c9a04a\"/>\n<rect x=\"156\" y=\"64\" width=\"24\" height=\"20\" fill=\"#c9a04a\" fill-opacity=\"0.4\" stroke=\"#c9a04a\"/>\n<rect x=\"180\" y=\"64\" width=\"24\" height=\"20\" fill=\"#c9a04a\" fill-opacity=\"0.4\" stroke=\"#c9a04a\"/>\n<rect x=\"204\" y=\"64\" width=\"24\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"30\" y=\"110\" font-size=\"10\" fill=\"#8892a4\" font-family=\"sans-serif\">2層目</text>\n<rect x=\"156\" y=\"98\" width=\"24\" height=\"20\" fill=\"#6ab08d\" fill-opacity=\"0.5\" stroke=\"#6ab08d\"/>\n<line x1=\"168\" y1=\"98\" x2=\"120\" y2=\"84\" stroke=\"#c9a04a\" stroke-width=\"1\"/>\n<line x1=\"168\" y1=\"98\" x2=\"216\" y2=\"84\" stroke=\"#c9a04a\" stroke-width=\"1\"/>\n<line x1=\"144\" y1=\"64\" x2=\"120\" y2=\"50\" stroke=\"#3b82f6\" stroke-width=\"1\"/>\n<line x1=\"192\" y1=\"64\" x2=\"216\" y2=\"50\" stroke=\"#3b82f6\" stroke-width=\"1\"/>\n<text x=\"170\" y=\"140\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\" font-family=\"sans-serif\">緑の1マス(2層目)は、入力5マス分(青)の情報を反映している</text>\n</svg>"}'),
  ('g-kentei-g-q27', '5. ディープラーニングの要素技術',
   '5×5の画像すべてを1つの出力ノードにつなぐ全結合層では、そのノードへの重みが25個必要になる。同じ範囲を3×3のフィルタ1枚の畳み込みで処理する場合、そのフィルタが持つ重みは何個か。',
   NULL::text,
   '["9", "25", "15", "1"]',
   0, '[0]', 'single',
   '{"asked": "全結合層と畳み込み層で、同じ範囲を処理するのに必要な重みの個数がどれだけ違うかを問う設問。", "point": "畳み込みのフィルタは画像のどこに当てても同じ重みを使い回す(重み共有)ので、フィルタの重み数はフィルタの大きさ(ここでは3×3=9個)だけで決まる。", "kid": "全結合層は画像の1マス1マスすべてに別々のつまみ(重み)をつなぐので、5×5=25マスなら25個のつまみが要る。畳み込みは3×3の小さな型紙を1枚だけ作って、それを画像のあちこちにずらしながら使い回す。だから型紙の中のつまみの数、つまり3×3=9個だけで済む。", "eg": "全結合はマス目ごとに専用のハンコを1個ずつ用意するようなもの。畳み込みは1個のハンコ(9マスぶんの絵柄)を紙のあちこちに何度も押していくようなもので、押す場所が増えてもハンコ自体は増えない。", "terms": [["重み共有(パラメータ共有)", "同じフィルタ(型紙)を画像の様々な場所に使い回すことで、覚えるべき数値の総数を減らす仕組み"], ["全結合層", "前の層の全てのマスと、次の層のノードを一つ残らずつなぐ層。つなぐ数だけ重みが必要"], ["パラメータ数", "モデルが学習で覚える(調整する)数値の総数"]], "think": "なぜ畳み込みだと重みが激減するのかがカギ。全結合層は「マスの位置ごとに違う重み」を持つので、画像が大きいほど、また出力ノードが増えるほど重みが爆発的に増える。畳み込みは「同じフィルタを場所を変えて何度も使う」という制約を先に置く。この制約のおかげで、フィルタを何回使っても新しい重みは増えず、フィルタ自体の大きさ(3×3なら9個)だけで済む。位置が変わっても「エッジらしさ」のような特徴の捉え方は同じでよいはずだ、という考え方が背景にあるため、この割り切りで精度を落とさずにパラメータを大きく減らせる。", "calc": "①日本語で言う: フィルタの重みの数は、フィルタ自体の大きさで決まり、画像のどこに当てても同じ重みを使い回す。\n②小さい数字で全ステップ:\n  フィルタの大きさ = たて3 × よこ3 = 9マス → 重みは9個\n  全結合なら、5×5=25マスすべてに1本ずつ線をつなぐので出力1ノードあたり25個\n  もし出力ノードが4個あれば、全結合は 25×4=100個必要だが、畳み込みはフィルタを使い回すので9個のまま変わらない\n③記号版: フィルタの重み数 = フィルタの高さ × フィルタの幅(× チャンネル数)。マスの位置には依存しない。", "vs": "全結合層は「マスの数×出力ノードの数」で重みが増えていくのに対し、畳み込み層は出力マスがいくつになっても、また画像がどれだけ大きくても、フィルタ自体の重み数(ここでは9個)は変わらない。", "why_asked": "「なぜCNNは全結合層だけのネットワークより効率的なのか」を数値で理解しているかを問う定番の切り口。重み共有の効果を言葉だけでなく数で説明できるかを見る。", "usecase": "画像のように入力が大きいデータを扱うとき、全結合層だけで組むと重みが膨大になり学習が難しくなる。畳み込み層を使えばパラメータ数を抑えたまま特徴を抽出でき、計算資源やメモリの節約にも直結する。", "opt": ["正解。フィルタの重み数はフィルタ自体の大きさ(3×3=9)で決まり、画像のどこに当てても同じ9個を使い回すため。", "全結合層で同じ範囲を処理する場合の重み数。畳み込みは重みを使い回すため、この数までは必要ない。", "3×3のフィルタを画像上で動かせる位置の数などと混同した値で、フィルタ自体の重み数ではない。", "フィルタが1個の重みだけで画像全体を処理していると勘違いした値。3×3の中身それぞれが別々のつまみを持つ。"]}'),
  ('g-kentei-g-q28', '5. ディープラーニングの要素技術',
   '1×1畳み込み(1×1コンボリューション)を使う目的として最も適切なものはどれか。',
   NULL::text,
   '["空間方向の大きさは変えずに、チャンネル数(特徴マップの枚数)を圧縮して計算量を減らす", "画像の空間方向(縦横)の大きさそのものを、半分程度にまで縮小してしまう操作である", "フィルタを飛び飛びに当てることによって、少ない層数のままより広い受容野を稼ぐ操作である", "学習中にノードの一部をランダムに無効化して過学習を防ぐ操作である"]',
   0, '[0]', 'single',
   '{"asked": "1×1畳み込みという特殊な畳み込みが何のために使われるかを問う設問。", "point": "1×1畳み込みは縦横のサイズには一切手を出さず、チャンネル数(特徴マップの枚数)だけを変える道具。", "kid": "畳み込みのフィルタは普通3×3や5×5のように面で見るが、1×1は縦横1マスしか見ない。その代わり、同じ位置にある複数のチャンネル(特徴マップの枚数ぶん)の数値をまとめて計算し直して、チャンネルの枚数を減らしたり増やしたりする。", "eg": "写真をたくさんの色フィルタ越しに重ねて撮ったような状態(チャンネルがたくさんある)を想像する。1×1畳み込みは、その場所を動かさずに「重ねた色をどう混ぜ合わせるか」だけを調整して、フィルタの枚数(チャンネル数)を減らす作業に近い。", "terms": [["チャンネル", "1枚の特徴マップの「奥行き」の枚数。例えばカラー画像の入力はR・G・Bで3チャンネル"], ["1×1畳み込み", "縦横1マスだけを見て、チャンネル方向だけを混ぜ合わせる特殊な畳み込み"], ["計算量", "モデルが1回の処理で行う掛け算・足し算の総数。多いほど処理が重くなる"]], "think": "なぜ1×1畳み込みでチャンネルを減らすと得なのかがカギ。3×3や5×5の畳み込みにかかる計算量は、入力チャンネル数と出力チャンネル数の掛け算に比例して増える。先に1×1畳み込みでチャンネル数を絞ってから普通の畳み込みをかけると、後段の畳み込みが扱うチャンネル数が減るぶん、掛け算の総数が大きく減る。縦横のサイズ(空間方向)には触れないので、画像のどこに何があるかという位置の情報は保ったまま、チャンネル方向の情報だけを整理・圧縮できる。", "vs": "縦横を縮小するのはストライドやプーリング層の役割で、1×1畳み込みはそこには関与しない。飛び飛びに当てて受容野を稼ぐのはDilated畳み込み、ノードを無効化するのはドロップアウトであり、1×1畳み込みとは別の仕組み。", "why_asked": "1×1畳み込みは「何もしていないように見えて実は計算量を減らす重要な道具」であり、名前だけ見て役割を誤解しやすい。畳み込みの中でも特殊な位置づけを理解しているかを問う。", "usecase": "GoogLeNetなど軽量なネットワーク設計で、大きなフィルタを使う前にチャンネル数を絞って計算量を抑える「ボトルネック構造」として使われる。", "opt": ["正解。1×1畳み込みは縦横の大きさを変えず、チャンネル方向の混ぜ合わせ・圧縮だけを行う。", "縦横の縮小はストライドやプーリング層が担う役割で、1×1畳み込み自体は縦横のサイズに関与しない。", "飛び飛びにフィルタを当てて受容野を広げるのはDilated(Atrous)畳み込みの役割であり、1×1畳み込みとは異なる。", "訓練中にノードを無効化するのはドロップアウトの役割で、1×1畳み込みとは無関係。"], "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\">\n<text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\" font-family=\"sans-serif\">1×1畳み込みは縦横はそのまま、チャンネル数だけを圧縮する</text>\n<g>\n<rect x=\"40\" y=\"35\" width=\"46\" height=\"46\" fill=\"#3b82f6\" fill-opacity=\"0.25\" stroke=\"#3b82f6\"/>\n<rect x=\"48\" y=\"27\" width=\"46\" height=\"46\" fill=\"#3b82f6\" fill-opacity=\"0.35\" stroke=\"#3b82f6\"/>\n<rect x=\"56\" y=\"19\" width=\"46\" height=\"46\" fill=\"#3b82f6\" fill-opacity=\"0.45\" stroke=\"#3b82f6\"/>\n<rect x=\"64\" y=\"11\" width=\"46\" height=\"46\" fill=\"#3b82f6\" fill-opacity=\"0.55\" stroke=\"#3b82f6\"/>\n</g>\n<text x=\"80\" y=\"95\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">チャンネル多い</text>\n<text x=\"80\" y=\"107\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">(縦横は同じ)</text>\n<path d=\"M 140 45 L 190 45\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#gk_arrow)\"/>\n<text x=\"165\" y=\"38\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">1×1畳み込み</text>\n<g>\n<rect x=\"230\" y=\"30\" width=\"46\" height=\"46\" fill=\"#6ab08d\" fill-opacity=\"0.35\" stroke=\"#6ab08d\"/>\n<rect x=\"238\" y=\"22\" width=\"46\" height=\"46\" fill=\"#6ab08d\" fill-opacity=\"0.55\" stroke=\"#6ab08d\"/>\n</g>\n<text x=\"255\" y=\"95\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">チャンネル少ない</text>\n<text x=\"255\" y=\"107\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">(縦横は同じ)</text>\n<defs>\n<marker id=\"gk_arrow\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\">\n<path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/>\n</marker>\n</defs>\n</svg>"}'),
  ('g-kentei-g-q29', '5. ディープラーニングの要素技術',
   'Global Average Pooling(GAP、大域平均プーリング)を全結合層の代わりに使う利点として最も適切なものはどれか。',
   NULL::text,
   '["各特徴マップを1つの平均値に圧縮し、全結合層のような大量の重みを持たずに済ませる", "画像の端の情報が失われないよう、パディングを自動的にきちんと追加してくれる操作である", "フィルタを飛び飛びに当てることで、少ない層数のまま広い受容野を得る操作である", "重みを画像全体で共有する仕組みにより、新たに局所的な特徴を抽出する操作である"]',
   0, '[0]', 'single',
   '{"asked": "分類の直前でGlobal Average Poolingを使う利点を問う設問。", "point": "GAPは特徴マップ1枚を丸ごと1つの数(平均値)にしてしまうので、全結合層のような膨大な重みが要らない。", "kid": "畳み込みの最後には、特徴マップ(画像のような形をした数値の集まり)が何枚もできている。これを普通は全部つなげて全結合層に入れるが、そのつなぎ方だと重みが大量に必要になる。GAPは、特徴マップ1枚の中の数値をぜんぶ平均して、1枚につき1個の数にまとめてしまう。", "eg": "クラス全員(1枚の特徴マップの中の数値ぜんぶ)のテストの点数を、1人ずつ覚える代わりに「クラス平均点」という1つの数字だけ覚えるようなもの。情報は大まかになるが、覚える量はぐっと減る。", "terms": [["Global Average Pooling(GAP、大域平均プーリング)", "直訳は「全体の・平均の・まとめ」。特徴マップ1枚全体を1つの平均値にまとめる操作"], ["特徴マップ", "畳み込み層が出力する、画像のどこに何の特徴があるかを表す数値の集まり"], ["全結合層", "前の層の全てのマスと次の層の全てのノードをつなぐ層。つなぐ数だけ重みが必要"]], "think": "なぜGAPだとパラメータが減るのかがカギ。全結合層で特徴マップを分類層につなぐと、特徴マップの縦×横×枚数ぶんのマス全部に、出力ノードごとの重みが必要になり数が膨大になる。GAPは特徴マップを平均するだけなので、学習して覚える重みが1つも要らない(単なる平均計算)。特徴マップの枚数と同じ数の値が出てくるだけなので、その先につなぐ重みの数も特徴マップの枚数ぶんで済み、全結合に比べて桁違いに少なくなる。重みが少ないほど過学習(訓練データだけに強くなりすぎる)も起きにくくなる。", "vs": "パディングは畳み込みの出力サイズを保つための余白の工夫、Dilated畳み込みは受容野を広げる工夫であり、どちらもGAPとは別の話。GAP自体は重みを学習する層ではなく、単純な平均計算である点も混同しやすい。", "why_asked": "近年のCNN(ResNetなど)で全結合層をGAPに置き換える設計が定番になっている理由を理解しているかを問う。", "usecase": "画像分類モデルを軽量化したいとき、最後の全結合層をGAPに置き換えることでパラメータ数とモデルサイズを大きく減らせる。", "opt": ["正解。GAPは特徴マップ1枚を1つの平均値にまとめるだけの単純な計算で、学習する重みを持たないためパラメータを大きく減らせる。", "パディングは畳み込みの出力サイズを保つための余白の工夫であり、GAPとは別の仕組み。", "受容野を広げるのはDilated(Atrous)畳み込みの役割で、GAPは特徴マップを平均するだけの操作。", "GAPは学習する重みを持たない単純な平均計算であり、局所的な特徴を新たに抽出する働きは畳み込み層が担う。"], "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\">\n<text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\" font-family=\"sans-serif\">GAPは特徴マップ1枚ごと、丸ごと平均して1つの数にする</text>\n<rect x=\"40\" y=\"30\" width=\"50\" height=\"50\" fill=\"#3b82f6\" fill-opacity=\"0.3\" stroke=\"#3b82f6\"/>\n<rect x=\"48\" y=\"22\" width=\"50\" height=\"50\" fill=\"#60a5fa\" fill-opacity=\"0.3\" stroke=\"#60a5fa\"/>\n<text x=\"55\" y=\"95\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">特徴マップ(複数枚)</text>\n<path d=\"M 130 48 L 175 48\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#gk_arrow2)\"/>\n<text x=\"152\" y=\"41\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">平均</text>\n<circle cx=\"205\" cy=\"38\" r=\"12\" fill=\"#6ab08d\" fill-opacity=\"0.4\" stroke=\"#6ab08d\"/>\n<circle cx=\"205\" cy=\"60\" r=\"12\" fill=\"#6ab08d\" fill-opacity=\"0.4\" stroke=\"#6ab08d\"/>\n<text x=\"205\" y=\"95\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">枚数と同じ数の値</text>\n<path d=\"M 225 48 L 260 48\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#gk_arrow2)\"/>\n<rect x=\"270\" y=\"20\" width=\"50\" height=\"60\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"295\" y=\"45\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">そのまま</text>\n<text x=\"295\" y=\"58\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">分類層へ</text>\n<defs>\n<marker id=\"gk_arrow2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\">\n<path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/>\n</marker>\n</defs>\n</svg>"}'),
  ('g-kentei-g-q30', '5. ディープラーニングの要素技術',
   'Dilated Convolution(Atrous畳み込み、拡張畳み込み)の仕組みとして最も適切なものはどれか。',
   NULL::text,
   '["フィルタの各マスの間に隙間をあけて画像上に当てることで、層を増やさずに受容野を広げる", "フィルタを画像上で重なりなく敷き詰めて当て、それぞれの範囲の代表値だけを残して縮小する", "画像の外側に余白を足すことで、畳み込み後の出力サイズが小さくなりすぎないようにする", "同じフィルタを画像全体で使い回すことで、覚えるべき重みの数を減らす"]',
   0, '[0]', 'single',
   '{"asked": "Dilated(Atrous)畳み込みという特殊な畳み込みの仕組みを問う設問。", "point": "Dilated畳み込みはフィルタのマスの間に隙間をあけて当てるので、フィルタの大きさ(重みの数)は変えずに見る範囲(受容野)だけを広げられる。", "kid": "普通の畳み込みはフィルタの3マスなら隣り合った3マスをそのまま見る。Dilated畳み込みは、その3マスの間に隙間を1マスずつ空けて、飛び飛びに見る。同じ3マスぶんの重みしか使わないのに、見る範囲(端から端までの幅)は広くなる。", "eg": "写真を見るとき、隣り合った3人だけを見るのと、1人おきに(1番目・3番目・5番目)3人を見るのとでは、同じ「3人を見る」でも、後者のほうが見渡す幅は広い。Dilated畳み込みはこの「1人おき」の見方をフィルタでやる。", "terms": [["Dilated Convolution(拡張畳み込み、Atrous畳み込み)", "直訳は「広げられた・畳み込み」。フィルタのマスの間に隙間をあけて当てる畳み込み"], ["受容野", "出力の1マスが間接的に反映している元画像の範囲"], ["dilation rate(拡張率)", "フィルタのマスの間に空ける隙間の大きさを決める値。1なら普通の畳み込みと同じ"]], "think": "なぜ隙間を空けると受容野が広がるのにパラメータは増えないのかがカギ。受容野を広げる方法は本来、フィルタを大きくする(3×3を5×5にする)か、層を重ねるかのどちらかで、どちらもパラメータや計算量、あるいはネットワークの深さが増えてしまう。Dilated畳み込みは、フィルタの中身の数(重みの数)はそのままに、当てる位置だけを飛び飛びにする。フィルタが実際にカバーする端から端までの幅は広がるが、掛け算する重みの個数は増えないので、少ない層数・少ないパラメータのまま広い範囲の情報を1回の畳み込みで捉えられる。", "vs": "重なりなくフィルタを敷き詰めて代表値を残すのはプーリング層、外側に余白を足すのはパディング、フィルタを使い回して重みを減らすのは(Dilatedに限らずすべての畳み込みに共通する)重み共有の性質であり、いずれもDilated畳み込みの定義そのものではない。", "why_asked": "セマンティックセグメンテーションなど、画像の細かい位置情報を保ちながら広い範囲を見たい場面で使われる技術で、プーリングによる縮小と対比して理解しているかを問う。", "usecase": "セグメンテーションのように出力も画像の形をしていてほしいタスクで、プーリングで縮小せずに受容野だけを広げたいときに使う。", "opt": ["正解。フィルタのマスの間に隙間をあけて当てることで、重みの数は変えずに見る範囲(受容野)だけを広げる仕組みだから。", "重なりなくフィルタを敷き詰めて代表値だけを残すのはプーリング層の仕組みであり、Dilated畳み込みとは異なる。", "外側に余白を足して出力サイズを保つのはパディングの役割であり、Dilated畳み込みが直接行う操作ではない。", "フィルタを使い回して重みの数を減らす(重み共有)のは通常の畳み込みにも共通する性質で、Dilated畳み込み固有の特徴ではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\">\n<text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\" font-family=\"sans-serif\">フィルタのマスの間に隙間をあけて、広い範囲を見る</text>\n<text x=\"80\" y=\"36\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\" font-family=\"sans-serif\">ふつうの畳み込み</text>\n<g>\n<rect x=\"35\" y=\"45\" width=\"90\" height=\"30\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<line x1=\"65\" y1=\"45\" x2=\"65\" y2=\"75\" stroke=\"#2a2f3f\"/>\n<line x1=\"95\" y1=\"45\" x2=\"95\" y2=\"75\" stroke=\"#2a2f3f\"/>\n<rect x=\"35\" y=\"45\" width=\"30\" height=\"30\" fill=\"#3b82f6\" fill-opacity=\"0.4\"/>\n<rect x=\"65\" y=\"45\" width=\"30\" height=\"30\" fill=\"#3b82f6\" fill-opacity=\"0.4\"/>\n<rect x=\"95\" y=\"45\" width=\"30\" height=\"30\" fill=\"#3b82f6\" fill-opacity=\"0.4\"/>\n</g>\n<text x=\"80\" y=\"98\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">3マス連続で見る</text>\n<text x=\"255\" y=\"36\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\" font-family=\"sans-serif\">Dilated畳み込み</text>\n<g>\n<rect x=\"170\" y=\"45\" width=\"170\" height=\"30\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<rect x=\"170\" y=\"45\" width=\"30\" height=\"30\" fill=\"#6ab08d\" fill-opacity=\"0.4\"/>\n<rect x=\"240\" y=\"45\" width=\"30\" height=\"30\" fill=\"#6ab08d\" fill-opacity=\"0.4\"/>\n<rect x=\"310\" y=\"45\" width=\"30\" height=\"30\" fill=\"#6ab08d\" fill-opacity=\"0.4\"/>\n<rect x=\"200\" y=\"45\" width=\"40\" height=\"30\" fill=\"none\" stroke=\"#2a2f3f\" stroke-dasharray=\"3,3\"/>\n<rect x=\"270\" y=\"45\" width=\"40\" height=\"30\" fill=\"none\" stroke=\"#2a2f3f\" stroke-dasharray=\"3,3\"/>\n</g>\n<text x=\"255\" y=\"98\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">同じ3マスで、隙間ぶん広い範囲を見る</text>\n<text x=\"170\" y=\"122\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">使う数値の個数(パラメータ数)はどちらも3のまま</text>\n</svg>"}'),
  ('g-kentei-g-q31', '5. ディープラーニングの要素技術',
   'Self-Attention(自己注意)とEncoder-Decoder Attention(Source-Target Attention)の違いとして最も適切なものはどれか。',
   NULL::text,
   '["Self-Attentionは同じ系列内で注目先を計算し、もう一方は出力側が入力側を参照する", "Self-Attentionはエンコーダでは使われず、デコーダの中だけで使われる仕組みである", "Encoder-Decoder Attentionは画像認識専用の仕組みで、自然言語処理には使われない", "Self-Attentionは1つの単語しか参照できず、もう一方は系列全体を参照できる"]',
   0, '[0]', 'single',
   '{"asked": "Self-AttentionとEncoder-Decoder Attentionという2種類のAttentionが、それぞれ「どの系列とどの系列の間」で注目先を計算するかの違いを問う設問。", "point": "「自分自身の中で見るか(Self)」「相手の系列を見るか(Encoder-Decoder)」がこの2つを見分ける決め手。", "kid": "Attention(注意機構)は「今作っている出力に対して、どこの情報を強く参考にするか」を重み付けして決める仕組み。Self-Attentionは、ある文の中の単語が、同じ文の中の他の単語を見て注目先を決める。Encoder-Decoder Attentionは、出力を作っている側(デコーダ)が、入力側(エンコーダ)の情報を見に行って注目先を決める。", "eg": "Self-Attentionは、1つの文章を読みながら「この『それ』は、同じ文中のどの単語を指しているか」を自分の中で探すようなもの。Encoder-Decoder Attentionは、日本語を英語に訳すときに、英単語を1つ書くたびに元の日本語文のどの部分を見返すか、別の資料(入力文)を参照しに行くようなもの。", "terms": [["Self-Attention(自己注意)", "同じ系列(同じ文など)の中の要素どうしで、どこに注目すべきかを計算する仕組み"], ["Encoder-Decoder Attention(Source-Target Attention)", "デコーダ側の要素が、エンコーダ側の出力(入力系列の情報)に対して注目先を計算する仕組み"], ["エンコーダ", "入力系列を読み込んで、意味を凝縮した表現に変換する側"], ["デコーダ", "エンコーダが作った表現をもとに、出力系列を1つずつ生成していく側"]], "vs": "この2つはどちらも「Query・Key・Valueで重み付けして混ぜる」という計算の仕組み自体は同じで、違うのはQueryとKey/Valueがどの系列から来るかという点。Self-AttentionはQuery・Key・Valueすべて同じ系列から来るが、Encoder-Decoder AttentionはQueryがデコーダ側、Key・Valueがエンコーダ側から来る。名前が似ているため試験でも定番の引っかけになる。", "why_asked": "Transformerの構造理解を問う頻出テーマ。同じ「Attention」という言葉でも、どの系列とどの系列の間で計算しているかを区別できないと、翻訳モデルの内部構造(エンコーダ・デコーダ間の橋渡し)を正しく説明できない。", "usecase": "機械翻訳や要約のように、入力系列と出力系列が別々に存在するタスクの構造を理解し設計するときに、この区別が必要になる。", "opt": ["正解。Self-Attentionは同じ系列内で注目先を計算し、Encoder-Decoder Attentionはデコーダ側からエンコーダ側の出力を参照する。", "Self-Attentionはエンコーダ内でもデコーダ内でも使われる仕組みであり、デコーダ限定ではない。", "Encoder-Decoder Attentionは自然言語処理(機械翻訳など)で広く使われる仕組みであり、画像認識専用ではない。", "Self-Attentionも系列全体を見渡して注目先を計算できる仕組みであり、1つの単語しか参照できないわけではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\">\n<text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\" font-family=\"sans-serif\">どちらの系列を見に行くかが違う</text>\n<text x=\"80\" y=\"34\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\" font-family=\"sans-serif\">Self-Attention</text>\n<rect x=\"30\" y=\"42\" width=\"20\" height=\"18\" fill=\"#3b82f6\" fill-opacity=\"0.4\" stroke=\"#3b82f6\"/>\n<rect x=\"60\" y=\"42\" width=\"20\" height=\"18\" fill=\"#3b82f6\" fill-opacity=\"0.4\" stroke=\"#3b82f6\"/>\n<rect x=\"90\" y=\"42\" width=\"20\" height=\"18\" fill=\"#3b82f6\" fill-opacity=\"0.4\" stroke=\"#3b82f6\"/>\n<rect x=\"120\" y=\"42\" width=\"20\" height=\"18\" fill=\"#6ab08d\" fill-opacity=\"0.55\" stroke=\"#6ab08d\"/>\n<path d=\"M 130 60 C 105 80, 55 80, 40 60\" stroke=\"#8892a4\" stroke-width=\"1\" fill=\"none\"/>\n<path d=\"M 130 60 C 115 75, 85 75, 70 60\" stroke=\"#8892a4\" stroke-width=\"1\" fill=\"none\"/>\n<text x=\"85\" y=\"98\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">同じ系列の中で注目先を探す</text>\n<text x=\"255\" y=\"34\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\" font-family=\"sans-serif\">Encoder-Decoder Attention</text>\n<rect x=\"195\" y=\"48\" width=\"18\" height=\"16\" fill=\"#60a5fa\" fill-opacity=\"0.4\" stroke=\"#60a5fa\"/>\n<rect x=\"222\" y=\"48\" width=\"18\" height=\"16\" fill=\"#60a5fa\" fill-opacity=\"0.4\" stroke=\"#60a5fa\"/>\n<rect x=\"249\" y=\"48\" width=\"18\" height=\"16\" fill=\"#60a5fa\" fill-opacity=\"0.4\" stroke=\"#60a5fa\"/>\n<text x=\"230\" y=\"42\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\" font-family=\"sans-serif\">入力側(エンコーダ)</text>\n<rect x=\"290\" y=\"82\" width=\"20\" height=\"18\" fill=\"#c9a04a\" fill-opacity=\"0.55\" stroke=\"#c9a04a\"/>\n<path d=\"M 300 82 C 280 70, 250 60, 222 64\" stroke=\"#8892a4\" stroke-width=\"1\" fill=\"none\"/>\n<path d=\"M 300 82 C 285 70, 265 62, 249 64\" stroke=\"#8892a4\" stroke-width=\"1\" fill=\"none\"/>\n<text x=\"260\" y=\"115\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">出力側(デコーダ)が入力側を見に行く</text>\n</svg>", "think": "どちらも Query・Key・Value で重み付けして混ぜる計算は同じで、材料をどの系列から取るかだけが違う、が背骨。Self-Attention は Query も Key も Value も同じ系列（自分自身）から取る。だから「この文の中で、どの単語とどの単語が関係し合うか」を捉えられる。Encoder-Decoder Attention は Query を出力側（デコーダ）から、Key と Value を入力側（エンコーダ）から取る。だから「いま出力しようとしている単語は、入力文のどこを見るべきか」を捉えられる。翻訳の Transformer では、まず Self-Attention で入力文の中の関係を整理し、次に Encoder-Decoder Attention で入力文を参照しながら訳語を選ぶ、という分担になっている。"}'),
  ('g-kentei-g-q32', '5. ディープラーニングの要素技術',
   'Attention機構の計算で使われるQuery(クエリ)・Key(キー)・Value(バリュー)の役割として最も適切なものはどれか。',
   NULL::text,
   '["QueryをKeyと照合して注目の重みを決め、その重みでValueを混ぜて出力を作る", "Queryは出力そのものを表し、KeyとValueは学習中にのみ使われる仕組みである", "Keyは正解ラベルを表し、QueryとValueで誤差を計算するための仕組みである", "Valueは注目の重みそのものを表し、QueryとKeyが最終出力を作るために使われる"]',
   0, '[0]', 'single',
   '{"asked": "Attentionの計算を構成するQuery・Key・Valueという3つの要素それぞれの役割を問う設問。", "point": "「Queryで探し、Keyと照らし合わせて重みを決め、Valueをその重みで混ぜる」の順番がQ・K・Vの決め手。", "kid": "Query(問い合わせ)は「今なにを知りたいか」という質問。Key(目印)は各情報につけられた「これはこういう情報です」という札。Value(中身)はその情報の実際の中身。QueryとKeyを見比べて「どれだけ似ているか(注目すべきか)」を計算し、その度合いを重みとして、対応するValueを混ぜ合わせたものが出力になる。", "eg": "図書館で本を探す場面に近い。Query は自分が調べたいテーマ(質問)。Key は本の背表紙のタイトル(目印)。Value は本の中身そのもの。テーマ(Query)とタイトル(Key)を見比べて関連が強い本ほど重視し、その本の中身(Value)を多めに参考にしてレポートをまとめる、という流れ。", "terms": [["Query(クエリ)", "直訳は「問い合わせ」。今なにに注目したいかを表すベクトル"], ["Key(キー)", "直訳は「鍵・目印」。各要素につけられた、照合に使う目印のベクトル"], ["Value(バリュー)", "直訳は「値・中身」。実際に混ぜ合わされる情報の中身のベクトル"]], "think": "なぜこの3段階に分けるのかがカギ。もし「探すための目印」と「実際の中身」を分けずに同じベクトルを使うと、似ている・似ていないの判定(照合)と、実際に運ぶ情報(中身)がいつも同じものになってしまい、柔軟な注目のしかたができない。QueryとKeyを使って「どこに注目すべきか」だけを先に計算し、その結果の重みを使ってValue(中身)を混ぜ合わせるという2段階に分けることで、「照合の基準」と「運ぶ情報」を別々に学習でき、より柔軟に注目先を選べるようになる。", "vs": "QueryとKeyは「どれだけ注目するか」という重みを決めるための計算にだけ使われ、実際に出力に混ざる中身はValueである点を混同しない。またQ・K・Vはすべて推論時にも使われる現役の計算要素であり、学習中だけの仕組みではない。", "why_asked": "Attentionの内部計算を「なんとなく重み付けする仕組み」で止めず、Q・K・Vそれぞれの役割まで理解しているかを問う頻出テーマ。", "usecase": "Transformerベースのモデルの動作を説明したり、Attentionの可視化(どの単語がどこに注目しているか)を読み解いたりするときの基礎になる。", "opt": ["正解。QueryとKeyの照合で注目の重みを決め、その重みでValueを混ぜ合わせて出力を作る。", "Q・K・Vはいずれも推論時にも使われる計算要素であり、学習中にだけ必要になるものではない。", "正解ラベルとの誤差計算に使われるのはAttentionの外側の損失関数の役割であり、Keyは正解ラベルではない。", "注目の重みはQueryとKeyの照合によって計算されるものであり、Valueは重みではなく実際に混ぜ合わされる中身である。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\">\n<text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\" font-family=\"sans-serif\">Queryで探し、Keyと照合し、Valueを重み付けして混ぜる</text>\n<rect x=\"20\" y=\"35\" width=\"60\" height=\"26\" fill=\"#3b82f6\" fill-opacity=\"0.3\" stroke=\"#3b82f6\"/>\n<text x=\"50\" y=\"52\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\" font-family=\"sans-serif\">Query</text>\n<text x=\"50\" y=\"75\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\" font-family=\"sans-serif\">何を知りたいか</text>\n<path d=\"M 82 48 L 118 48\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#gk_arrow3)\"/>\n<rect x=\"120\" y=\"20\" width=\"55\" height=\"22\" fill=\"#c9a04a\" fill-opacity=\"0.3\" stroke=\"#c9a04a\"/>\n<text x=\"147\" y=\"35\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\" font-family=\"sans-serif\">Key A</text>\n<rect x=\"120\" y=\"48\" width=\"55\" height=\"22\" fill=\"#c9a04a\" fill-opacity=\"0.3\" stroke=\"#c9a04a\"/>\n<text x=\"147\" y=\"63\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\" font-family=\"sans-serif\">Key B</text>\n<text x=\"147\" y=\"88\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\" font-family=\"sans-serif\">目印と照合</text>\n<path d=\"M 178 31 L 210 40\" stroke=\"#8892a4\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/>\n<path d=\"M 178 59 L 210 46\" stroke=\"#8892a4\" stroke-width=\"1.5\"/>\n<text x=\"195\" y=\"52\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\" font-family=\"sans-serif\">重み</text>\n<rect x=\"215\" y=\"20\" width=\"55\" height=\"22\" fill=\"#6ab08d\" fill-opacity=\"0.25\" stroke=\"#6ab08d\"/>\n<text x=\"242\" y=\"35\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\" font-family=\"sans-serif\">Value A</text>\n<rect x=\"215\" y=\"48\" width=\"55\" height=\"22\" fill=\"#6ab08d\" fill-opacity=\"0.55\" stroke=\"#6ab08d\"/>\n<text x=\"242\" y=\"63\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\" font-family=\"sans-serif\">Value B</text>\n<path d=\"M 272 45 L 300 45\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#gk_arrow3)\"/>\n<rect x=\"302\" y=\"34\" width=\"30\" height=\"22\" fill=\"#e8eaf0\" fill-opacity=\"0.15\" stroke=\"#e8eaf0\"/>\n<text x=\"317\" y=\"49\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\" font-family=\"sans-serif\">出力</text>\n<text x=\"147\" y=\"112\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">重みが大きいValueほど強く出力に混ざる</text>\n<defs>\n<marker id=\"gk_arrow3\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\">\n<path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/>\n</marker>\n</defs>\n</svg>"}'),
  ('g-kentei-g-q33', '5. ディープラーニングの要素技術',
   'デノイジングオートエンコーダが、通常のオートエンコーダと異なる工夫として最も適切なものはどれか。',
   NULL::text,
   '["入力にノイズを混ぜてから、ノイズのない元の入力を復元するように学習させる", "圧縮した表現を確率分布として扱い、新しいデータをサンプリングして生成する", "エンコーダとデコーダの間に畳み込み層を挟み、局所的な特徴だけを抽出する", "正解ラベルを使って教師あり学習として訓練し、分類タスクに直接使えるようにする"]',
   0, '[0]', 'single',
   '{"asked": "デノイジングオートエンコーダという派生形が、通常のオートエンコーダに加えるどんな工夫かを問う設問。", "point": "「わざとノイズを混ぜた入力」から「ノイズのない元の姿」を復元させるのがデノイジングオートエンコーダの決め手。", "kid": "普通のオートエンコーダは、入力をそのまま圧縮して、そのまま復元できるように学習する。デノイジングオートエンコーダは、入力にわざと汚れ(ノイズ)を混ぜたものを渡しておいて、汚れのない元の姿を当てさせるように学習する。", "eg": "写真に少し傷や汚れをつけたコピーだけを見せて、「元のきれいな写真を描いてみて」と練習させるようなもの。汚れがあっても元の絵柄がわかるくらい本質的な特徴を覚えないと、この練習では正解にたどり着けない。", "terms": [["デノイジングオートエンコーダ(Denoising Autoencoder)", "直訳は「除去する・ノイズの・自動符号化器」。ノイズを混ぜた入力から元のきれいな入力を復元するように学習するオートエンコーダ"], ["オートエンコーダ", "入力を一度低次元に圧縮し、そこから元の入力を復元するように学習するネットワーク"], ["ノイズ", "元のデータにわざと加える、ランダムな乱れや汚れ"]], "think": "なぜノイズを混ぜると頑健な特徴になるのかがカギ。ノイズを混ぜずに「入力をそのまま復元する」練習だけでは、細かいノイズの1つ1つまで丸暗記してしまえば復元できてしまい、本当に大事な特徴(全体の形や構造)を捉えなくても正解にたどり着ける抜け道が残る。ノイズを混ぜた入力から元のきれいな姿を当てさせると、細かいノイズをそのまま覚えても正解にならないので、ノイズに惑わされない本質的な特徴(輪郭や大まかな構造)を捉えないと復元できなくなる。結果として、少々の乱れがあっても崩れにくい頑健な特徴を学ぶようになる。", "vs": "圧縮表現を確率分布として扱い新しいデータを生成できるのは変分オートエンコーダ(VAE)の工夫であり、デノイジングオートエンコーダとは別の派生形。オートエンコーダはラベルを使わない教師なし学習であり、正解ラベルを使う教師あり学習ではない。", "why_asked": "オートエンコーダには目的に応じたいくつかの派生形(デノイジング・変分など)があり、それぞれの工夫を区別できるかを問う頻出テーマ。", "usecase": "画像のノイズ除去や、多少荒れた入力データからでも安定して特徴を抽出したい前処理・特徴抽出の場面で使われる。", "opt": ["正解。ノイズを混ぜた入力から元のきれいな入力を復元させることで、ノイズに惑わされない頑健な特徴を学習する。", "圧縮表現を確率分布として扱い新しいデータを生成できるようにするのは変分オートエンコーダ(VAE)の工夫であり、デノイジングオートエンコーダとは別物。", "畳み込み層を挟むかどうかは実装上の選択であり、デノイジングオートエンコーダを特徴づける工夫そのものではない。", "オートエンコーダはラベルを使わない教師なし学習として訓練されるものであり、正解ラベルを使う教師あり学習ではない。"]}'),
  ('g-kentei-g-q34', '5. ディープラーニングの要素技術',
   '画像からエッジ(輪郭)を検出するようなフィルタの与え方について、CNN以前の画像処理とCNNの違いとして最も適切なものはどれか。',
   NULL::text,
   '["CNN以前は人がフィルタを設計していたが、CNNはフィルタの値を学習で獲得する", "CNN以前もCNNも、フィルタの値は必ず人の手で設計して固定する点で変わらない", "CNNではフィルタという考え方自体を使わず、全結合層だけで特徴を抽出する", "CNN以前は畳み込みという計算自体が存在せず、プーリングだけで特徴を抽出した"]',
   0, '[0]', 'single',
   '{"asked": "エッジ検出のようなフィルタを「誰が」「どうやって」決めるかについて、CNN以前とCNNの違いを問う設問。", "point": "CNN以前は人がフィルタを設計、CNNはフィルタの値そのものをデータから学習で獲得するのが決め手。", "kid": "画像から輪郭を見つける計算そのもの(フィルタを画像にかけるという操作)は、CNNが登場する前から画像処理の分野で使われていた。ただし、その「どんな数値のフィルタを使うか」は、CNN以前は人間が「輪郭を強調するにはこの並びの数値がよい」と考えて手で設計していた。CNNでは、フィルタの中の数値そのものを、訓練データを使って自動的に学習で見つけ出す。", "eg": "料理で言えば、CNN以前は「このレシピ(フィルタの数値)なら輪郭がきれいに出る」と料理人(人間)が試行錯誤して決めていたようなもの。CNNは、大量の写真とお手本を見せながら、機械自身に「どんな味付け(数値)がいちばん役に立つか」を練習させて見つけさせるようなもの。", "terms": [["フィルタ(カーネル)", "畳み込みで画像に当てる小さな数値の並び。値によってエッジ検出やぼかしなど、抽出できる特徴が変わる"], ["特徴量エンジニアリング", "CNN以前によく行われた、人間が知識や経験をもとに特徴の取り出し方を設計する作業"], ["End-to-Endの学習(誤差逆伝播)", "直訳は「端から端までの」。入力から出力までの一連の処理を、人手で分けずにまとめて訓練データから学習する考え方"]], "think": "なぜ「学習で獲得する」ことが重要な違いなのかがカギ。人がフィルタを設計する場合、その人が思いつく範囲の特徴しか捉えられず、対象が変わるたびに設計をやり直す必要がある。CNNでは、フィルタの中身を固定の答えとして与えず、訓練データに対する予測の誤差が小さくなるように、誤差逆伝播でフィルタの数値そのものを少しずつ調整していく。この結果、人が思いつかなかったような、そのタスクに最適な特徴の取り出し方を、データから自動的に見つけ出せるようになる。", "vs": "「畳み込みという計算をするかどうか」はCNN以前とCNNで共通しており、違うのは「フィルタの中身を誰が・どうやって決めるか」という点。この2つを混同しない。", "why_asked": "「CNNの何が新しかったのか」を、計算の仕組みではなく学習の仕組みとして理解しているかを問う。ディープラーニングが従来の画像処理と決定的に違う点を突く頻出テーマ。", "usecase": "画像認識モデルを設計するとき、特徴抽出を人手で作り込む必要がなく、大量のデータさえあればタスクに合った特徴を自動で獲得できるという利点を説明する根拠になる。", "opt": ["正解。CNN以前はフィルタを人が設計していたが、CNNはフィルタの値そのものを訓練データから学習で獲得する。", "CNN最大の特徴は、フィルタの値を人手ではなく学習によって獲得する点にあり、CNN以前とは異なる。", "CNNは畳み込み層(フィルタを使う層)を中心に構成されており、フィルタという考え方自体は使われている。", "畳み込みという計算自体は、CNN以前の画像処理(エッジ検出など)でも使われていた。プーリングだけで特徴を抽出していたわけではない。"]}'),
  ('g-kentei-g-q35', '5. ディープラーニングの要素技術',
   '手書き数字の「6」を認識するモデルを訓練するためのデータ拡張として、避けるべき変形はどれか。',
   NULL::text,
   '["画像を180度近くまで回転させる変形(6が9に見えるようになる変形)", "画像をわずかに左右・上下へずらすだけの、平行移動させる程度の変形", "画像の明るさやコントラストだけを、ごくわずかにだけ変化させる程度の変形", "画像の大きさをわずかに拡大・縮小させる変形"]',
   0, '[0]', 'single',
   '{"asked": "データ拡張(データオーグメンテーション)で使う変形のうち、場面によっては使うべきでないものを見分ける設問。", "point": "変形させた結果、見た目が別のラベルの見え方に変わってしまう変形は避ける、が決め手。", "kid": "データ拡張は、手元の画像を少しだけ変形させて訓練データを水増しし、様々な見え方に慣れさせて過学習(訓練データだけに強くなりすぎること)を防ぐ工夫。ただし、変形のしかたによっては、変形後の画像が別の答えに見えてしまうことがある。手書きの「6」を大きく回転させると「9」に見えてしまい、画像には「9」のような形が写っているのにラベルは「6」のまま、という矛盾したデータになってしまう。", "eg": "テスト勉強で、問題と答えのペアを増やそうとして、問題文をあまりに大きく書き換えてしまい、答えが違う問題になってしまったのに、もとの答えをそのまま貼り付けてしまうようなもの。増やしたつもりが、間違ったお手本を教え込むことになる。", "terms": [["データ拡張(データオーグメンテーション)", "手元のデータを回転・反転・拡大縮小・明るさ変更などで少しずつ変形させ、訓練データを水増しする手法"], ["ラベル", "その画像が「何であるか」を表す正解の答え(この場合は数字の「6」)"], ["過学習", "訓練データだけに強くなりすぎて、新しいデータにうまく対応できなくなる状態"]], "think": "なぜ回転だけが問題になるのかがカギ。データ拡張のそもそもの狙いは、「同じ意味を持つ見え方のバリエーション」を増やして、モデルにその意味の本質を学ばせること。左右にずらす・明るさを変える・少し拡大縮小するといった変形は、見た目が変わっても「6」であるという意味は変わらないので、ラベルはそのままで使ってよい。ところが180度近い回転は、「6」という形そのものを「9」という別の数字の形に変えてしまう。変形後の画像の見た目と、そのままつけられた「6」というラベルが食い違ってしまい、モデルに間違った対応関係を教え込むことになる。だから、ラベルの意味を変えてしまう変形は避ける必要がある。", "vs": "同じ「回転」でも、ごくわずかな角度(数度程度)の回転は「6」の形を保ったままなので問題にならない。「大きく回転させると意味が変わる」という点であり、回転そのものが常にダメというわけではない。", "why_asked": "データ拡張は「変形すれば何でも安全」と思われがちだが、対象によっては変形がラベルの意味を変えてしまう場面があることを理解しているかを問う。場面判断を求める定番の切り口。", "usecase": "文字認識・標識認識など、向きや形が意味そのものに直結するタスクでデータ拡張を設計するとき、どの変形なら安全かを判断する基準になる。", "opt": ["正解。180度近い回転は「6」の形を「9」に近づけてしまい、画像の見た目と正解ラベルが矛盾するデータを作ってしまうため。", "わずかな平行移動は「6」という形の意味を変えないので、データ拡張として問題なく使える変形。", "わずかな明るさ・コントラストの変化は「6」という形自体には影響しないので、データ拡張として問題なく使える変形。", "わずかな拡大・縮小は「6」という形の意味を変えないので、データ拡張として問題なく使える変形。"]}'),
  ('g-kentei-g-q36', '5. ディープラーニングの要素技術',
   '系列を1つずつ生成するモデル(文章生成など)を訓練するとき、教師強制(Teacher Forcing)と呼ばれる工夫として最も適切なものはどれか。',
   NULL::text,
   '["各時刻の次の入力に、モデルの予測ではなく正解の系列をそのまま使う", "各時刻の次の入力に、モデル自身が直前に出した予測を必ず使い続ける", "訓練データにわざとノイズを混ぜて、頑健な特徴を学習させる", "訓練中に一部のノードをランダムに無効化して、過学習を防ぐ"]',
   0, '[0]', 'single',
   '{"asked": "系列生成モデルの訓練時に使われる教師強制という工夫が、具体的に何をしているかを問う設問。", "point": "教師強制は、訓練中の「次の入力」にモデルの予測ではなく正解をそのまま使う、が決め手。", "kid": "文章を1単語ずつ作っていくモデルは、ある時点で単語を予測したら、次の時点ではその予測した単語を入力として使い、続きを予測していく。ただし訓練の最初のうちはモデルの予測がまだ下手で、間違った単語を次の入力にしてしまうと、そこから先もどんどんズレていってしまう。教師強制は、訓練中に限って「モデル自身の予測」ではなく「本当の正解の単語」を次の入力として使う工夫。", "eg": "作文の練習で、1文字書くごとに先生が「その続きはこう書くんだよ」と正解の文字を渡してくれるようなもの。自分の書いた(間違っているかもしれない)文字をもとに続きを書かせるより、正解をもとに書かせたほうが、練習の途中で話がどんどんズレていかない。", "terms": [["教師強制(Teacher Forcing)", "直訳は「先生に・強制させる」。訓練時に、次の時点の入力として正解の系列を使う工夫"], ["系列生成", "文章や音声のように、順番のある要素を1つずつ作り出していくタスク"], ["露出バイアス(Exposure Bias)", "訓練では常に正解を見せられるのに、実際に使うとき(推論時)は自分の予測しか見られないために生じる、訓練と本番のギャップ"]], "think": "なぜ正解を使うと訓練しやすくなるのかがカギ。もし訓練中も「モデル自身の予測」を次の入力に使うと、訓練の初期はモデルがまだ未熟で予測を外しやすく、1つ目の単語を間違えると2つ目、3つ目とズレが積み重なっていき、どこがどう間違っているのか学習の手がかりが混乱してしまう。教師強制で正解を次の入力に固定すると、各時点の予測を独立に「この状況ならこの単語」という形で安定して訓練でき、学習が早く安定して進む。ただし本番(推論時)は正解が手に入らず自分の予測を使うしかないため、訓練と本番でモデルが経験する入力にズレ(露出バイアス)が生じる、という副作用もある。", "vs": "教師強制は「次の入力に何を使うか」という訓練時特有の工夫であり、入力にノイズを混ぜるデノイジングオートエンコーダの工夫や、ノードを無効化するドロップアウトとは別の仕組み。", "why_asked": "RNNやTransformerを使った系列生成モデルの訓練の仕組みとして頻出。訓練時と推論時でモデルの動き方が違うという、見落としやすいポイントを突く。", "usecase": "機械翻訳や文章生成モデルを訓練するときの標準的な手法で、訓練を安定させ収束を早める効果がある。", "opt": ["正解。訓練中は次の入力にモデル自身の予測ではなく正解の系列をそのまま使うことで、誤りの積み重なりを防ぎ訓練を安定させる。", "モデル自身の予測を次の入力に必ず使うのは教師強制をしない場合の動き方であり、教師強制そのものの説明ではない。", "入力にノイズを混ぜて頑健な特徴を学ばせるのはデノイジングオートエンコーダの工夫であり、教師強制とは別の仕組み。", "ノードをランダムに無効化するのはドロップアウトの仕組みであり、教師強制とは別の工夫。"]}'),
  ('g-kentei-g-q37', '5. ディープラーニングの要素技術',
   'Transformerの各層でよく使われる「Add & Norm」という構成が指しているものとして最も適切なものはどれか。',
   NULL::text,
   '["残差接続(入力を足し込む近道)とレイヤー正規化を組み合わせた構成", "複数の異なる観点のAttentionを同時に計算して組み合わせる構成", "系列の中の位置情報を表すベクトルを入力にあらかじめ足す構成", "訓練中に一部のノードを無効化してから、残りを正規化する構成"]',
   0, '[0]', 'single',
   '{"asked": "Transformerの各層に組み込まれている「Add & Norm」というブロックが具体的に何を指しているかを問う設問。", "point": "「Add」は残差接続(入力をそのまま足す近道)、「Norm」はレイヤー正規化(値のばらつきをそろえる仕上げ)を指すのが決め手。", "kid": "Transformerの各層は、Attentionのような処理をしたあと、その結果に「層に入る前の入力をそのまま足し算する」処理(Add)と、「足し算した結果の値の散らばり方をそろえる」処理(Norm)をセットで行う。これがAdd & Normと呼ばれる構成。", "eg": "文章を清書するとき、下書き(層の処理結果)だけを提出するのではなく、元のメモ(層の入力)もホチキスで一緒に添えて出す(Add)。そのうえで、文字の大きさや濃さを一定にそろえてから(Norm)提出する、という2段階の仕上げ作業に近い。", "terms": [["残差接続(スキップ結合、Residual Connection)", "層をいくつか飛び越えて、入力をそのまま先の層に足し込む近道"], ["レイヤー正規化(Layer Normalization)", "1つのサンプルの中の値どうしをそろえて、平均や散らばり方を整える正規化"], ["Add & Norm", "直訳は「足す」と「整える」。残差接続で足し算したあと、レイヤー正規化で整える一連の処理"]], "think": "なぜこの2つをセットで使うのかがカギ。Transformerは層をいくつも重ねる深いネットワークで、層を通るたびに学習の合図(どれだけ間違えたかの伝達)が弱まっていくと、手前の層まで届かず学習が進みにくくなる。残差接続(Add)は、入力をそのまま先へ運ぶ近道を作ることで、この合図が近道を通って小さくならずに手前まで届くようにする。ただし足し算を重ねていくと値の大きさがどんどんばらついていき、学習が不安定になりやすい。そこでレイヤー正規化(Norm)で、足し算のたびに値のばらつきをそろえ直し、次の層に渡す値を安定させる。この2つが揃うことで、深い層を積んでも学習の合図が消えず、かつ値も暴れずに済む。", "vs": "複数の観点のAttentionを組み合わせるのはマルチヘッドアテンション、位置情報を足すのは位置エンコーディング、ノードを無効化するのはドロップアウトであり、いずれもAdd & Normとは別の構成。", "why_asked": "Transformerの層の中身を「Attentionだけ」で理解して終わりにせず、それを支える補助的な仕組み(残差接続と正規化)まで理解しているかを問う。", "usecase": "非常に深いTransformerモデルを安定して学習させるための標準構成として、実装上ほぼ必ず組み込まれている。", "opt": ["正解。Addは残差接続(入力をそのまま足す近道)、Normはレイヤー正規化(値をそろえる仕上げ)を指し、深い層でも学習を安定させる。", "複数の観点のAttentionを同時に計算して組み合わせるのはマルチヘッドアテンションの仕組みであり、Add & Normとは別の構成。", "位置情報を入力に足し込むのは位置エンコーディングの役割であり、Add & Normが指す残差接続・正規化とは別の仕組み。", "ノードをランダムに無効化するのはドロップアウトの仕組みであり、Add & Normが指す残差接続・正規化とは別の工夫。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\">\n<text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\" font-family=\"sans-serif\">入力を足し込む近道(Add)と、そろえる仕上げ(Norm)</text>\n<rect x=\"130\" y=\"30\" width=\"80\" height=\"26\" fill=\"#3b82f6\" fill-opacity=\"0.3\" stroke=\"#3b82f6\"/>\n<text x=\"170\" y=\"47\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\" font-family=\"sans-serif\">Attentionなど</text>\n<path d=\"M 40 70 L 40 43 L 128 43\" stroke=\"#8892a4\" stroke-width=\"1.2\" fill=\"none\" marker-end=\"url(#gk_arrow4)\"/>\n<text x=\"40\" y=\"90\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" font-family=\"sans-serif\">入力</text>\n<path d=\"M 40 70 C 40 100, 200 100, 200 68\" stroke=\"#c9a04a\" stroke-width=\"1.4\" fill=\"none\" marker-end=\"url(#gk_arrow4)\"/>\n<text x=\"120\" y=\"112\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c9a04a\" font-family=\"sans-serif\">近道(残差接続)でそのまま足す</text>\n<path d=\"M 212 43 L 240 43\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#gk_arrow4)\"/>\n<circle cx=\"255\" cy=\"43\" r=\"12\" fill=\"none\" stroke=\"#6ab08d\"/>\n<text x=\"255\" y=\"47\" text-anchor=\"middle\" font-size=\"11\" fill=\"#6ab08d\" font-family=\"sans-serif\">+</text>\n<path d=\"M 267 43 L 285 43\" stroke=\"#8892a4\" stroke-width=\"1.2\" marker-end=\"url(#gk_arrow4)\"/>\n<rect x=\"287\" y=\"30\" width=\"45\" height=\"26\" fill=\"#6ab08d\" fill-opacity=\"0.3\" stroke=\"#6ab08d\"/>\n<text x=\"309\" y=\"47\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\" font-family=\"sans-serif\">Norm</text>\n<defs>\n<marker id=\"gk_arrow4\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\">\n<path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/>\n</marker>\n</defs>\n</svg>"}'),
  ('g-kentei-g-q38', '6. ディープラーニングの応用例',
   '医療画像などのセグメンテーションで代表的な構造で、画像を段階的に縮めて特徴をとらえたあと、今度は段階的に元の大きさへ戻しながら、縮める側の特徴をスキップ接続で対応する位置に橋渡しする、U字型のネットワークはどれか。',
   NULL::text,
   '["U-Net", "ResNet", "VGG", "GAN"]',
   0, '[0]', 'single',
   '{"asked": "セグメンテーションで使われる、U字型でスキップ接続を持つ代表的なネットワーク構造を選べるかを問われている。", "point": "「エンコーダで縮めてデコーダで戻す」だけでなく「戻す側に縮める側の特徴を橋渡しする」ならU-Net。", "kid": "写真の中で「ここが臓器」「ここが背景」のように、画素一つひとつに色分けするタスクをセグメンテーションという。U-Netはそのための定番の形。", "eg": "地図を一度ぼやけた縮小版にしてから、元の大きさの地図に描き戻すとき、縮小前の細かい道の情報を横から差し込みながら描き直すイメージ。差し込む線がスキップ接続。", "terms": [["U-Net", "名前の通りU字型のネットワーク。医療画像のセグメンテーションで生まれた"], ["スキップ接続", "エンコーダの浅い層の特徴を、デコーダの対応する層に直接橋渡しするつながり"], ["エンコーダ・デコーダ", "エンコーダは縮めて特徴を抽出する側、デコーダは戻して復元する側"]], "think": "なぜスキップ接続が要るのかがカギ。エンコーダで画像を何度も縮めると、「何が写っているか」という大まかな特徴は残るが、「どこに境目があるか」という細かい位置情報はどんどん失われる。デコーダで拡大するだけでは、その失われた位置情報は戻ってこない。そこでエンコーダの各段階の特徴をそのままデコーダの対応する段階に橋渡しすると、大まかな特徴と細かい位置情報の両方を使えるようになる。だから画素単位でくっきり塗り分けられる。", "vs": "ResNetの残差接続は同じ層の中で入力を出力に足すショートカットで、深い層の学習を安定させるためのもの。U-Netのスキップ接続は、エンコーダの層からデコーダの対応する層へ、離れた場所同士を橋渡しする点が違う。", "why_asked": "セグメンテーションの構造を、画像分類向けの構造（ResNet・VGG）と混同しやすいので、U字＋スキップ接続という形の特徴で見分けられるかを問われる。", "usecase": "医療画像でがんの領域を特定する、自動運転で道路と障害物を画素単位で塗り分けるなど、位置を細かく特定したい画像タスクで使われる。", "opt": ["正解。U-Net（ユーネット）は名前の通りネットワーク図を描くとU字になる。左半分（エンコーダ）で画像をだんだん縮めながら特徴をとらえ、右半分（デコーダ）でだんだん元の大きさに戻しながら位置情報を復元する。このとき左の各段階の特徴を、スキップ接続で右の対応する段階に直接橋渡しするのが最大の工夫。", "ResNet（Residual Network）は画像分類で使われる、層を飛び越える残差接続を持つ構造。層を深くしても学習が崩れにくくする工夫であり、セグメンテーション専用のU字構造ではない。", "VGG（Visual Geometry Group）は小さな畳み込みを何層も直列に積み重ねるだけの、画像分類向けの素朴な構造。縮めた特徴を戻すデコーダ部分を持たない。", "GAN（Generative Adversarial Network、敵対的生成ネットワーク）は生成器と識別器を競わせて新しいデータを作り出す仕組みで、画像を塗り分けるセグメンテーションの構造とは目的が違う。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">U-Netの形（エンコーダ→デコーダ＋スキップ接続）</text>\n\n<path d=\"M28 55 C28 24, 70 24, 70 40\" stroke=\"#c9a04a\" fill=\"none\" stroke-dasharray=\"3 3\"/>\n<path d=\"M70 40 C70 24, 214 24, 214 40\" stroke=\"#c9a04a\" fill=\"none\" stroke-dasharray=\"3 3\"/>\n<path d=\"M108 48 C108 32, 176 32, 176 48\" stroke=\"#c9a04a\" fill=\"none\" stroke-dasharray=\"3 3\"/>\n<text x=\"170\" y=\"22\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#c9a04a\">スキップ接続（縮める側の特徴を戻す側へ橋渡し）</text>\n\n<rect x=\"10\" y=\"50\" width=\"36\" height=\"40\" rx=\"3\" fill=\"none\" stroke=\"#3b82f6\"/>\n<text x=\"28\" y=\"73\" text-anchor=\"middle\" font-size=\"8\" fill=\"#e8eaf0\">入力</text>\n\n<rect x=\"54\" y=\"55\" width=\"32\" height=\"30\" rx=\"3\" fill=\"none\" stroke=\"#3b82f6\"/>\n<rect x=\"94\" y=\"59\" width=\"28\" height=\"22\" rx=\"3\" fill=\"none\" stroke=\"#3b82f6\"/>\n<rect x=\"130\" y=\"62\" width=\"24\" height=\"16\" rx=\"3\" fill=\"none\" stroke=\"#60a5fa\"/>\n\n<rect x=\"162\" y=\"59\" width=\"28\" height=\"22\" rx=\"3\" fill=\"none\" stroke=\"#6ab08d\"/>\n<rect x=\"198\" y=\"55\" width=\"32\" height=\"30\" rx=\"3\" fill=\"none\" stroke=\"#6ab08d\"/>\n<rect x=\"238\" y=\"50\" width=\"36\" height=\"40\" rx=\"3\" fill=\"none\" stroke=\"#6ab08d\"/>\n<text x=\"256\" y=\"73\" text-anchor=\"middle\" font-size=\"8\" fill=\"#e8eaf0\">出力</text>\n\n<path d=\"M46 70 L54 70\" stroke=\"#8892a4\" fill=\"none\"/>\n<path d=\"M86 70 L94 70\" stroke=\"#8892a4\" fill=\"none\"/>\n<path d=\"M122 70 L130 70\" stroke=\"#8892a4\" fill=\"none\"/>\n<path d=\"M154 70 L162 70\" stroke=\"#8892a4\" fill=\"none\"/>\n<path d=\"M190 70 L198 70\" stroke=\"#8892a4\" fill=\"none\"/>\n<path d=\"M230 70 L238 70\" stroke=\"#8892a4\" fill=\"none\"/>\n\n<text x=\"10\" y=\"102\" font-size=\"8\" fill=\"#8892a4\">縮める（エンコーダ）</text>\n<text x=\"200\" y=\"102\" font-size=\"8\" fill=\"#8892a4\">戻す（デコーダ）</text>\n<text x=\"142\" y=\"112\" text-anchor=\"middle\" font-size=\"7\" fill=\"#8892a4\">最小</text>\n<text x=\"170\" y=\"134\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">縮小と拡大の間を橋渡しすると細部の位置が復元できる</text>\n</svg>"}'),
  ('g-kentei-g-q39', '6. ディープラーニングの応用例',
   '物体検出で、予測した枠（バウンディングボックス）が正解の枠とどれだけ重なっているかを、「重なった部分の面積 ÷ 二つの枠を合わせた部分の面積」で表す評価指標はどれか。',
   NULL::text,
   '["IoU", "適合率", "再現率", "mAP"]',
   0, '[0]', 'single',
   '{"asked": "物体検出で、2つの枠の重なり具合を面積の比で表す指標を選べるかを問われている。", "point": "「重なり÷合わせた広さ」で枠の一致度を測るならIoU。", "kid": "予測した四角い枠が、正解の四角い枠とどれだけピッタリ重なっているかを数字にする方法。", "eg": "二枚の透明なシートに四角を描いて重ねたとき、重なった部分の広さを、二枚を合わせた広さ全体で割るイメージ。", "terms": [["IoU", "Intersection over Union、直訳は「共通部分 割る 合併部分」"], ["Intersection（共通部分）", "二つの枠が両方とも覆っている重なり部分"], ["Union（合併部分）", "二つの枠のどちらかが覆っている部分全体"]], "think": "なぜ「重なった面積」をそのまま使わず、「合わせた面積で割る」のかがカギ。重なった面積だけを見ると、大きな枠を適当に置くほど重なりやすくなってしまい、位置がずれていても数値が高く出てしまう。合わせた面積（Union）で割ることで、枠の大きさが違っても、無駄にはみ出た部分がある予測ほど数値が下がる。だから枠の位置と大きさの両方がぴったり合っているときだけ高い値になる。", "vs": "適合率・再現率は「検出できたかどうか」の判定結果を数える指標。IoUはその判定の元になる、1組の枠がどれだけ重なっているかを測る指標で、役割の階層が違う（多くの場合、IoUがある値以上なら「正しく検出できた」とみなしてから適合率・再現率を計算する）。", "why_asked": "適合率・再現率・mAPと並んで出てくるため、何を測る指標かを混同しやすい。IoUは枠の重なり、適合率・再現率は検出の当たり外れ、と役割で切り分けられるかを問われる。", "usecase": "物体検出モデルを評価するとき、検出できたと数えてよいIoUのしきい値（例えば0.5以上）を決めるのに使う。", "opt": ["正解。IoU（Intersection over Union、直訳は「共通部分 割る 合併部分」）は、予測の枠と正解の枠の重なり具合を0〜1の数値で表す。1に近いほど枠の位置と大きさがぴったり一致している。", "適合率（Precision）は「陽性と判定したもののうち実際に正しかった割合」で、枠の重なり具合そのものを測る指標ではない。", "再現率（Recall）は「本当に存在する正解のうちどれだけ見つけられたか」の割合で、こちらも枠同士の重なりを直接測るものではない。", "mAP（mean Average Precision）は、複数のクラス・複数の信頼度しきい値にわたって適合率を平均した、物体検出モデル全体の性能をまとめる指標。IoUは1組の枠を比べる部品として使われる。"], "calc": "①まず日本語で言うと: 重なった部分の面積を、二つの枠を合わせた部分の面積で割る。\n②小さい数字でやってみる: 予測の枠の面積が4、正解の枠の面積が4、重なっている部分の面積が2だとする。合わせた部分の面積（Union）は、それぞれの面積を足してから重なった分を1回だけ引く。4+4-2=6。よってUnion=6。重なった部分（Intersection）は2。IoU=2÷6=0.33（小数第3位を四捨五入）。\n③記号版: IoU = Intersection（共通部分の面積） ÷ Union（合併部分の面積） = 2 ÷ 6 ≈ 0.33。", "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 140\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">IoU＝重なった面積 ÷ 合わせた面積</text>\n\n<rect x=\"70\" y=\"30\" width=\"90\" height=\"70\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<text x=\"72\" y=\"26\" font-size=\"8\" fill=\"#60a5fa\">予測の枠</text>\n\n<rect x=\"120\" y=\"50\" width=\"90\" height=\"70\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/>\n<text x=\"212\" y=\"128\" font-size=\"8\" fill=\"#c9a04a\">正解の枠</text>\n\n<rect x=\"120\" y=\"50\" width=\"40\" height=\"50\" fill=\"#6ab08d\" opacity=\"0.35\" stroke=\"none\"/>\n<text x=\"140\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#e8eaf0\">重なり</text>\n\n<text x=\"170\" y=\"136\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">緑の重なりが大きいほど、枠の位置と大きさが一致している</text>\n</svg>"}'),
  ('g-kentei-g-q40', '6. ディープラーニングの応用例',
   '音声認識の前処理で使われる特徴量のうち、人の耳が高い音より低い音の違いを敏感に感じ取るという聴覚の特性（メル尺度）に合わせて、音声の周波数成分を変換した特徴量はどれか。',
   NULL::text,
   '["MFCC", "スペクトログラム", "ゼロ交差率", "one-hotエンコーディング"]',
   0, '[0]', 'single',
   '{"asked": "音声認識の前処理で、人の聴覚特性に合わせて周波数を変換した特徴量を選べるかを問われている。", "point": "人の耳の感度（メル尺度）に合わせた周波数変換ならMFCC。", "kid": "人間の耳は、低い音の違いにはよく気づくのに、高い音の違いにはあまり気づかない。MFCCはその耳の感じ方に合わせて音を数値にする方法。", "eg": "同じ100Hzの音の差でも、低い音域（100Hzと200Hz）では大きな違いに聞こえ、高い音域（5000Hzと5100Hz）ではほとんど同じに聞こえる。MFCCはこの「耳の物差し」を先に当てはめてから特徴を取り出す。", "terms": [["MFCC（Mel-Frequency Cepstral Coefficients）", "直訳は「メル周波数のケプストラム係数」。メル＝人の耳の感度に合わせた音の物差し。Mel-Frequency Cepstral Coefficients、直訳は「メル周波数のケプストラム係数」"], ["メル尺度", "人の聴覚の感度に合わせて周波数の間隔を調整した物差し"], ["ケプストラム", "音の周波数成分の大まかな形を取り出す信号処理の手法"]], "think": "なぜ耳の感度に合わせるのかがカギ。周波数をそのまま均等な物差しで測ると、人間には聞き分けられない高音域の細かい差にまで同じだけ計算資源を使ってしまい、逆に人間が敏感な低音域の差が埋もれてしまう。メル尺度で低音域を細かく、高音域を粗く測ることで、人間の聞こえ方に近い形で声の特徴を圧縮できる。だから少ない数値で、声の違いをよく表せる特徴量になる。", "vs": "スペクトログラムは変換前の生の周波数情報、MFCCはそこから聴覚特性に合わせてさらに圧縮・変換した特徴量という関係。CTCと混同しやすいが、MFCCは音声を数値化する入り口の処理、CTCはその後の学習で入力と出力の長さのズレを扱う処理で、担当する段階が違う。", "why_asked": "音声処理の特徴量として名前だけ暗記していると、何に基づいた変換かを問われたときに答えられない。人の聴覚特性（メル尺度）という根拠まで理解しているかを問われる。", "usecase": "スマートスピーカーや音声アシスタントの音声認識モデルの入力として、生の波形の代わりに使われる。", "opt": ["正解。MFCC（Mel-Frequency Cepstral Coefficients、直訳は「メル周波数のケプストラム係数」）は、音声の周波数成分を人の聴覚の感度（メル尺度）に合わせて変換し、声の特徴を少ない数値でまとめた特徴量。音声認識で長く使われてきた定番の入力。", "スペクトログラム（Spectrogram）は音声の周波数成分の強さを時間の経過とともに並べた図そのもので、聴覚の感度に合わせた変換は行っていない。", "ゼロ交差率（Zero Crossing Rate）は波形が0を横切る回数を数える単純な特徴量で、声か雑音かのおおまかな判定などに使うが、聴覚の感度には基づいていない。", "one-hotエンコーディングはカテゴリを「該当する1マスだけ1、他は0」のベクトルで表す方法で、音声波形の特徴量化とは別物。"]}'),
  ('g-kentei-g-q41', '6. ディープラーニングの応用例',
   '音声認識で、音声を細かく区切った入力フレームの数と、書き起こす文字列の長さが一致しないという問題を、「文字を出さない」ことを表す空白ラベルを挟むことで対応付けながら学習する手法はどれか。',
   NULL::text,
   '["CTC", "MFCC", "形態素解析", "TF-IDF"]',
   0, '[0]', 'single',
   '{"asked": "音声認識で、入力と出力の長さの不一致を空白ラベルで解決する学習手法を選べるかを問われている。", "point": "入力フレーム数と出力文字数のズレを「空白ラベル」で埋めて対応付けるならCTC。", "kid": "1秒の音声を100個の細切れ（フレーム）にしても、書き起こす文字は「こんにちは」の5文字しかない。100個と5個のズレをどう埋めるかを解決するのがCTC。", "eg": "駅のアナウンスを1コマずつ写真に撮ると何百枚にもなるが、実際に話した文はたった一文。何百枚のうちどこからどこまでが同じ1文字分の間なのかを、空白ラベルを使って整理するイメージ。", "terms": [["CTC（Connectionist Temporal Classification）", "直訳は「つながりを学ぶ、時間方向の分類」。Connectionist Temporal Classification、直訳は「時間方向をつなぐ分類」"], ["空白ラベル", "その入力フレームでは新しい文字を出さない、という特別な出力"], ["フレーム", "音声を一定の細かい時間幅で区切った1コマ分の単位"]], "think": "なぜ空白ラベルが要るのかがカギ。もし全フレームに必ず1文字を割り当てると、「こんにちは」の「こ」の音が10フレーム続いた場合、「こ」が10回連続で出力されてしまい、正しい文字列に戻せない。空白ラベルを使って「今は文字を出さない」フレームを作れるようにすると、同じ文字が続くフレームと、文字の切れ目のフレームを区別できる。区別できれば、連続した同じ文字と空白をまとめて元の短い文字列に戻せる。だから長さの違う入力と出力を対応付けて学習できる。", "vs": "MFCCは音声を特徴量に変換する入り口の処理、CTCはその特徴量の列から文字列を得るときの長さ合わせの処理で、パイプラインの段階が違う。Attention機構も入出力の対応付けに使われるが、CTCは空白ラベルで長さを揃える方式である点が異なる。", "why_asked": "音声認識のパイプラインのどの段階の技術かを混同しやすい。特徴抽出（MFCC）と、系列の長さ合わせ（CTC）を切り分けられるかを問われる。", "usecase": "音声をリアルタイムで文字起こしする音声認識システムの、出力の長さ調整の仕組みとして使われる。", "opt": ["正解。CTC（Connectionist Temporal Classification、直訳は「時間方向をつなぐ分類」）は、各入力フレームに「この文字」または「空白（何も出さない）」を割り当て、同じ文字の連続や空白をまとめることで、フレーム数と文字列の長さのズレを埋めながら学習する手法。", "MFCC（Mel-Frequency Cepstral Coefficients）は音声波形から特徴量を取り出す前処理であり、フレーム数と文字列長のズレを対応付ける仕組みではない。", "形態素解析は日本語の文を単語に区切る自然言語処理の前処理で、音声のフレームと文字列のズレを扱う話ではない。", "TF-IDFは文書中の語の重要度を数値化する手法で、音声認識の入出力の長さ合わせとは無関係。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 140\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">CTCの空白ラベルによる対応付け</text>\n\n<text x=\"10\" y=\"32\" font-size=\"9\" fill=\"#60a5fa\">入力フレーム</text>\n<g font-size=\"9\" fill=\"#e8eaf0\">\n<rect x=\"10\" y=\"38\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"25\" y=\"52\" text-anchor=\"middle\">こ</text>\n<rect x=\"44\" y=\"38\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"59\" y=\"52\" text-anchor=\"middle\">こ</text>\n<rect x=\"78\" y=\"38\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"93\" y=\"52\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#8892a4\">空白</text>\n<rect x=\"112\" y=\"38\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"127\" y=\"52\" text-anchor=\"middle\">ん</text>\n<rect x=\"146\" y=\"38\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"161\" y=\"52\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#8892a4\">空白</text>\n<rect x=\"180\" y=\"38\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"195\" y=\"52\" text-anchor=\"middle\">に</text>\n<rect x=\"214\" y=\"38\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"229\" y=\"52\" text-anchor=\"middle\">に</text>\n<rect x=\"248\" y=\"38\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"263\" y=\"52\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#8892a4\">空白</text>\n<rect x=\"282\" y=\"38\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"297\" y=\"52\" text-anchor=\"middle\">ち</text>\n</g>\n\n<path d=\"M25 58 L25 66 L59 66 L59 58\" stroke=\"#3b82f6\" fill=\"none\"/>\n<path d=\"M42 66 L42 82\" stroke=\"#3b82f6\" fill=\"none\"/>\n<path d=\"M127 58 L127 82\" stroke=\"#3b82f6\" fill=\"none\"/>\n<path d=\"M195 58 L195 66 L229 66 L229 58\" stroke=\"#3b82f6\" fill=\"none\"/>\n<path d=\"M212 66 L212 82\" stroke=\"#3b82f6\" fill=\"none\"/>\n<path d=\"M297 58 L297 82\" stroke=\"#3b82f6\" fill=\"none\"/>\n\n<text x=\"10\" y=\"80\" font-size=\"9\" fill=\"#6ab08d\">出力文字列</text>\n<rect x=\"27\" y=\"84\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#6ab08d\"/><text x=\"42\" y=\"98\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">こ</text>\n<rect x=\"112\" y=\"84\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#6ab08d\"/><text x=\"127\" y=\"98\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">ん</text>\n<rect x=\"197\" y=\"84\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#6ab08d\"/><text x=\"212\" y=\"98\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">に</text>\n<rect x=\"282\" y=\"84\" width=\"30\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#6ab08d\"/><text x=\"297\" y=\"98\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">ち</text>\n\n<text x=\"170\" y=\"122\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">同じ文字の連続と空白をまとめて、短い文字列に戻す</text>\n</svg>"}'),
  ('g-kentei-g-q42', '6. ディープラーニングの応用例',
   '「今日は晴れです」のように単語の間にスペースを入れない日本語の文を自然言語処理にかける前に、文を意味のある単語（形態素）の単位に区切る処理はどれか。',
   NULL::text,
   '["形態素解析", "TF-IDF", "LDA", "word2vec"]',
   0, '[0]', 'single',
   '{"asked": "日本語の文を単語単位に区切る前処理を選べるかを問われている。", "point": "スペースの無い日本語の文を単語の単位に区切るなら形態素解析。", "kid": "日本語は英語と違って単語の間にスペースを空けないので、コンピュータはどこからどこまでが1つの単語か分からない。それを区切ってあげる作業。", "eg": "「すもももももももものうち」を人間なら「すもも／も／もも／も／もものうち」と自然に区切れるが、コンピュータには最初から区切りが見えない。その区切りを教えるのが形態素解析。", "terms": [["形態素解析", "文を意味を持つ最小単位（形態素）に分割し、品詞も判定する処理"], ["形態素", "それ以上分けると意味が壊れる、単語より小さいこともある最小の意味単位"], ["分かち書き", "単語と単語の間にスペースを入れて区切って書くこと"]], "think": "なぜ日本語だけこの処理が要るのかがカギ。英語はスペースで単語が区切られているので、そのまま単語ごとに数えたり並べたりできる。日本語にはその区切りが最初から無いので、形態素解析で先に区切ってからでないと、他の自然言語処理（重要度計算、トピック推定、ベクトル化）がそもそもどこまでが1つの単語かを認識できない。だから日本語処理では最初の一歩として欠かせない。", "vs": "TF-IDF・LDA・word2vecはどれも、すでに単語に区切られたあとのデータを使って重要度や意味を計算する手法。形態素解析はそれより前の、区切ること自体を担当する前処理という違いがある。", "why_asked": "英語の自然言語処理の知識だけで日本語の処理をイメージすると、単語分割が要らないと誤解しやすい。日本語特有の前処理として形態素解析を知っているかを問われる。", "usecase": "日本語の文章を検索エンジンや感情分析にかける前段階として、ほぼすべての日本語NLPシステムで使われる。", "opt": ["正解。形態素解析は、文を「今日／は／晴れ／です」のように、意味を持つ最小単位（形態素）に区切り、それぞれの品詞も判定する処理。英語のように単語間にスペースがない日本語では、後続の処理の前に必ず必要になる前処理。", "TF-IDFは、区切られた単語が文書の中でどれだけ重要かを数値化する処理で、単語に区切ること自体は前提として済んでいる段階の話。", "LDA（Latent Dirichlet Allocation）は、区切られた単語の出現パターンから文書の話題（トピック）を推定する手法で、単語分割そのものではない。", "word2vecは、区切られた単語を意味の近さが分かるベクトルに変換する手法で、単語分割の後工程にあたる。"]}'),
  ('g-kentei-g-q43', '6. ディープラーニングの応用例',
   '文書の中である語が何度も出てくるほど重要とみなしつつ、「これ」「する」のようにどの文書にもまんべんなく出てくる語は重要度を割り引いて評価する、文書の特徴量化の手法はどれか。',
   NULL::text,
   '["TF-IDF", "word2vec", "LDA", "one-hotエンコーディング"]',
   0, '[0]', 'single',
   '{"asked": "文書内での語の出現頻度と、語の珍しさの両方から重要度を数値化する手法を選べるかを問われている。", "point": "「よく出るほど重要、でもどこにでも出る語は割り引く」ならTF-IDF。", "kid": "「です」「ます」みたいにどの文章にもよく出てくる言葉は、あまりその文章らしさを表さない。逆に、その文章にだけよく出てくる言葉は、その文章の中身を強く表している。TF-IDFはその考え方を数値にする。", "eg": "クラス全員が使う挨拶の言葉（「おはよう」）は誰の日記を見ても出てくるので手がかりにならないが、一人だけがよく書く言葉（「サッカー」）はその人の日記の特徴をよく表す、というイメージ。", "terms": [["TF-IDF（Term Frequency - Inverse Document Frequency）", "直訳は「語の頻度 × 文書頻度の逆数」。Term Frequency-Inverse Document Frequency、直訳は「語の出現頻度 かける 逆文書頻度」"], ["TF（語の出現頻度）", "その文書の中で、ある語が何回出てきたか"], ["IDF（逆文書頻度）", "その語が全体の文書のうちどれだけ珍しいか。多くの文書に出るほど値が小さくなる"]], "think": "なぜ出現回数だけでなく珍しさも掛け合わせるのかがカギ。出現回数（TF）だけで重要度を決めると、「です」「する」のようにどの文書にも大量に出る語が常に上位になってしまい、文書ごとの違いを表せない。そこにIDF（多くの文書に出るほど小さくなる値）を掛けると、ありふれた語の重要度は下がり、その文書に特有の語の重要度だけが高く残る。だから文書らしさを表す語を自動で浮かび上がらせられる。", "vs": "word2vecは語同士の意味の近さを表すのが目的で、文書内での重要度は測らない。LDAは文書全体を複数のトピックの混ざり方として捉える手法で、語1つずつの重要度計算とは目的の階層が違う。", "why_asked": "自然言語処理の特徴量化の手法（TF-IDF・word2vec・LDA）を横並びで覚えていると混同しやすい。重要度を測るのか、意味の近さを測るのか、話題を推定するのか、目的の違いを問われる。", "usecase": "検索エンジンで検索語と文書の関連度を計算するときや、文書の要約でどの語が重要かを判定するときに使われる。", "opt": ["正解。TF-IDF（Term Frequency-Inverse Document Frequency、直訳は「語の出現頻度 かける 逆文書頻度」）は、ある文書内でよく出る語ほど重要度を上げるTF（語の出現頻度）と、多くの文書に出回っている語ほど重要度を下げるIDF（逆文書頻度）を掛け合わせて、語の重要度を数値化する。", "word2vecは語を意味の近さが分かるベクトルに変換する手法で、文書ごとの語の重要度を測るものではない。", "LDAは文書を複数の話題（トピック）の混合として捉える手法で、語1つずつの重要度を割り引く計算はしない。", "one-hotエンコーディングは、語を「該当する1マスだけ1」のベクトルにするだけで、出現回数や希少さを一切考慮しない。"]}'),
  ('g-kentei-g-q44', '6. ディープラーニングの応用例',
   '1つの文書は、いくつかの話題（トピック）が混ざり合ってできていると仮定し、大量の文書からそれぞれのトピックがどんな単語の組み合わせでできているかを推定する手法はどれか。',
   NULL::text,
   '["LDA", "TF-IDF", "word2vec", "形態素解析"]',
   0, '[0]', 'single',
   '{"asked": "文書を複数トピックの混合として捉え、トピックごとの単語の傾向を推定する手法を選べるかを問われている。", "point": "文書を「複数トピックの混合」として捉えるならLDA。", "kid": "1つのニュース記事は政治の話だけでできているわけではなく、政治の話が7割、経済の話が3割のように話題が混ざっていることが多い。LDAはその混ざり具合と、それぞれの話題がどんな単語でできているかを、文書をたくさん読ませて逆算する。", "eg": "料理のレシピ本を大量に読み込ませると、「和食トピック（だし・醤油・味噌が多い）」「洋食トピック（バター・チーズ・オリーブオイルが多い）」のように、単語の組み合わせのパターンから話題を自動で見つけ出すイメージ。", "terms": [["LDA（Latent Dirichlet Allocation）", "直訳は「潜在的ディリクレ配分法」。潜在＝表に見えない話題を推定する。Latent Dirichlet Allocation、直訳は「潜在的なディリクレ配分」"], ["トピック", "文書に混ざっている、単語の出現パターンで特徴づけられる話題のまとまり"], ["潜在的（Latent）", "データに直接書かれてはいないが、裏に隠れて存在すると仮定するもの"]], "think": "なぜ「1つの文書＝1つの話題」ではなく「混合」で考えるのかがカギ。もし1文書に1トピックしか割り当てられないと、政治と経済の両方を扱う記事のような、複数の話題にまたがる文書をうまく表現できない。文書を複数トピックの混合比率として表すことで、どんな内容の混ざった文書でも、トピックの配分の違いとして柔軟に表現できる。だから多様な文書の中から共通する話題のパターンを自動で見つけられる。", "vs": "TF-IDFは語1つずつの重要度、word2vecは語同士の意味の近さを扱う手法で、どちらも文書全体を複数の話題の混合として捉える発想ではない点がLDAと違う。", "why_asked": "自然言語処理の中でも文書全体を要約的に捉える手法として、語単位の手法（TF-IDF・word2vec）と混同されやすい。捉える単位が語なのか、文書全体の話題構成なのかを問われる。", "usecase": "大量のニュース記事やレビューを、人手でラベル付けせずに自動で話題ごとに分類・要約するときに使われる。", "opt": ["正解。LDA（Latent Dirichlet Allocation、直訳は「潜在的なディリクレ配分」）は、1つの文書を複数のトピックの混ざり合いとみなし、それぞれのトピックがどんな単語をどれくらいの割合で含むかを、大量の文書から逆算して推定する手法。", "TF-IDFは1つの語がある文書内でどれだけ重要かを数値化する手法で、文書全体を複数のトピックの混合として捉えるものではない。", "word2vecは単語同士の意味の近さをベクトルの距離で表す手法で、文書の話題構成を推定するものではない。", "形態素解析は文を単語に区切る前処理で、話題（トピック）の推定とは別の段階の処理。"]}'),
  ('g-kentei-g-q45', '6. ディープラーニングの応用例',
   'word2vecは同じ単語であれば常に同じベクトルを割り当てるが、それとは違い「銀行の口座」と「川の銀行（土手）」のように文脈によって単語の意味が変わる場合に、その文脈に応じてベクトルを変化させる文脈化単語埋め込みの代表手法はどれか。',
   NULL::text,
   '["ELMo", "word2vec", "TF-IDF", "one-hotエンコーディング"]',
   0, '[0]', 'single',
   '{"asked": "同じ単語でも文脈によってベクトルが変化する、文脈化単語埋め込みの代表手法を選べるかを問われている。", "point": "同じ単語でも文脈に応じてベクトルが変わるならELMo。word2vecは常に固定。", "kid": "「明日、銀行に行く」の「銀行」と「川の銀行に座る」の「銀行（土手の意味）」は同じ文字でも意味が違う。word2vecはこの2つに同じベクトルしか割り当てられないが、ELMoは文全体を読んで文脈に合わせてベクトルを変える。", "eg": "同じ「かける」でも「電話をかける」「めがねをかける」「時間をかける」で意味が違う。文の前後を読んで初めて正しい意味が分かるのと同じことを、ELMoは単語のベクトルでもやってくれる。", "terms": [["ELMo", "Embeddings from Language Models、直訳は「言語モデルから得た埋め込み」"], ["文脈化単語埋め込み", "同じ単語でも前後の文脈によって変化するベクトル表現"], ["多義語", "文脈によって複数の異なる意味を持つ単語"]], "think": "なぜ文脈で変化させる必要があるのかがカギ。word2vecのように単語ごとに1つのベクトルを固定してしまうと、「銀行」の2つの意味のような多義語では、片方の意味しか表せずどちらかの文脈で誤った意味として扱われてしまう。ELMoは単語単体ではなく文全体を読んでからベクトルを計算するので、同じ単語でも周りの語に応じて異なるベクトルを出せる。だから多義語を文脈ごとに正しく区別でき、後段の自然言語処理の精度が上がる。", "vs": "word2vecは学習が終わると単語ごとに固定されたベクトルの表（辞書）を引くだけの手法。ELMoは毎回文全体をモデルに通して、その場でベクトルを計算し直す点が根本的に違う。", "why_asked": "word2vecとの違いを精度が高いか低いかの漠然とした比較で覚えていると、何が本質的に違うのかを問われたときに答えられない。固定ベクトルか、文脈で変わるベクトルかという構造の違いを問われる。", "usecase": "多義語が多い文章の意味理解が重要なタスク（質問応答や機械翻訳）で、word2vecより高い精度を出すための単語表現として使われた。", "opt": ["正解。ELMo（Embeddings from Language Models、直訳は「言語モデルから得た埋め込み」）は、文全体を読んだ上で、同じ単語でも前後の文脈に応じて異なるベクトルを与える手法。多義語を文脈ごとに正しく区別できる。", "word2vecは1つの単語には常に1つの固定ベクトルしか割り当てないため、文脈によって意味が変わる多義語を区別できない。", "TF-IDFは語の重要度を数値化する手法であり、単語をベクトル空間の意味として表すものではない。", "one-hotエンコーディングは語を「該当する1マスだけ1」のベクトルで表すだけで、意味の近さや文脈による違いを一切表現しない。"]}'),
  ('g-kentei-g-q46', '6. ディープラーニングの応用例',
   '画像を、格子状に並んだ固定サイズの小さな正方形（パッチ）に分割し、それぞれのパッチを文の中の単語のようなトークンとして扱ってTransformerに入力する画像認識モデルはどれか。',
   NULL::text,
   '["ViT", "CNN", "ResNet", "GAN"]',
   0, '[0]', 'single',
   '{"asked": "画像をパッチに分けてTransformerに入力する画像認識モデルを選べるかを問われている。", "point": "画像をパッチに切り分けてトークン列としてTransformerに入れるならViT。", "kid": "文章をTransformerに読ませるときは、文を単語ごとに区切って1列に並べる。ViTは画像も同じように、小さな正方形に切り分けてから1列に並べ、Transformerに単語の代わりのパッチの列として読ませる。", "eg": "写真をパズルのピースのように正方形に切り分けて、ピース同士の関係（このピースとあのピースは隣り合っている、似ている）をTransformerに考えさせるイメージ。", "terms": [["ViT", "Vision Transformer、直訳は「視覚のためのTransformer」"], ["パッチ", "画像を分割した固定サイズの正方形の断片。単語のトークンに相当する"], ["Attention", "トークン同士がどれくらい関係し合っているかを重み付けして捉える仕組み"]], "think": "なぜ画像をパッチに切ってから扱うのかがカギ。Transformerはもともと単語のようなトークンの列を入力として設計されており、画像の画素をそのまま1つずつ入力すると、画素数が多すぎて計算量が爆発してしまう。画像を大きめのパッチ単位にまとめてから1つのトークンとして扱うことで、トークンの数を現実的な数まで減らせる。数が減れば、Transformerが得意とするパッチ同士の関係の計算（Attention）を無理なく回せる。だから画像にもTransformerの仕組みをそのまま応用できる。", "vs": "CNNはフィルタを画像上でスライドさせて近くの画素同士の関係を段階的にとらえるのに対し、ViTは画像を最初からパッチの列に変換し、離れたパッチ同士の関係もAttentionで直接とらえられる点が違う。", "why_asked": "画像認識といえばCNNという固定観念があると、Transformerベースの手法を問われたときに見分けがつかない。CNNとViTで画像をどう扱うかの発想が根本的に違うことを理解しているかを問われる。", "usecase": "大量の画像データがある場合に、CNNより高い精度を出す画像分類モデルとして使われる。", "opt": ["正解。ViT（Vision Transformer、直訳は「視覚のためのTransformer」）は、画像を小さな正方形のパッチに切り分け、それぞれを単語のトークンのように並べた列としてTransformerに入力し、パッチ同士の関係をAttentionで捉えることで画像を認識する。", "CNN（Convolutional Neural Network、畳み込みニューラルネットワーク）は、フィルタを画像上でスライドさせながら近くの画素同士の関係をとらえる仕組みで、画像をパッチに切ってトークン列にする発想ではない。", "ResNetはCNNの一種で、層を飛び越える残差接続を特徴とする画像分類モデル。ViTのようにTransformerを使う構造ではない。", "GAN（Generative Adversarial Network）は生成器と識別器を競わせてデータを生成する仕組みで、画像認識のための構造ではなく目的が異なる。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 140\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">ViT：画像をパッチに分けてトークン列にする</text>\n\n<g stroke=\"#2a2f3f\" fill=\"none\">\n<rect x=\"30\" y=\"26\" width=\"90\" height=\"90\"/>\n<line x1=\"60\" y1=\"26\" x2=\"60\" y2=\"116\"/>\n<line x1=\"90\" y1=\"26\" x2=\"90\" y2=\"116\"/>\n<line x1=\"30\" y1=\"56\" x2=\"120\" y2=\"56\"/>\n<line x1=\"30\" y1=\"86\" x2=\"120\" y2=\"86\"/>\n</g>\n<text x=\"75\" y=\"122\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">画像をパッチに分割</text>\n\n<path d=\"M126 70 L160 70\" stroke=\"#8892a4\" fill=\"none\"/>\n<text x=\"143\" y=\"63\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">→</text>\n\n<g font-size=\"8\" fill=\"#e8eaf0\">\n<rect x=\"164\" y=\"60\" width=\"24\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#3b82f6\"/>\n<rect x=\"192\" y=\"60\" width=\"24\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#3b82f6\"/>\n<rect x=\"220\" y=\"60\" width=\"24\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#3b82f6\"/>\n<rect x=\"248\" y=\"60\" width=\"24\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#3b82f6\"/>\n<rect x=\"276\" y=\"60\" width=\"24\" height=\"20\" rx=\"2\" fill=\"none\" stroke=\"#3b82f6\"/>\n</g>\n<text x=\"232\" y=\"94\" text-anchor=\"middle\" font-size=\"8\" fill=\"#60a5fa\">パッチ＝トークンの列</text>\n<text x=\"232\" y=\"50\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">Transformerへ入力</text>\n\n<text x=\"170\" y=\"134\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">単語の代わりにパッチを1トークンとして扱う</text>\n</svg>"}'),
  ('g-kentei-g-q47', '6. ディープラーニングの応用例',
   '盤面から先の展開をランダムなシミュレーションで何度も試しながら、有望そうな手を優先的に深く読んでいく探索手法で、AlphaGoが自分自身と対局を繰り返す学習（セルフプレイ）と組み合わせて使ったのはどれか。',
   NULL::text,
   '["モンテカルロ木探索", "α-β法", "Q学習単体", "遺伝的アルゴリズム"]',
   0, '[0]', 'single',
   '{"asked": "ランダムなシミュレーションを使い、AlphaGoがセルフプレイと組み合わせた探索手法を選べるかを問われている。", "point": "ランダムなシミュレーションの結果で有望な手を絞り込む探索ならモンテカルロ木探索。", "kid": "囲碁は手の組み合わせが多すぎて、全部の手を最後まで読み切ることはできない。そこでとりあえずランダムに最後まで打ってみるのを何度も繰り返して、勝ちやすかった手を優先的にもっと深く読む、という方法をとる。", "eg": "迷路の分かれ道で、どちらに行けばゴールに近いか分からないとき、それぞれの道を何度も適当に走ってみて、ゴールにたどり着きやすかった道を重点的にもう一度試すイメージ。", "terms": [["モンテカルロ木探索", "Monte Carlo Tree Search。ランダムなシミュレーションの結果を使って有望な手を優先的に探索する手法"], ["セルフプレイ", "AIが自分自身を相手にして対局を繰り返し、その結果から学習すること"], ["シミュレーション", "実際に最後まで手を進めてみて、勝敗などの結果を確かめること"]], "think": "なぜランダムなシミュレーションを使うのかがカギ。囲碁は手の組み合わせが天文学的に多く、すべての手を最後まで正確に読み切ることは計算量的に不可能。そこで一部の手だけを深く正確に読む代わりに、多くの手をとりあえず最後まで適当に打ってみるシミュレーションで大まかに評価する。勝率が高かった手ほど、次はより多くのシミュレーション回数を割いて深く読み直す。この繰り返しで、限られた計算時間の中でも有望な手に絞り込んでいける。", "vs": "α-β法はミニマックス探索の枝刈りで、正確な読みを前提に無駄な計算を省く手法。モンテカルロ木探索はそもそも正確に読み切れない規模の探索で、ランダムなシミュレーションの統計から有望さを見積もる点が違う。", "why_asked": "AlphaGoの強さの理由を深層学習だけと誤解しやすいが、探索（モンテカルロ木探索）と学習（セルフプレイによる強化学習）を組み合わせた点が重要なので、両方を切り分けて理解しているかを問われる。", "usecase": "囲碁・将棋のようなゲームAIや、手の候補が膨大な計画問題で、限られた計算時間の中で良い手を絞り込むために使われる。", "opt": ["正解。モンテカルロ木探索（Monte Carlo Tree Search、MCTS）は、盤面から先の手をランダムに何度もシミュレーションし、その結果（勝率）をもとに有望な手ほど優先的に深く読み進める探索手法。AlphaGoはこれと、自分自身と対局を重ねるセルフプレイによる強化学習を組み合わせて、人間の棋譜に頼らず強くなった。", "α-β法は、ミニマックス探索（お互いが最善を尽くすと仮定して手を読む探索）のうち、明らかに選ばれない手を計算の途中で切り捨てて高速化する手法。ランダムなシミュレーションは使わない。", "Q学習単体は、行動価値（Q値）を試行錯誤で更新していく強化学習の基本手法で、盤面の探索木を作ってシミュレーションする仕組みそのものではない。", "遺伝的アルゴリズムは、複数の解の候補を親として組み合わせたり変異させたりしながら、より良い解を世代を重ねて探す最適化手法で、盤面の探索とは発想が異なる。"]}'),
  ('g-kentei-g-q48', '6. ディープラーニングの応用例',
   '強化学習のうち、「今の状態でこの行動をとったら次はどんな状態になり、どんな報酬が得られるか」を予測するシミュレータ（モデル）を持ち、それを使って先の展開を計画してから行動を決める方式はどれか。',
   NULL::text,
   '["モデルベース強化学習", "モデルフリー強化学習", "教師あり学習", "教師なし学習"]',
   0, '[0]', 'single',
   '{"asked": "環境のシミュレータを持ち、計画してから行動を決める強化学習の方式を選べるかを問われている。", "point": "環境の仕組みを予測するモデルを持って計画してから動くならモデルベース強化学習。", "kid": "強化学習には大きく2種類ある。先に頭の中でシミュレーションしてから動くタイプと、実際にやってみた結果だけを頼りに少しずつ賢くなるタイプ。前者がモデルベース。", "eg": "旅行の計画を立てるとき、地図（環境のシミュレータ）を見ながらこの道を行けばこう着くと頭の中で先読みしてから出発するのがモデルベース。逆に地図を持たず、実際に歩いてみた結果（迷った、早く着いた）だけをもとに次のルートを決めるのがモデルフリー。", "terms": [["モデルベース強化学習", "環境の仕組みを予測するモデルを持ち、それを使って計画してから行動する方式"], ["モデルフリー強化学習", "環境のモデルを持たず、実際の行動結果だけから学ぶ方式"], ["環境のモデル", "ある状態で行動したとき、次にどんな状態・報酬になるかを予測する仕組み"]], "think": "なぜモデルを持つかどうかで大きく分かれるのかがカギ。環境の仕組みを正確にシミュレーションできるモデルがあれば、実際に行動して失敗する前に、頭の中で何手も先まで試して一番良さそうな行動を選べるので、少ない実際の試行回数で済む。一方、環境が複雑すぎて正確なモデルを作れない場合は、モデルを作ろうとするとかえって不正確な予測に基づいた計画になり失敗しやすい。そのときは実際に行動した結果だけを地道に積み上げるモデルフリーの方が、遠回りでも確実に賢くなれる。だから環境をモデル化できるかどうかで、どちらの方式を選ぶべきかが決まる。", "vs": "教師あり学習・教師なし学習はどちらも報酬をもとに試行錯誤するという強化学習の枠組みそのものに含まれない別のカテゴリ。モデルベース・モデルフリーはどちらも強化学習の中の分類で、環境のシミュレータを持つかどうかで分かれる点が違う。", "why_asked": "AlphaGoの囲碁シミュレータのようにルールが明確な環境ではモデルベースが有効、ロボット制御のように環境が複雑な場合はモデルフリーが多い、という使い分けの理解を問われる。", "usecase": "囲碁・将棋のようにルールが完全に分かっている環境ではモデルベースの計画が有効。ロボットの実世界での制御のように環境を正確にモデル化しづらい場合はモデルフリーが使われることが多い。", "opt": ["正解。モデルベース強化学習は、環境の仕組み（次の状態と報酬がどう決まるか）を予測するモデルを持ち、実際に行動する前にそのモデルの中で先の展開をシミュレーションして計画を立ててから行動する方式。", "モデルフリー強化学習は、環境の仕組みを予測するモデルを持たず、実際に行動して得られた結果（報酬）だけをもとに、行動の価値や方策を直接更新していく方式。Q学習などが代表例。", "教師あり学習は、正解ラベル付きのデータから入力と出力の対応を学ぶ方式で、行動の結果として報酬を受け取りながら学ぶ強化学習の枠組みとは異なる。", "教師なし学習は、正解ラベルの無いデータからパターンやグループ分けを見つける方式で、報酬をもとに行動を学ぶ強化学習とは目的が異なる。"]}'),
  ('g-kentei-g-q49', '6. ディープラーニングの応用例',
   '通常の畳み込みを、「チャネルごとに空間方向だけを畳み込む処理」と「1×1畳み込みでチャネル方向だけを混ぜ合わせる処理」の2段階に分けることで計算量を大きく減らし、スマートフォンのような非力な端末（エッジAI）でも動くように設計された画像認識モデルはどれか。',
   NULL::text,
   '["MobileNet", "ResNet（残差接続を持つ画像分類モデル）", "VGG（畳み込みを直列に積むモデル）", "U-Net（医療画像セグメンテーションのモデル）"]',
   0, '[0]', 'single',
   '{"asked": "畳み込みを2段階に分けて軽量化した、エッジ端末向けの画像認識モデルを選べるかを問われている。", "point": "畳み込みを空間方向とチャネル方向の2段階に分けて軽くするならMobileNet。", "kid": "普通の畳み込みは「場所の特徴をとらえる」ことと「色や種類ごとの特徴（チャネル）を混ぜ合わせる」ことを1回の計算で同時にやっていて、計算量が多い。MobileNetはこの2つの仕事を分けて、順番にやることで計算量を減らす。", "eg": "料理で材料を切る作業と味付けを混ぜる作業を同時に1つの工程でやろうとすると大変だが、切る工程と混ぜる工程を分けて順番にやると、それぞれが単純な作業になって早く済む。Depthwise Separable Convolutionも畳み込みの仕事を2つの単純な工程に分けている。", "terms": [["MobileNet", "スマートフォンなど非力な端末向けに設計された軽量な画像認識モデル"], ["Depthwise Separable Convolution", "直訳は「深さ方向に分けられる畳み込み」。通常の畳み込みを2段階に分ける工夫"], ["エッジAI", "スマートフォンやセンサーなど、クラウドではなく端末側でAIの計算を行う仕組み"]], "think": "なぜ2段階に分けると計算量が減るのかがカギ。通常の畳み込みは、フィルタが「その場所の特徴をとらえる」ことと「複数チャネルの情報を1つに混ぜ合わせる」ことを同時に行うため、チャネル数とフィルタの大きさの掛け算ぶんだけ計算が必要になる。Depthwise Separable Convolutionでは、まずチャネルごとに別々のフィルタで場所の特徴だけをとらえ（チャネルを混ぜない）、次に1×1畳み込みでチャネル同士だけを混ぜ合わせる。2つの仕事を分けて別々にこなすことで、同時にやるより必要な掛け算の回数が大幅に減る。だから精度をあまり落とさずに計算量を減らせる。", "vs": "ResNetやVGGは精度を重視した通常の畳み込みを使うモデルで、計算量の削減そのものは主目的ではない。MobileNetは軽さを最優先にした設計思想が違う。", "why_asked": "CNN系のモデル名（ResNet・VGG・MobileNet）を横並びで暗記していると、それぞれの設計目的の違いを問われたときに答えられない。軽量化のための畳み込みの分解というMobileNet特有の工夫を理解しているかを問われる。", "usecase": "スマートフォンのカメラアプリのリアルタイム物体認識や、IoT機器・エッジデバイスに搭載する軽量なAIモデルとして使われる。", "opt": ["正解。MobileNet（モバイルネット）は、Depthwise Separable Convolution（直訳は「深さ方向に分けられる畳み込み」）という、畳み込みを2段階に分ける工夫で計算量を大きく減らし、スマートフォンなど計算資源の少ない端末でも動く軽さを実現した画像認識モデル。", "ResNetは層を飛び越える残差接続で深い層の学習を安定させるモデルで、通常の畳み込みを使っており、2段階に分けて軽量化する工夫は主眼ではない。", "VGGは小さな畳み込みを何層も直列に積み重ねるだけの、比較的パラメータ数の多いモデルで、軽量化を目的とした構造ではない。", "U-Netはセグメンテーション向けのU字型構造で、畳み込みの分解による軽量化ではなく、エンコーダ・デコーダとスキップ接続が特徴のモデル。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">通常の畳み込みとDepthwise Separable Convolution</text>\n\n<text x=\"10\" y=\"32\" font-size=\"9\" fill=\"#60a5fa\">通常の畳み込み（1回で同時に処理）</text>\n<rect x=\"10\" y=\"38\" width=\"46\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"33\" y=\"53\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">入力</text>\n<text x=\"60\" y=\"53\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">→</text>\n<rect x=\"68\" y=\"38\" width=\"180\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#3b82f6\"/>\n<text x=\"158\" y=\"53\" text-anchor=\"middle\" font-size=\"8\" fill=\"#e8eaf0\">場所の特徴＋チャネル混合を同時に</text>\n<text x=\"256\" y=\"53\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">→</text>\n<rect x=\"264\" y=\"38\" width=\"66\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#8892a4\"/>\n<text x=\"297\" y=\"53\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#e8eaf0\">計算量 多い</text>\n\n<text x=\"10\" y=\"90\" font-size=\"9\" fill=\"#6ab08d\">MobileNet（2段階に分けて処理）</text>\n<rect x=\"10\" y=\"96\" width=\"40\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"30\" y=\"111\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">入力</text>\n<text x=\"54\" y=\"111\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">→</text>\n<rect x=\"60\" y=\"96\" width=\"98\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#6ab08d\"/>\n<text x=\"109\" y=\"107\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#e8eaf0\">①チャネルごとに</text>\n<text x=\"109\" y=\"117\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#e8eaf0\">空間だけ畳み込む</text>\n<text x=\"162\" y=\"111\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">→</text>\n<rect x=\"168\" y=\"96\" width=\"98\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#6ab08d\"/>\n<text x=\"217\" y=\"107\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#e8eaf0\">②1×1畳み込みで</text>\n<text x=\"217\" y=\"117\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#e8eaf0\">チャネルを混合</text>\n<text x=\"270\" y=\"111\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">→</text>\n<rect x=\"276\" y=\"96\" width=\"54\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#8892a4\"/>\n<text x=\"303\" y=\"107\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#e8eaf0\">計算量</text>\n<text x=\"303\" y=\"117\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#e8eaf0\">少ない</text>\n\n<text x=\"170\" y=\"140\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">2つの仕事を分けると、同時にやるより掛け算の回数が減る</text>\n</svg>"}'),
  ('g-kentei-g-q50', '6. ディープラーニングの応用例',
   '同じシーンを様々な角度から撮影した複数の写真をもとに、その場所の3次元的な見え方を学習し、実際には撮影していない新しい視点からの画像を作り出す手法はどれか。',
   NULL::text,
   '["NeRF", "GAN", "VAE", "拡散モデル"]',
   0, '[0]', 'single',
   '{"asked": "複数視点の写真から3次元的な見え方を学習し、新しい視点の画像を作り出す手法を選べるかを問われている。", "point": "複数視点の写真から新しい視点の画像を作るならNeRF。", "kid": "同じ部屋をいろんな角度から撮った写真をたくさん見せると、AIがその部屋の立体的な見え方を覚えて、写真を撮っていない角度からの様子まで想像して描けるようになる、という技術。", "eg": "友達の部屋の写真を正面・横・斜めから何枚も見せてもらうと、見せてもらっていない角度（真上から見たらどうなるか）もなんとなく想像できるようになる。NeRFはこの想像をAIにやらせるイメージ。", "terms": [["NeRF", "Neural Radiance Fields、直訳は「ニューラルな放射輝度場」"], ["新視点合成", "撮影していない角度からの画像を作り出すこと"], ["放射輝度場", "空間内の各点が、見る方向によってどんな色・明るさに見えるかを表す情報"]], "think": "なぜ複数視点の写真だけから新しい視点の画像が作れるのかがカギ。1枚の写真だけでは、物の形や奥行き、光の反射の仕方は分からない。しかし同じ場所を異なる角度から撮った写真を何枚も見比べると、同じ点が角度によってどう色や明るさを変えるかのパターンが見えてくる。NeRFはそのパターンを、空間の各点ごとに「どの方向から見たらどんな色・明るさか」という関数としてニューラルネットワークに学習させる。学習が終われば、学習に使っていない新しい角度を関数に入力するだけで、その角度から見た画像を計算で作り出せる。だから撮影していない視点の画像も生成できる。", "vs": "GAN・VAE・拡散モデルはどれも訓練データ全体の傾向から新しいデータを生成する画像生成モデルだが、NeRFは特定の1つのシーンを複数視点の写真から学習し、その同じシーンの新しい視点を作ることに特化している点が違う。", "why_asked": "生成モデルの名前を並べて覚えていると、GAN・VAE・拡散モデルと同じ枠でNeRFもなんでも生成する技術と誤解しやすい。NeRFが特定シーンの新視点合成という別の目的の技術であることを問われる。", "usecase": "不動産のバーチャル内覧や、映画・ゲームでの3次元シーンの再現など、複数の写真から立体的な空間を作り出す用途で使われる。", "opt": ["正解。NeRF（Neural Radiance Fields、直訳は「ニューラルな放射輝度場」）は、複数視点の写真から、空間内の各点がどの方向にどんな色・明るさで光っているかをニューラルネットワークに学習させ、撮影していない新しい視点からの画像を生成する手法。", "GAN（Generative Adversarial Network、敵対的生成ネットワーク）は生成器と識別器を競わせて本物らしいデータを作る仕組みで、複数視点の写真から3次元的な光の情報を学習する仕組みそのものではない。", "VAE（Variational Autoencoder、変分オートエンコーダ）はデータを確率分布に圧縮してから復元するように学習する生成モデルで、複数視点写真からの新視点生成に特化した手法ではない。", "拡散モデルはノイズを段階的に取り除きながらデータを生成する手法で、NeRFのように複数視点写真から3次元の光の情報を学習するものではない。"]}')
) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei-g'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
